INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3373, 86, 84, 15, 15, '费尔南达在那些动荡的日子里安之若素。丈夫因她未经自己同意就决定了梅梅的命运而与她大吵一通，从那以后她便失去了与外界的联系。奥雷里亚诺第二曾想去搭救女儿，必要的话甚至会报警，但费尔南达给他出示了文件，上面写明女儿进修道院是出于自愿。实际上，梅梅签字时已经置身于铁栅的另一边，仍像被人领入时一样浑不在意。在内心里，奥雷里亚诺第二不相信那些证据的合法性，就像他不相信马乌里肖·巴比伦进院子是为了偷鸡，但这两个说法安抚了他的良心，使他没有歉疚地回到了佩特拉·科特斯的护庇下，继续摆宴欢闹、大吃大喝。费尔南达对市镇上的动荡漠不关心，对乌尔苏拉的预言充耳不闻，实施了自己的最后一步计划。她给将要成为初阶神职人员的儿子何塞·阿尔卡蒂奥写了一封长信，在信中说他姐姐雷纳塔因患黄热病已安息在天主的怀抱里。后来，她将阿玛兰妲·乌尔苏拉交给桑塔索菲亚·德拉·彼达照顾，专心与隐身的医生通信。她所做的第一件事就是为几经推迟的通灵手术定下最终日期。然而隐身的医生答复说鉴于马孔多的局势不稳定，暂时不宜做手术。她急不可耐同时又缺乏对外界的了解，居然在另一封信里向他们解释不存在什么时局不稳，一切都是自己小叔子胡闹的结果，说他最近心血来潮搞什么工会，就像以前开河通航时一样疯狂。到了炎热的星期三，他们还没达成共识，这时有人敲响家门，是一位老修女挎着一个篮子。为她开门的时候，桑塔索菲亚·德拉·彼达以为是一件礼物，想接过那个用绣花台巾盖着的篮子。但修女没让她拿过去，声称自己受命要严守秘密，亲手交与堂娜费尔南达·德尔·卡皮奥·德·布恩迪亚本人。那是梅梅的儿子。费尔南达以前的灵修导师在信中告诉她孩子出生于两个月前，由于他母亲不愿开口表达自己的意愿，只好用他外祖父的名字奥雷里亚诺为他命名施洗。费尔南达对命运的这一嘲弄愤怒不已，但在修女面前仍不动声色。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3339, 86, 50, 9, 9, '两天后，赫里内勒多·马尔克斯上校以叛国罪被判处死刑。奥雷里亚诺·布恩迪亚上校吊床高卧，对一切求情置若罔闻。行刑前夜，乌尔苏拉不顾禁止打扰的命令，到卧室去见他。她一身黑衣，带着罕见的肃穆神情，在会面的三分钟内一直保持站姿。“我知道你要枪毙赫里内勒多，”她庄严宣告，“我怎么做也拦不住。但是我告诉你：我以我父亲和我母亲的骨头发誓，以何塞·阿尔卡蒂奥·布恩迪亚的名义在上帝面前发誓，我只要一看见他的尸体，不管你在哪儿都会立刻把你揪出来，亲手杀了你。”没等他回答，她转头就走了，最后又丢下一句话：
