INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (4135, 44, 129, 149, 149, '她兴奋地捂着小嘴巴，躲在灌木丛后面，直到听到一串靠近的脚步声。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3361, 86, 72, 13, 13, '朋友们把他送回家，认为他算是履行了对妻子的承诺，没有死在情妇的床上。佩特拉·科特斯把他想要穿到棺材里去的那双漆皮靴打好鞋油，正四处找人要给他送去，这时却有人来告诉她说奥雷里亚诺第二已脱离危险。实际上他不到一个星期就康复了，十五天后举办了规模空前的筵席庆祝大难不死。他仍然住在佩特拉·科特斯家里，但每天都去看望费尔南达，有时还会留下来和家人吃饭，仿佛命运颠倒了事物，使他变成了情人的丈夫、妻子的情人。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3401, 86, 112, 20, 20, '阿玛兰妲·乌尔苏拉在孕期的昏倦中试图经营鱼脊骨项链生意，但除了梅尔塞德斯买了一打，再无他人光顾。奥雷里亚诺第一次发觉自己的语言天赋、百科全书般的博学，以及不需实地了解便能对远方事物了如指掌的罕见能力，都像自己女人的那匣珠宝一样毫无用处，尽管那时马孔多所有剩余居民的全部家资加在一起才抵得上那些珠宝的价值。他们奇迹般地勉强度日。阿玛兰妲·乌尔苏拉仍能保持良好心态，继续制造情趣花样，但她也养成了午饭后坐在长廊里的习惯，似睡非睡，若有所思。奥雷里亚诺则在一旁陪伴。有时两人会一直默默坐到傍晚，面对着面，彼此凝视，在静谧中相爱，并不比当初在癫狂中相爱减色。未来的不确定使他们的心绪回到了过去。他们看见自己置身暴雨时期失落的乐园，在院中的泥坑里玩水，捕杀蜥蜴挂到乌尔苏拉身上，拿她玩活埋游戏。这些回忆令他们恍然觉察，两人自从记事以来共度的时光总是十分幸福。追忆往事时，阿玛兰妲·乌尔苏拉记起一天下午她走进金银器作坊，母亲告诉她那个小奥雷里亚诺不是任何人的孩子，因为他是躺在一个篮子里顺水漂来的。这一说法似乎让人难以置信，但却没有任何真实的信息可以取代。在研究过所有可能性之后，唯一可以确定的是，费尔南达不是奥雷里亚诺的母亲。阿玛兰妲·乌尔苏拉倾向于认为他是佩特拉·科特斯的儿子，尽管她只是记得那女人的一些丑闻。这一推测使两人内心因恐惧而纠结。
