INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3397, 86, 108, 19, 19, '奥雷里亚诺发表蟑螂宏论的那天下午，讨论最后在那些卖身糊口的女孩们家里结束，那是一家充满假象的妓院，位于马孔多郊区。老鸨是个笑容可掏的好心妈妈，有着喜欢开门关门的怪癖。她不变的微笑仿佛在嘲弄那些信以为真的主顾，他们真的把只在想象中存在的一切当作了实在，因为这里连可摸可感的物品也同属虚假：家具坐上去便散架，唱机的空膛里藏了一只抱窝的母鸡，花园里全是纸花，日历上还是香蕉公司到来之前的年份，画框里的版画剪自从未出版过的杂志。连那些一听到老鸨招呼接客便从四邻赶来的羞怯小妓女，也同样当不得真。她们出现时并不打招呼，穿着五年前的印花小衣裳，怎样天真无邪地穿上也怎样脱下，在情爱的高潮则大声惊呼“好家伙，你看房顶都要塌了”，而一拿到那一比索五十铜板就立即去老鸨那里买面包和干酪。每到这时老鸨的笑容更加欢畅，因为只有她知道那些食物同样并非真实。奥雷里亚诺那时的世界始于梅尔基亚德斯的羊皮卷，终于尼格罗曼妲的床铺，他却在这家小妓院里找到了医治腼腆的猛药。最初他毫无进展，因为老鸨常在正销魂时走进，对双方的情爱魅力大加评论。但随着时间的推移，他最终对这世上的种种扫兴习以为常，甚至在一个最疯狂的夜里到待客的小厅中脱个精光，用他那难以想见的阳具托着个啤酒瓶逛遍整幢房子。他还创造出许多荒唐的花样，老鸨只是带着不变的微笑旁观，从未抗议，从未当真，一如赫尔曼试图点燃房子来证明其不存在，阿尔丰索拧断鹦鹉的脖子丢进刚开锅的香蕉木薯炖鸡里的时候。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3294, 86, 5, 1, 1, '大儿子何塞·阿尔卡蒂奥已经十四岁，脑袋四方，头发粗硬，和父亲一样固执任性。他发育迅速，体格健壮也像父亲，不过从那时就可以明显看出他缺乏想象力。他在马孔多建立前翻越山脉的路上孕育和诞生，当时父母在证实他身上没有任何动物器官之后曾一起感谢上天。奥雷里亚诺是在马孔多出生的第一个孩子，到三月就满六岁了。他沉默寡言，性格孤僻，在母亲腹中就会哭泣，来到人世时大睁着双眼。剪脐带的时候，他四下打量房间里的东西，好奇却毫无惊惧地观察人们的脸庞。随后，他任凭人们凑过来看，自己却无动于衷，专注地望着棕榈叶铺成的屋顶，那屋顶在雨水的巨大压力下似乎即将坍塌。乌尔苏拉没再想起他那全神贯注的目光，直到有一天，三岁的小奥雷里亚诺走进厨房，正赶上她从灶台端下一口滚烫的汤锅放到桌上。孩子在门口一脸困惑，说：“要掉下来了。”汤锅本来好好地摆在桌子中央，但孩子话音刚落，它便像受到某种内在力量的驱使，开始不可逆转地向桌边移动，掉到地上摔得粉碎。警觉的乌尔苏拉将此事告诉丈夫，但丈夫却将其解释为自然现象。他一向如此，对孩子们不闻不问，一方面因为他认为童年是智力尚未发育健全的时期，另一方面因为他总是沉浸于自己虚无缥缈的玄想中。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (4057, 44, 51, 69, 69, '第68章 野男人
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3293, 86, 4, 1, 1, '何塞·阿尔卡蒂奥·布恩迪亚对这一地区的地理情况一无所知。他只知道向东是无法逾越的山脉，山脉的另一侧是古老的城市里奥阿查，据他的祖父即第一位奥雷里亚诺·布恩迪亚讲，弗朗西斯·德雷克爵士 ① 曾在那里用大炮猎杀鳄鱼为乐，修补后填上稻草送给伊丽莎白女王。年轻的时候，何塞·阿尔卡蒂奥·布恩迪亚领着一群同伴，携带妻儿、牲口及所有生活用品，翻越山脉去寻找入海口。他们经过二十六个月的跋涉后决定放弃，为了避免原路返回便建立了马孔多。他对那条路不感兴趣，因为它只能将他带回到过去。向南是永远覆着绿色植被的泥塘和广阔的大沼泽，吉卜赛人都说没见过它的边界。大沼泽西边毗邻的是广袤无垠的水面，那里有皮肤娇嫩的鲸类，它们长着女人的头颅和身体，凭借巨大乳房的魔力让航行者迷失心智。吉卜赛人沿着这条水路航行了六个月，才找到邮政骡队经过的陆地。根据何塞·阿尔卡蒂奥·布恩迪亚的估计，与文明世界唯一可能的连接是北方的道路。于是他将当年和自己一起创建马孔多的同一群人用开荒装备和狩猎器械武装起来，把向导工具和地图塞进背包，开始了这场可怕的冒险。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3347, 86, 58, 10, 10, '蕾梅黛丝·布恩迪亚将成为狂欢节女王的消息在短短几个小时内飞越大泽区的边界，传至遥远到从未听说过她超凡美貌的地方，引发了一些人的担忧。在他们眼中，这一姓氏仍与反叛作乱联系在一起。这种担忧是毫无根据的。如果那个时期还有谁能做到与世无争，那便是日渐衰老、归于平凡的奥雷里亚诺·布恩迪亚上校，他渐渐失去了与家国现世的一切联系。他待在作坊里足不出户，小金鱼生意是联结他与外界的唯一纽带。停战初期被派来监视他家的士兵中有一个负责将成品拿到大泽区的村镇去贩卖，又带着金币和最近的消息回来。他说保守党政府获得了自由党人的支持，正在修改历书使每任总统可以在任一百年。他说政府终于与教廷达成协定，还有一位红衣主教从罗马被派来，头戴钻石冠冕，端坐在实心的黄金宝座上，而自由党的部长们都跪下来亲吻他的戒指并摄影存照。他说一家西班牙剧团经过首都时，女主唱在化妆室里被一群戴面具的人绑架，到了星期天却出现在共和国总统的消夏别墅里跳裸体舞。“别跟我谈政治，”奥雷里亚诺·布恩迪亚上校对他说，“咱们只管卖小金鱼。”坊间有流言说他对国家规状不闻不问是因为靠着作坊发了财，但传到乌尔苏拉耳中时只引发了她的讥笑。从她纯粹的实用主义观念出发，她实在难以理解上校的生意意义何在：用小金鱼换来金币，随即把金币变成小金鱼，如此反复，卖得越多就越辛苦，却只是为了维持一种不断加剧的恶性循环。实际上上校在乎的不是生意，而是干活本身。他必须全神贯注地投人，嵌上片片鱼鱗，用红宝石微粒镶鱼眼，锤出鱼鳃，添上尾鳍，再没有余睱为战后的失落而烦恼。这门精密的手艺极其耗费心神，令他在短短时间内比在整个战争年代衰老得更甚。不变的坐姿令他脊柱变形，精确到毫米的工艺使他视力受损，但不容丝毫分心的专注让他获得了心灵的平静。一群来自两个党派的老兵寻求他的支持，希望解决养老抚恤金的问题，因为政府一直许诺却从未落实，那是他最后一次涉入与战争相关的事务。“忘了这回事吧，”他劝道，“你们看我早就放弃了养老金，免得傻等到死受罪。”开始的时候，赫里内勒多·马尔克斯上校每到傍晚都来拜访，两人坐在大门口追忆过往。但阿玛兰妲无法忍受这个疲累的男人勾起自己的回忆，他的秃顶正将他引向未老先衰的深渊。于是她无理地令他处处难堪，终于他只在特殊情况下才登门，最后因瘫痪而彻底消失。沉默寡言的奥雷里亚诺·布恩迪亚上校对家中重新焕发的活力视若无睹，约略懂得幸福晚年的秘诀不过是与孤独签下不失尊严的协定罢了。每天浅睡一觉后五点起床，照例到厨房喝上一杯不加糖的咖啡，然后一整天关在作坊里，到下午四点才拖着一张矮凳走过长廊，如火如荼的玫瑰、明媚耀眼的暮色、阿玛兰妲的漠然——每到黄昏时分她的忧郁就发出开锅般清晰可闻的声响——都无法吸引他的注意。他在临街的门口坐下，直到蚊虫开始肆虐才回到家中。一次，有人鼓起勇气打扰了他的独处。
