INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (4110, 44, 104, 127, 127, '她的语气很平，像是在说一件与自己无关的事，
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (4124, 44, 118, 140, 140, '黎泱愕然地看向他，手里还拿着那块假体，头皮不由得一阵发麻。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3334, 86, 45, 8, 8, '他去了剧院。一家西班牙剧团将上演《狐狸的匕首》，那实际上是索里利亚的戏，但阿基莱斯·里卡多上尉下令改了名字，因为自由派把保守派称作哥特人 ① 。到入口验票的时候，奥雷里亚诺·何塞才发现阿基莱斯·里卡多带着两个荷枪实弹的士兵在搜查过往人流。“留神，上尉，”奥雷里亚诺·何塞提醒道，“敢对我动手动脚的人还没生出来呢。”上尉试图强行搜查，奥雷里亚诺·何塞因为没带武器，撒腿便跑。士兵们没有听从开枪的命令。“他是布恩迪亚家的人。”一个士兵解释道。上尉气急败坏，一把抢过步枪，跨到街心，瞄准了目标。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3358, 86, 69, 13, 13, '第13章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3356, 86, 67, 12, 12, '腐坏的屋顶在巨响中四分五裂，那男人来不及发出一声惊恐的叫喊，就已摔得头破血流，当即死在水泥地面上。从饭厅闻声赶来的外乡人匆忙抬走尸体，他们在死者的皮肤上闻到了美人儿蕾梅黛丝那令人窒息的气息。那气息深深渗入尸体，连头颅裂缝里涌出的都不是鲜血，而是一种饱含那神秘香气的琥珀色液体。于是他们明白美人儿蕾梅黛丝的气息仍在折磨死者，直到尸骨成灰也不放过。然而，他们并没有将这桩恐怖的事件与其他两个为美人儿蕾梅黛丝而死的男人联系起来。要等到另一个牺牲者出现，外乡人以及马孔多的许多老住户才会相信关于美人儿蕾梅黛丝的传说，即她发出的不是爱情的气息，而是死亡的召唤。证实这一点的机会出现在几个月后，那天下午美人儿蕾梅黛丝和一群女友一起去见识那些新奇的种植园。对马孔多的居民来说，这是一种新兴的消遣：在香蕉林中弥漫着湿润气息又杳无尽头的小径间漫步，那里的寂静仿佛刚刚从别处迁来，崭新未用，因此还不能正常传递声音。有时候在半米的距离内听不清别人说话，但在种植园另一头却能听得清清楚楚。这个新游戏为马孔多的少女带来欢笑和惊奇，引发惊恐与戏嘲，直到晚上她们还会谈起恍如梦境的散步经历。那里的寂静如此出名，乌尔苏拉也不忍剥夺美人儿蕾梅黛丝的乐趣，便同意她那天下午出门，但要衣着得体并戴上帽子。从少女们走进种植园的那一刻起，空气中便有致命的芳香满溢。在沟垄间劳作的男人感到自己被奇异的魔力所控制，面临着无形的危险，很多人甚至忍不住想要痛哭一场。美人儿蕾梅黛丝和她受惊的女友们险些落人一群凶暴的男人手中，好不容易才躲进附近的一户人家。没过多久四个奥雷里亚诺将她们救出，他们额上的灰烬十字引发某种对神明的敬意，仿佛那是门第等级的标志、免受伤害的印记。美人儿蕾梅黛丝没跟任何人说起有个男人趁着混乱在她腹部摸了一把，那只手更像是攫在悬崖边缘的鹰爪。那一瞬她惊愕地望着袭击者，那双绝望的眼睛像灼人的炭火印在她的心里。当晚，那男人在土耳其人大街吹嘘自己的勇气，炫耀自己的幸运，可几分钟后一匹马就从他胸前踏过，众多外乡人看着他在街上垂死挣扎，直到在自己吐出的鲜血里窒息。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3376, 86, 87, 15, 15, '门一关上，何塞·阿尔卡蒂奥第二就确信自己的战争已经结束。数年前，奥雷里亚诺·布恩迪亚上校曾对他讲起战争的魅力，并试图用个人经历中的无数实例来证明。他信以为真。但就在军人们对他视而不见的这个晚上，他回想起过去几个月的紧张局势，狱中的苦难，车站里的恐慌，以及满载死尸的火车，得出一个结论：奥雷里亚诺·布恩迪亚上校不过是个伪君子或懦夫。他不理解上校何必用那么多言辞来解释自己在战争中的感受，其实用一个词便足够：恐惧。相反，在梅尔基亚德斯的房间里，被神奇的光线、落雨的声音、隐身的感觉所保护，他找到了此前生命中一刻不曾有过的安宁，余下的唯一恐惧就是自己有可能会被活埋。他告诉了每天前来送饭的桑塔索菲亚·德拉·彼达，她答应只要自己一息尚存，就一定让他先死后葬。摆脱了所有恐惧，何塞·阿尔卡蒂奥第二得以专心钻研梅尔基亚德斯的羊皮卷，愈难索解兴致愈高。他习惯了雨声，两个月之后那已经无异于另一种静谧，唯一打扰他独处的就是桑塔索菲亚·德拉、彼达的进进出出。因此他恳求她把饭留在窗台上，再次关门上锁。家人已将他遗忘，包括费尔南达，她得悉军人们对他视而不见，便不觉得留他在那里有什么不妥。六个月的幽闭过去，军队已撤离马孔多，奥雷里亚诺第二想找人聊天打发等待雨停的时间，便打开门锁。门一开，剌鼻的气味扑面而来，这气味散发自屋里满地的便盆，每一个都已用过多次。何塞·阿尔卡蒂奥第二须发蓬乱形容难辨，对令人作呕的气味恍若不知，仍在反复研读天书般的羊皮卷。他身上闪耀着天使般的光芒。门开的时候，他只是微微抬了下头, 但就在那一瞥中，他的兄弟分明看到了曾祖父那种无可挽回的宿命在重演。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3379, 86, 90, 16, 16, '奥雷里亚诺第二扶她回到床上，像往常一样漫不经心地问她那句告别是什么意思。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3330, 86, 41, 7, 7, '奥雷里亚诺·布恩迪亚上校那时还能抽出时间，每两个星期发一份详细的通报到马孔多。只有一回，就在离开近八个月后，他直接写信给乌尔苏拉。一位特使把一封火漆封口的信送到家里，里面的—张纸上是上校工整的字迹：好好照顾爸爸，他就要死了。乌尔苏拉吃了一惊。“既然奥雷里亚诺这么说，奥雷里亚诺就有把握。”她说。她去请人帮忙把何塞·阿尔卡蒂奥·布恩迪亚带回卧室。他一如往昔身子沉重，而且栗树下的漫长岁月助长了他随意增重的本事，结果七个人协力都搬不动他，只能勉强把他拖到床上。身量巨硕的老人饱受淫雨骄阳的折磨，他一呼气，屋里的空气中便充溢着幼蘑、鸡蛋花以及经年凝聚的风雨的味道。次日清晨，床上不见了他的踪影。各个房间找过一遍之后，乌尔苏拉发现他又回到了栗树下。于是把他绑在床上。尽管气力仍在，何塞·阿尔卡蒂奥·布恩迪亚却无意反抗。他对一切都无所谓。他回到栗树下也不是出于本人意志，只不过源于身体的习惯。乌尔苏拉照顾他，喂他进食，给他讲奥雷里亚诺的消息。然而实际上，他很久以来还保持交流的对象只有普鲁邓希奥·阿基拉尔。普鲁邓希奥·阿基拉尔死后衰老已极，几近归于尘土，但仍每天两次找他聊天。他们谈起斗鸡。他们约好建立一个饲养优异品种的养殖场，倒不是为了享受他们已不再需要的胜利，而是为了在阴间沉闷的星期天聊作消遣。正是普鲁邓希奥·阿基拉尔为他擦洗，给他喂食，向他讲述一个陌生人的光辉业绩，那人名叫奥雷里亚诺，是战时的一名上校。一个人的时候，何塞·阿尔卡蒂奥·布恩迪亚在一个有无穷房间的梦中得到慰藉。他梦见自己从床上起来，打开房门，走进另一间一模一样的房间，里面有同样铸铁床头的床、同样的藤椅和后墙上同样的救难圣母像。从这一间又进入另一间一模一样的，如此循环，无穷无尽。他喜欢从一间走到另一间，仿佛漫步在镜廊中，直到普鲁邓希奥·阿基拉尔轻拍他的肩头。于是，他一间间回溯，渐渐苏醒，他原路折返，在现实的房间里与普鲁邓希奥·阿基拉尔相会。然而一天晚上，就在他被拖回床上两个星期之后，普鲁邓希奥·阿基拉尔在居中的房间里拍了他的肩膀，他便永远留在了那里，认为那才是现实的房间。第二天早上乌尔苏拉给他送饭的时候，看见一个男人从长廊走近。他个子矮小敦实，身穿黑呢大衣，一顶同样漆黑的巨大帽子直压至忧郁的眼际。“上帝啊，”乌尔苏拉想，“简直就是梅尔基亚德斯。”那是卡塔乌雷，比西塔西翁的兄弟，当年为了逃避失眠症而出走，一去再没有消息。当比西塔西翁问他为什么回来，他用他们庄重的语言答道：
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (4064, 44, 58, 77, 77, '第76章 卖肉计
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3968, 43, 50, 50, 50, '第49章 一章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3375, 86, 86, 15, 15, '那女人用同情的眼神打量着他。“这儿没有死人。”她说，“从你伯父，也就是上校那时候起，马孔多没发生过任何事。”何塞·阿尔卡蒂奥第二在到家前一路逗留过的三家厨房里都听到同样的回答：“没有死人。”他走过车站广场，看见油炸食品摊子的桌子已被码起，那里也没留下任何屠杀的痕迹。雨下个不停，街上空无一人，家家大门紧闭，看不出里面有丝毫生命的迹象。直到第一声弥撒钟声响起，才有了一丝人间气象。他敲开了加比兰上校家的门。一个他以前见过多次的孕妇，当面把门紧紧关闭。“他走了，”她惊恐地说道, “回他的老家了。”电网鸡笼的正门和往常一样，由两名地方警察守卫，他们身着雨衣，头戴橡胶头盔，在雨中仿佛石像。在偏僻的小巷里，安的列斯群岛的黑人齐声唱着安息日的赞美诗。何塞·阿尔卡蒂奥第二翻过院墙，从厨房进了家。桑塔索菲亚·德拉·彼达几乎没有提高声音。“别让费尔南达看见你，”她说，“她刚起床。”仿佛在完成一项早已领会的使命，她把他引到“便盆室”，收拾出梅尔基亚德斯快要散架的行军床，还在下午两点趁费尔南达午睡的时候从窗子递进一盘食物。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3324, 86, 35, 7, 7, '第7章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3311, 86, 22, 4, 4, '恢复不久的平静又被打破，这一次是梅尔基亚德斯的死。尽管这结果已在意料之中，但他死亡的情形却是人们事先所想象不到的。他归来后没几个月，便经历了一个急剧衰老的过程，很快就被归为那类无用的老翁，他们像幽灵般在卧室间步履蹒跚地游荡，高声追怀美好岁月却无人理睬，直到某天清晨死在床上才被人想起。起初，何塞·阿尔卡蒂奥·布恩迪亚出于对新奇的银版照相术和诺查丹玛斯预言的热情，还常常帮他的忙。但随着时间流逝，两人之间的交流日益困难，他最终被丢下孤独一人。他的视力和听力都在衰退，似乎把对话者混同于他在人类历史早期所结识的人物，回答他人问题时混乱使用多种语言。一天他忘了戴上夜里放在床边水杯里的假牙，从此索性不戴。乌尔苏拉着手扩建家宅的时候，特意为他盖了一个房间，紧挨着奥雷里亚诺的作坊，远离家中的忙乱喧闹, 有一扇阳光充沛的窗子和一个书架。她亲自把尘侵蛾蛀几近损毁的书籍、写满难解符号的脆薄纸张和装假牙的杯子一一摆上书架，那杯子里已经长出水生植物，开着纤小的黄花。梅尔基亚德斯似乎很喜欢这个新居，因为从此再没见他出屋，甚至在饭厅也不见他的踪影。他只去奥雷里亚诺的作坊，一待就是几个小时，在随身携带的羊皮纸上涂写谜一般的文字，那纸好像由某种干燥的材料所制，像千层饼似的裂开。他就在那里吃下比西塔西翁每天两次送去的食物，但最后那段日子他没了胃口，只吃蔬菜过活。很快他就显出素食者特有的孤清模样。他的皮肤上覆着一层柔软的苔藓，与那件不分季节永不离身的坎肩上滋生的相仿，他的呼吸间散发出熟睡动物的臭气。奥雷里亚诺最终忘了他的存在，沉浸在自己的诗行里，但有一次感觉听懂了他低沉独白中的只言片语，便留了心。实际上，他滔滔不绝说出的艰深话语中唯一能够辨别出来的，只是像锤击般不断重复的一个词“二分点二分点二分点” ① 。还有一个名字“亚历山大·冯·洪堡” ② 。阿尔卡蒂奥开始帮奥雷里亚诺做金银器活计的时候，曾尝试稍稍接近他。梅尔基亚德斯回应了这一沟通努力，不时吐出几个和现实毫不相干的卡斯蒂利亚语句子。然而一天下午，他好像突然间激情骤至，神采焕发。多年以后，面对行刑队，阿尔卡蒂奥将回想起梅尔基亚德斯为他朗读那一页页不可理解的文字时的颤抖，他自然是听不懂，但那铿锵的音调听起来仿佛教皇通谕的吟唱。随后，他很久以来第一次露出笑容，用西班牙语说道：“等我死的时候，请在我房间里烧上三天水银。”阿尔卡蒂奥告诉了何塞·阿尔卡蒂奥·布恩迪亚，后者试图获取更具体的信息，却只得到一句回答：“我巳经达到永生。”每当梅尔基亚德斯的呼气发臭，阿尔卡蒂奥便在星期四的上午带他去河里洗澡。他看来好了些。他脱下衣服，和年轻人一起没到水里，凭着神秘的方向感绕过深凹和危险地带。“我们是水做的。”他有一次这么说道。就这样过了很长时间，没人在家里见过他，除了那天晚上他令人感动地努力修理自动钢琴，以及他腋下夹着用毛巾包好的加拉巴木果壳瓢和油椰肥皂跟阿尔卡蒂奥去河里洗澡的时候。一个星期四，在叫他去河边之前，奥雷里亚诺听见他说：“我已经发热病死在新加坡的沙洲上。”那天他下水时弄错了路线，直到第二天早上才在下游几公里的地方被找到，尸身搁浅在一处明晃晃的河湾里，一只孤零零的秃鹫落在他肚子上。乌尔苏拉哭得比自己父亲去世时还伤心。何塞·阿尔卡蒂奥·布恩迪亚不顾她的惊诧和反对，拒绝为他下葬。“他永生不死，”他说，“他自己给出了复活的配方。”他重新燃起遗忘多时的炼金炉，放上一锅水银煮沸，一旁的尸体渐渐充满蓝色的泡沐。堂阿波利纳尔·摩斯科特鼓起勇气提醒他，溺死者不安葬的话会危害公共卫生。“哪儿的话，他根本没死。”何塞·阿尔卡蒂奥·布恩迪亚如此回答。熏香一般的水银烧煮已经持续七十二小时，尸体上开始迸裂出青紫色的花朵，伴随着轻微的爆响，家里充满恶臭。到了这个时候，他才同意下葬，但拒绝草率行事，而要用隆重的礼仪对待这位马孔多最大的恩人。这是镇上第一次也是参与人数最多的葬礼，一个世纪后格兰德大妈的葬礼或可与之媲美。他们将他葬在为公墓预留的空地中央，筑起一座坟墓，墓碑上铭刻着他们对他的唯一所知：梅尔基亚德斯。他们为他守灵九个夜晚。大家聚在庭院里喝咖啡、讲笑话、玩纸牌，阿玛兰妲趁着这混乱找到一个机会向皮埃特罗·克雷斯皮表白自己的爱情，后者几个星期前刚与丽贝卡正式订下婚约，并且开办了一家乐器和发条玩具店，就在当年阿拉伯人常常流连并用廉价的小玩意儿交换金刚鹦鹉的地方，也就是人们口中的土耳其人大街。意大利人那一头闪亮的鬈发常引得女人们情不自禁地赞叹，他觉得阿玛兰妲不过是个任性的小姑娘，没有把她的话当真。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3389, 86, 100, 18, 18, '对桑塔索菲亚·德拉·彼达来说，家里人口的减少理应成为她喘息的机会，这是她操劳半个多世纪后应得的。从未听见她有过一声怨言，这个沉默寡言、难以捉摸的女人在家中留下了美人儿蕾梅黛丝这样天使般的后代，何塞·阿尔卡蒂奥第二这样带着神秘的庄严气息的子嗣，她把孤独而沉寂的一生都用来抚养孩子，却几乎记不清他们是自己的子辈还是孙辈。她照料奥雷里亚诺如同己出，却不知道自己正是他的曾祖母。只有在这样一个家里才能想象这种情形，她竟然一直以来都铺席子睡在谷仓地板上，夜间忍受着老鼠的喧闹。一天晚上她突然感到黑暗中有人盯着自己，吓醒过来才发现是一条毒蛇从肚子上滑过。她从未告诉任何人，心里清楚假若让乌尔苏拉知道，一定会让自己睡她的床。那段时间，除非你到长廊里喊叫，家里人对任何事都浑然不觉，面包房里的忙碌，战争的惊扰，照料孩子的操劳，让人无暇再顾及他人的福祉。从未谋面的佩特拉·科特斯是唯一顾念她的人。她一直关心她是否有一双穿着出门的好鞋，会不会缺衣服穿，即使在靠彩票收入创造奇迹的时期依然如此。费尔南达进这个家门时有充分理由认为她只是一名终身女仆，她虽然不止一次听说那是丈夫的母亲，却实在难以置信，转眼就抛在脑后。桑塔索菲亚·德拉·彼达对这种低人一等的待遇并未流露出任何不满。相反，她给人的感觉是似乎很爱在角落里忙碌，一刻不停、一声不吭，把她从年轻时起一直居住的这座大宅打理得整洁有序。特别是在香蕉公司时期，家里更像一座热闹的军营，全亏了她才能运转正常。但在乌尔苏拉死后，桑塔索菲亚·德拉·彼达身上渐渐不见了往日非凡的勤劳、惊人的能干。这不仅仅是因为她已年迈力竭，还因为整个家在一夜之间进入了暮年。柔嫩的苔藓在墙上蔓延。杂草荆棘占满庭院之后又顶穿长廊的水泥地如同击碎一面玻璃，那裂缝间还涌出小黄花，与一个世纪前乌尔苏拉在梅尔基亚德斯放假牙的杯中发现的花朵一般无二。面对自然界的疯狂，桑塔索菲亚·德拉·彼达无睱也无力对抗，她整天往来于各卧室之间，好不容易赶走那些蜥蜴，可一到夜间它们又将泛滥。一天清早，她看到红蚂蚁离开千疮百孔的地基，穿过花园，沿着扶栏爬过已蒙上土色的秋海棠, 一直侵人到家中深处。她起初试图用扫帚杀灭，后来换成除虫剂，最后用上石灰，但第二天它们又在原地出现，杀不尽灭不绝。费尔南达忙于给儿女写信，对势不可当的毁灭大潮毫无察觉。桑塔索菲亚·德拉·彼达继续孤身作战，奋力抗击不让杂草侵入厨房，扯下墙上短短几小时内就会重生的蛛网，刮去白蚁蚁路。但当她看到连梅尔基亚德斯的房间也覆满灰尘和蛛网，看到纵然自己一天清理三遍拼了命地打扫，房间仍难逃荒凉破落的命运，呈现出当年只有奥雷里亚诺·布恩迪亚上校和那个年轻军官预见到的残败景象，便明白自己已然失败。于是她穿上多处磨损的主日正装、乌尔苏拉的一双旧鞋和阿玛兰妲·乌尔苏拉送她的长棉袜，把两三套换洗衣服打了个小包。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3342, 86, 53, 9, 9, '仪式仅仅持续了签署文件所需的一段时间。各方代表在补丁重重的马戏团帐篷正中一张简陋的桌前就坐，忠心追随奥雷里亚诺·布恩迪亚上校到底的军官围在四周。签字之前，共和国总统特使准备高声朗读降书，但奥雷里亚诺·布恩迪亚上校表示反对。“我们不要在形式上浪费时间了。”他说，看也不看就要在文件上签字。这时他手下的一位军官打破了帐篷里令人昏昏欲睡的沉默。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3322, 86, 33, 6, 6, '了解他身世秘密的人从这句反驳推想他自己也已知情，其实他一直蒙在鼓里。庇拉尔·特尔内拉，他的母亲，曾经在照相暗室里令他热血沸腾，对他而言，她是无法抗拒的诱惑，就像对当初的何塞·阿尔卡蒂奥和随后的奥雷里亚诺一样。尽管她已失去迷人的风采和笑声的魅力，他仍然循着她的烟味四处寻找她，找到她。开战前不久的一天中午，她比平时晚了些来学校接她的小儿子，阿尔卡蒂奥就在他用来午休、后来增设了锁镣的房间里等她。孩子在院中玩耍，他则躺在吊床上等待，焦渴得浑身颤抖，他知道庇拉尔·特尔内拉一定会从这里经过。她来了。阿尔卡蒂奥抓住她的手腕，想把她拉到吊床上。“我不能，不能，”庇拉尔·特尔内拉惊恐地说，“你不知道我多想让你高兴，但是老天在上，我不能这样。”阿尔卡蒂奥以家传的超凡力气揽住她的腰，肌肤相触让他感觉世界在融化。“别装圣女了，”他说，“说到底，全世界都知道你是个婊子。”可悲的命运令庇拉尔一阵恶心，她只得强行忍住。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3363, 86, 74, 13, 13, '事实上，即使何塞·阿尔卡蒂奥第二也无法将上校从幽闭中拉出来。女学生的侵扰已经耗尽他的耐心。尽管烧毁了蕾梅黛丝可爱的娃娃，他仍以卧室里蛀虫太多为借口，在作坊里支起吊床，除了去院中大小便以外再不离开。乌尔苏拉连跟他随便聊天都做不到。她知道他只顾着打制小金鱼，对盘里的食物看也不看就推到桌角，不在乎汤里油渐凝肉已冷。自从赫里内勒多·马尔克斯上校拒绝帮助他在晚年发动一场战争，他一天天变得愈加冷酷。他紧紧封闭起自己的内心，家人最后就权当他已不在人世。他再没有表现出任何人性的反应，直到有一年的十月十一日他出门去看马戏团游行。对奥雷里亚诺·布恩迪亚上校来说，那一天与他最后几年中的任何一天都没什么两样。清晨五点，他被墙外蟾蜍和蟋蟀的齐鸣惊醒。绵绵细雨从星期六开始就没有停歇，他即使不曾听到花园枝叶上的淅沥声，也能从自己骨头中的寒意里察觉到。他与往常一样裹着羊毛毯，穿着粗棉布衬裤。他还沿用旧年间的过时名谓称这裤子为“哥特佬衬裤”，但图舒适一直穿着。他套上紧身裤，但没有系上带子，也没有像往常那样在衬衣领口别上金纽扣，因为他准备马上洗澡。随后他把毯子披到头上好像兜帽，用手指捋捋脏污的髭须，就去院中小便。离太阳出来还有好些时候，何塞·阿尔卡蒂奥·布恩迪亚还在泡了雨水而腐烂的棕榈棚下打盹。上校像往常一样没看见他，也没听见他的鬼魂因热尿溅在靴子上被惊醒时所说的难解的言语。他决定晚些时候洗澡，不是因为寒冷和潮湿，而是因为十月里沉闷的雾气。回作坊的路上，他闻到桑塔索菲亚·德拉·彼达用来点燃炉灶的火捻的气味，便到厨房里等待咖啡煮开，好取走自己不加糖的那一杯。桑塔索菲亚·德拉·彼达像每天清晨那样问他那天是星期几，他回答说是星期二、十月十一日。他望着眼前这个被火光映成金色的沉稳女人，这个无论此时还是其他时刻都仿佛从未真实存在过的女人，忽然想起战事激烈时的另一个十月十一日，他因确信与他过夜的女人已死而突然惊醒。她的确死了，而他没有忘记那个日期，因为那女人在死前一小时曾问过他那天是星期几。在回忆中，这一次他仍未意识到往日的预感早已弃他而去。咖啡在沸腾，他纯粹出于好奇，不带丝毫怀旧的风险，想着那个他从未知晓姓名，从未见过她生前模样的女人，因为她是在黑暗中跌跌撞撞摸上他的吊床。然而，有太多女人以同样的方式进入他的生活，在他脑海中成为茫然一片, 他记不起是否就是她在初会的狂热中几乎淹没在自己的眼泪里，并且在死前不到一小时还信誓旦旦要爰他到死。他不再想她，也不再想其他女人，端着热气腾腾的咖啡走进作坊，打开灯来数点存在铁皮罐里的小金鱼。有十七条。自从决定不再出售，他仍然每天做两条，等凑够二十五条就放到坩埚里熔化重做。他干了一上午活计，全神贯注，心无旁骛，没有察觉到十点的时候雨下大了，有人在作坊前叫喊着关门别让水淹到家里；他甚至忘掉了自我，直到乌尔苏拉端着午饭进来并关了灯。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3300, 86, 11, 2, 2, '何塞·阿尔卡蒂奥和女郎没有观看砍头表演。他们去了她的帐篷，一边脱衣服一边急不可耐地亲吻。女郎卸下玻璃珠链，脱去浆过花边的层层衬裙和重重背心，以及无用的紧身胸甲，最后露出的身体几乎可以忽略不计。这是个瘦弱的小家伙，乳房刚刚发育，双腿还没有何塞·阿尔卡蒂奥的手臂粗，但她的坚定和热情弥补了身体的单薄。然而何塞·阿尔卡蒂奥无法回应她，因为他们身处公用帐篷，吉卜赛人拿着马戏道具走来走去忙着各自的事情，甚至会在床边停下掷上一把骰子。挂在帐篷中央木杆上的油灯照得四下通明。在爱抚的间歇，何塞·阿尔卡蒂奥赤着身子躺在床上伸了个懒腰，不知如何是好，而女郎还在努力诱导他。没过多久进来一个体态丰腴的吉卜赛女人，陪伴她的男人不属于马戏团，也不是村里的人。两人开始在床前脱衣服。那女人无意中看了何塞·阿尔卡蒂奥一眼，以狂热的目光打量着他那休憩中的壮观野兽。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3325, 86, 36, 7, 7, '“同意与否，悉听尊便，”上校说，“但这就是我的最后愿望。”从那时起预感不再光临。乌尔苏拉来探监的这一天，他反复思考，终于得出结论：或许这次死亡不会给出预告，因为它并非由运气决定，而是取决于刽子手的意愿。他被疖子折磨得整夜不眠。黎明将近，走道上传来脚步声。“来了。”他对自己说，不知为什么还想到何塞·阿尔卡蒂奥·布恩迪亚，而那老人这时也正在栗树下晦暗的晨曦中想着他。他心里没有恐惧，没有留恋，只有深深的怒气，愤怒于这人为的死亡害得他看不到那么多未竟的事情如何收场。门开了，卫兵端着一杯咖啡走了进来。第二天同一时间他还是一样，为腋下的疼痛而恼火，发生的事情也一般无二。星期四，他和卫兵们分享了奶味甜点，换上了穿着略紧的干净衣服和漆皮靴。到了星期五，仍未行刑。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3312, 86, 23, 4, 4, '丽贝卡被这解不开的谜团搅得忧心忡忡，便告诉了何塞·阿尔卡蒂奥·布恩迪亚。他责怪她竟然相信纸牌的预言，自己却在暗中翻遍衣柜和衣箱，挪开家具，掀起床板和地板，四处寻找那个骨殖袋。他想起自从房子扩建以后就再没见过，便偷偷找来那些泥瓦匠，其中一个承认，当时嫌那袋子碍事就把它砌在了夹壁里。他们耳朵贴在墙上四处侦听，听了好几天终于听到了低沉的咯啦咯啦声，于是凿开墙壁，发现骨殖仍完好无损地保存在袋中。当天他们便把骨殖安葬在一个没有墓碑的坟茔里，就在梅尔基亚德斯的坟墓旁。何塞·阿尔卡蒂奥·布恩迪亚回到家，心里卸下了如同对普鲁邓希奥·阿基拉尔的回忆一样的良心重负。经过厨房的时候，他吻了一下丽贝卡的额头。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3331, 86, 42, 8, 8, '第8章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3326, 86, 37, 7, 7, '由此，又一场战争爆发。罗格·卡尔尼塞罗上尉带着手下的六个士兵和奥雷里亚诺·布恩迪亚上校一起去里奥阿查，解救在那里被判处死刑的革命军将军维多利奥·梅迪纳。他们为了争取时间，本想沿着当年何塞·阿尔卡蒂奥·布恩迪亚创建马孔多时走过的道路穿越山区，但不到一个星期就确信那是不可能实现的行动。因此他们被迫取道危险的盘山路，随身装备除了行刑队配备的弹药再无其他。他们常常在村镇附近扎营，派出一个人乔装改扮一番，带着一条小金鱼在光天化日之下走进村子和潜伏的自由党人接头，次日清早那些人便出门打猎一去不回。当他们从一处山脊遥遥望见里奥阿查的时候，维多利奥·梅迪纳将军却已被处决。奥雷里亚诺·布恩迪亚上校的手下人推举他为加勒比海沿岸革命军统帅，挂将军衔。他接受了职务，但拒绝升衔，并发誓一天不推翻保守党政权就一天不变军衔。三个月后，他们成功武装起一千多人，但随即被打垮，幸存者逃到了东部边境。下一次消息传来的时候，他们已经离开安的列斯群岛，在贝拉角登陆。一份政府公告通过电文传遍全国，欢天喜地地宣布奥雷里亚诺·布恩迪亚上校的死讯。但是两天后，另一封通电几乎紧随前一封的余波，带来南方平原爆发起义的消息。奥雷里亚诺·布恩迪亚上校无所不在的神话由此而生。相互矛盾的消息同时传来，说他在比亚努埃瓦获胜，说他在瓜卡马亚勒被击败，说他被莫蒂隆印第安人生吃，说他死在大泽区的一个小镇，说他又在乌鲁米达起义。自由党的领导人那时正忙于谈判争取国会席位，称他为冒险主义者，完全不代表本党立场。国民政府将他归于土匪一类，悬赏五千比索买他的人头。经过十六次失利，奥雷里亚诺·布恩迪亚上校率领两千名武装精良的土著从瓜希拉出发，里奥阿查的守军在梦中惊醒，弃城而去。他在那里建立总部，对政府全面宣战。他从政府方面收到的第一份通告，以枪毙赫里内勒多·马尔克斯上校相威胁，要他在四十八小时内带人撤到东部边境。罗格·卡尔尼塞罗上校当时是驻地负责人，沮丧地将电文呈送到他面前，但他看过之后却出人意料的高兴。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3386, 86, 97, 17, 17, '乌尔苏拉一死，家里重又陷入荒废状态，连果断坚定、雷厉风行的阿玛兰妲·乌尔苏拉也没法扭转，多年以后她将出落成一位开明、欢快又新潮的女性，在世上稳稳占据一席之地。那时她打开门窗驱散颓气，修整花园，杀灭大白天就在长廊猖獗活动的红蚂蚁，努力恢复遗忘已久的好客氛围，可一切仍归于徒劳。费尔南达闭门幽居的执著成为一道坚不可摧的堤坝，遏阻住乌尔苏拉积蕴百年的洪流。她不仅拒绝在热风经过时开门，还命人用十字木条钉死窗户, 严格遵循娘家教导过着活死人的生活。她与隐身医生频繁的通信以失败告终。经过无数次拖延后，她在约定的日期和时间把自己关进卧室，头向北躺着，周身上下只裹了条白床单。到凌晨一点，她感到有人用浸过冰凉液体的手帕盖上自己的脸。等她醒来，阳光在窗前闪耀，她身上多了一道可怕的弧形伤口，从腹股沟一直延伸到胸前。但还没等静养期结束，她便收到隐身的医生表达迷惑的来信，信中称经过六个小时的检查，他们没有发现任何与她反复详尽描述的症状相符的疾病。实际上，这是她不按本来名称称呼事物的恶习造成的又一次混乱，通过心灵感应实施手术的外科医生们只查出她子宫下垂，建议用子宫托加以矫正。失落的费尔南达还希望得到更清晰的说明，但从未谋面的医生们不再回信。那个陌生的词语成了她心头的重负，她最终决定按下羞赧去询问究竟什么是子宫托，到这时才得知那位法国医生已在三个月前悬梁自尽，奥雷里亚诺·布恩迪亚上校的一位旧日同袍不顾全市镇人的反对将他下了葬。于是她寄希望于自己的儿子，何塞·阿尔卡蒂奥从罗马给她寄来了几个子宮托。她把附带的说明书背熟后立即丢进厕所，以免让人知晓自己隐痛的根源。这一防范未免多余，因为家中仅剩的几个活人对她根本未加在意。桑塔索菲亚·德拉·彼达浑浑噩噩地度过孤独的晚年时光，每日给家人准备所需的少许食物，几乎把全部精力都用来照料何塞·阿尔卡蒂奥第二。阿玛兰妲·乌尔苏拉继承了几分美人儿蕾梅黛丝的魅力，她把以前折磨乌尔苏拉的时间都用于做家庭作业，并开始在学业上显出聪颖和专注，令奥雷里亚诺第二重新燃起当年寄托在梅梅身上的希望。他答应按照香蕉公司时期形成的惯例，送女儿到布鲁塞尔完成学业，并在这一期望的激励下试图令毁于暴雨的土地重获生机。那时节在家中很少看到他的身影，他出现也只是为了看望阿玛兰妲·乌尔苏拉，时间已经把他变成费尔南达眼中的陌生人。小奥雷里亚诺渐渐步入青春期，沉浸在自己的世界里，变得难以捉摸。奥雷里亚诺第二曾寄希望于费尔南达人到老年会心肠变软，允许孩子踏入市镇上的生活，而那时不会再有人费心猜测他的出身。但奥雷里亚诺似乎甘守被囚的孤独，从未动念要去见识大门外的世界。乌尔苏拉命人打开梅尔基亚德斯房间的时候，他常去门前走动，往半掩的房门内张望。没人知道从何时起他和何塞·阿尔卡蒂奥第二成了朋友。奥雷里亚诺第二直到很久以后听男孩说起车站的屠杀，才发觉这段友情。那天有人在餐桌上感叹香蕉公司的撤离造成了市镇的败落，奥雷里亚诺当下予以反驳，言语间带着不属于他这个年龄的成熟。他的观点与常见的解释不同，他认为马孔多本是一个欣欣向荣、前程远大的地方，却被香蕉公司所扰乱、败坏、压榨，而且他们的工程师还引来暴雨，借此逃避履行对工人的承诺。他说得头头是道，在费尔南达眼中不啻对少年耶稣辩倒文士的渎神戏仿。他还以令人信服的精确细节描述了军队如何向被包围在车站的三千多工人开枪射击，如何将尸体装上两百节车厢的火车抛进大海。像大多数人一样，费尔南达接受的是官方说法，相信在车站没有发生任何事，因此一见孩子承袭了奥雷里亚诺·布恩迪亚上校的无政府主义思想便大为惊骇，立即命令他闭嘴。奥雷里亚诺第二却听出了那是自己孪生兄弟的说法。事实上，何塞·阿尔卡蒂奥第二尽管被当作疯子，却是家里最清醒的人。他教小奥雷里亚诺读写，领他入门研究羊皮卷，就香蕉公司对马孔多的影响灌输给他与众不同的看法，而多年以后奥雷里亚诺接触到外面的世界时，将会意识到那种说法显得荒谬不经，因为与历史学家在教科书中奉为圭臬的错误观点大相径庭。偏居一隅的小屋，无论热风、灰尘还是酷暑都无法侵及，两人身处其中，眼前都浮现出祖辈遗传的一幕记忆：远在他们出生以前，一位头戴鸦翼状礼帽的老人背对着窗户侃侃而谈。两人同时发觉屋内永远是三月，永远是星期一，于是明白了何塞·阿尔卡蒂奥·布恩迪亚并不像家人说的那样昏聩，实际上只有他足够清醒能洞察真相：原来时间也会失误和出现意外，并因此迸裂，在某个房间里留下永恒的断片。何塞·阿尔卡蒂奥第二把羊皮卷上费解的字母一一归类。这些字母单独看起来好像蛛爬虱走，以梅尔基亚德斯细密的字迹呈现出来则像挂在铁丝上的衣物，但他确信它们属于一个字母总数在四十七到五十三之间的字母表。奥雷里亚诺想起在英语百科全书上见过类似的图表，便拿到房间里与何塞·阿尔卡蒂奥第二的成果对照。结果完全相同。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3367, 86, 78, 14, 14, '如果不是阿玛兰妲不合时宜的死亡引发新的动荡，布恩迪亚家衰颓宅院中安静恬和的日子或许能持续很久。这一事件出乎所有人的意料。她虽然衰老又孤僻离群，但看起来依然结实挺拔，一如往常健康得好像磐石。自从那个下午她彻底拒绝赫里内勒多·马尔克斯上校并关在房中痛哭，再没有人能窥见她的内心。她在走出房门的那一刻，已经耗尽所有的眼泪。从此再没见她哭过，不管是在美人儿蕾梅黛丝升天的时候、奥雷里亚诺们遇害的时候，还是在奥雷里亚诺·布恩迪亚上校去世的时候。上校是她在这世上最爱的人，尽管直到他的尸体在栗树下被发现时她才表现出这一点。她去帮忙抬运尸体。她为他穿上军装，刮胡子，梳头发，给髭须上蜡，比他自己在光荣岁月中做得还好。没有人觉察到其中的爱意，因为他们都已见惯阿玛兰妲熟练地处理丧葬事宜。费尔南达惊诧于她对天主教与生活的关系一无所知，只懂得天主教与死亡的关联，仿佛那不是一种宗教，而只是一套丧葬习俗的手册。阿玛兰妲太过沉浸于自己的回忆，无法理解那些精微的教理。她人老了，心中的往事却依然鲜活。她听到皮埃特罗·克雷斯皮的华尔玆舞曲时，想哭的欲望一如年轻时涌上心来，仿佛流逝的时间和往日的教训都没留下痕迹。那些她借口受潮发霉而亲手扔进垃圾桶的乐谱纸带，依然在记忆中转动令琴槌敲击不停。她曾经试图在与侄子奥雷里亚诺·何塞窘迫的激情中将记忆淹没，试图在赫里内勒多·马尔克斯上校稳重阳刚的庇护下藏身，但都是枉然，连她老年时最绝望的举措也归于徒劳。还在小何塞·阿尔卡蒂奥被送去神学院之前三年，她为他洗澡时用的爱抚方式就不像是老祖母对待孙儿，更像是女人对待男人，如同传言中法国女郎们所做的那样，也如同十二岁和十四岁的她看见皮埃特罗·克雷斯皮穿着紧身舞蹈长裤随着节拍器的拍子舞动魔杖时想要对他做的那样。她有时为自己没能阻止这一悲惨的暗流而痛苦，有时愤怒得甚至用针扎手指，然而最令她痛苦最令她愤怒最令她心酸的却是爱情这棵芳香四溢却暗遭虫蛀的石榴树正渐渐走向死亡。就像奥雷里亚诺·布恩迪亚上校总想起战争一样，她不可避免地想起丽贝卡。她兄长可以看淡记忆，她却只能让它越发灼烫。多年间她对上帝的唯一祈求，就是不要让自己遭受惩罚死在丽贝卡之前。每次路过丽贝卡的家，看着房子日渐破败，她便心满意足地以为上帝垂听了她的祈求。一天下午，她在长廊里缝纫，突然冒出一个念头，确信自己会坐在这里，以同样的姿势并在同一束阳光下听见丽贝卡的死讯传来。她坐下等待，仿佛在等一封信。一段时间里，她拆下扣子又缝上，让等待变得不那么漫长难耐。家里没人注意到阿玛兰妲在为丽贝卡缝制一件精美的寿衣。后来，当奥雷里亚诺·特里斯特说看见丽贝卡形如鬼魂，皮肤遍布裂纹，头顶黄发稀疏，阿玛兰妲丝毫不觉惊奇，因为他描述的鬼魂和她很久以来想象的一模一样。她已作好决定要为丽贝卡的尸身装殓整容，用石蜡掩盖脸上的裂纹，再用圣徒像的头发为她做一顶假发。她将装扮出一具美丽的尸体，让它身着亚麻寿衣，并为棺材套上带紫色花边的丝绒衬面，还要举行最体面的仪式下葬到蛆虫的所在。她满怀怨恨地制定了计划，但心中一个念头令她战惊：纵然出于爱意，她也无法做得比这更好。但她没受困惑搅扰，继续完善各种细节，最后超越了丧葬专家的水准，不啻精通死亡仪轨的大师。在这可怖的计划中唯一没有考虑到的就是，她尽管曾向上帝祈求，仍有可能死在丽贝卡之前。事实上，事情就这样发生了。然而在最后的时刻，阿玛兰姐毫无受挫感，相反感到摆脱一切苦痛获得了自由，因为死神格外开恩，提前几年预先给出了通知。那是在梅梅上学后不久，一个炎热的中午，她正在长廊里缝纫时看见了死神。她当下认了出来，没有丝毫恐惧，因为她面前是一位穿蓝衫的长发女人，外表有些老气，与昔日帮忙下厨的庇拉尔·特尔内拉有几分相似。费尔南达很多次也在场，却没有看见她，尽管她是那样真实，那样有血有肉，好几回还请阿玛兰妲帮忙穿针。死神并未说到她何时会死，也没告知她是否会死在丽贝卡之前，只是让她从四月六日起开始为自己缝制寿衣。死神应许她尽可以做得精美复杂，但要像为丽贝卡缝制时一样认真，还说她会死在完工的当天傍晚，死时没有痛苦、没有恐惧也没有烦恼。为了尽可能拖延时间，阿玛兰妲订购了优等麻纱，亲手织布。她织得极其仔细，光做这项活计就耗费了四年时间。然后她开始绣花。随着完工日斯不可避免地临近，她意识到除非发生奇迹，才能将活计拖到丽贝卡死后，但千活时的专注令她得以保持必要的镇静来接受失败。也就在那时，她理解了奥雷里亚诺·布恩迪亚上校制成小金鱼随即又销毁的举动。世界不过是身外之物，她的内心不再为任何苦痛而波动。她深深遗憾没能在多年前获得这样的领悟，那时还来得及净化记忆，在崭新的光芒下重建世界，平静地唤回傍晚时皮埃特罗·克雷斯皮身上的薰衣草味道，并且将丽贝卡救出悲惨的境地，而这不是出于爱也不是出于恨，而是出于对孤独的深切理解。那天晚上梅梅言语中的怨恨令她惊讶，并非因为她在情感上受到触动，而是因为她感觉到自己的经历在另一个少女身上重演，她表面看来纯洁无瑕，实际上却已遭到怨恨的玷污。但那时她已完全接受命运，明知纠正的一切可能都不复存在，也并不觉得失落。做完寿衣成了她的唯一目标。她非但没像当初那样借助不必要的精工细作来拖延时间，反而加快了进度。一个星期前，她估计将在二月四日晚间缝上最后一针，便向梅梅提议将预定在次日举行的古钢琴音乐会提前。她没有说明原因，结果建议没被釆纳。于是，阿玛兰妲开始设法拖延四十八个小时，后来她甚至觉得死神也在助她一臂之力，因为二月四日晚上风雨大作破坏了发电厂。但到第二天早上八点，她还是在任何女人都不曾完成过的精美作品上添上了最后一针，并以最平常的口气宣告自己将死于当晚。她不仅告诉了家人，还通知了整个市镇，因为她相信可以通过最后一次造福世人的举动来补救自己卑微的一生，而在她看来没有什么事比给逝者带信更好。', 2381, 'length_limit', FALSE, 'selected', 4.8, '该场景以阿玛兰妲之死为轴心，浓缩其一生执念与孤独，通过缝制寿衣这一象征性行动结构叙事，将死亡预兆、时间流逝、人物心理和魔幻元素融为一体。其写法具有高度可迁移性：如何用具体物件承载抽象命运，如何在有限篇幅内完成人物回顾与主题深化，以及如何以平静语调处理死亡与和解。尽管依赖《百年孤独》整体语境，但核心情节和情感逻辑自足，对任何写作者都有借鉴价值。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 4.2, "distinctiveness": 5.0, "prose_quality": 5.0, "reference_value": 4.8, "scene_completeness": 4.8, "technique_value": 5.0}, "reference_reason": "该场景以阿玛兰妲之死为轴心，浓缩其一生执念与孤独，通过缝制寿衣这一象征性行动结构叙事，将死亡预兆、时间流逝、人物心理和魔幻元素融为一体。其写法具有高度可迁移性：如何用具体物件承载抽象命运，如何在有限篇幅内完成人物回顾与主题深化，以及如何以平静语调处理死亡与和解。尽管依赖《百年孤独》整体语境，但核心情节和情感逻辑自足，对任何写作者都有借鉴价值。", "reference_score": 4.8, "reference_status": "selected"}'::jsonb, '阿玛兰妲在孤独中缝制寿衣，等待丽贝卡之死以完成报复，却先迎来死神。死神命她为自己织寿衣，完工即死。她平静接受，用四年织布绣花，最终如期完成，并通知全镇，愿为逝者带信以赎一生。', '以内心独白贯穿生死，将仇恨、爱情与孤独织入日常缝纫。时间在回忆与现实中跳跃，死亡被赋予具象的仪式感。语言沉静而富有象征，细节精确，情感克制却浓烈，是展示人物命运与主题的典范。', '适合参考如何用日常动作承载重大主题、以死神意象推动结局、通过重复与细节制造宿命感。避免过度煽情，保持叙述的冷静与距离。', ARRAY['emotional', 'daily_life', 'mystery']::text[], ARRAY['emotional', 'daily_life', 'mystery']::text[], ARRAY['inner_monologue', 'foreshadow', 'contrast', 'show_dont_tell']::text[], ARRAY['inner_monologue', 'foreshadow', 'contrast', 'show_dont_tell']::text[], ARRAY['lyrical', 'restrained', 'dark', 'cinematic']::text[], ARRAY['lyrical', 'restrained', 'dark', 'cinematic']::text[], ARRAY['grief', 'heartache', 'relief']::text[], ARRAY['grief', 'heartache', 'relief']::text[], ARRAY['rain', 'light', 'night']::text[], ARRAY['rain', 'light', 'night']::text[], 'payoff', '{"emotion_tags": ["grief", "heartache", "relief"], "key_images": ["rain", "light", "night"], "narrative_func": "payoff", "scene_type": ["emotional", "daily_life", "mystery"], "style_summary": "以内心独白贯穿生死，将仇恨、爱情与孤独织入日常缝纫。时间在回忆与现实中跳跃，死亡被赋予具象的仪式感。语言沉静而富有象征，细节精确，情感克制却浓烈，是展示人物命运与主题的典范。", "style_tags": ["lyrical", "restrained", "dark", "cinematic"], "summary": "阿玛兰妲在孤独中缝制寿衣，等待丽贝卡之死以完成报复，却先迎来死神。死神命她为自己织寿衣，完工即死。她平静接受，用四年织布绣花，最终如期完成，并通知全镇，愿为逝者带信以赎一生。", "technique": ["inner_monologue", "foreshadow", "contrast", "show_dont_tell"], "usage_hint": "适合参考如何用日常动作承载重大主题、以死神意象推动结局、通过重复与细节制造宿命感。避免过度煽情，保持叙述的冷静与距离。"}'::jsonb, 'annotated', 'indexed', NULL, 3, TRUE, '2026-10-06T10:42:56.586149+00:00', '2026-10-06T10:57:09.857796+00:00', 'not_run', '', '', '{}'::jsonb);
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3346, 86, 57, 10, 10, '美人儿蕾梅黛丝被选为狂欢节女王。乌尔苏拉为曾孙女惊心动魄的美貌感到恐惧，却无法阻止她当选。此前，乌尔苏拉禁止她出门，除非是和阿玛兰妲一起去望弥撒，但是也要她用一块黑色头巾蒙住脸庞。那些并不虔敬的男人，那些在卡塔利诺店里化装成神甫主持渎神弥撒的男人，都涌向教堂，只为一窥美人儿蕾梅黛丝的脸庞，哪怕看上一眼也好。她的美貌传说伴着人们惊人的狂热在整个大泽区流传。他们等了很久才如愿以偿，事实上等不到那机会才是真正的幸运，因为他们中的大多数人终生再也无法安眠。让她露出面容的男人，那个外来者，尊严尽失，陷入自轻自贱的泥潭，数年后睡在枕木上被一辆夜行列车轧死。从他身着绿色丝绒上装和绣花马甲出现在教堂的那一刻起，就没有人怀疑他必定是受美人儿蕾梅黛丝的魔力所吸引，从远方而来，或许是从域外某个遥远的城市而来。他如此英俊，如此优雅沉静，如此风度翩翩，和他比起来皮埃特罗·克雷斯皮不过是个充大人的毛头小子。不少女人笑容中含着不满，嘟囔说他才配得上黑纱蒙面。他在马孔多不曾与任何人交谈。星期天清晨他如同神话中的王子一般现身，骑着配有银马镫和天鹅绒鞍褥的骏马，弥撒结束后便离开市镇。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3351, 86, 62, 11, 11, '“我是说，”她答道，“你就是那种把屁股说成斋戒日的女人。”从那天开始两人不再说话。实在迫不得已，她们会互留便条，或者对着空气传话。费尔南达感觉得到自己在家中不受欢迎，但并未因此稍减推行祖上规矩的决心。她取缔了家中谁饿了就自行去厨房吃饭的习惯，强制家人准时准点在饭厅的大桌上就餐，并铺好亚麻桌布，配上枝状烛台和银餐具。乌尔苏拉一向视为日常生活中最简单的事情变成庄严的仪式，由此形成了一种紧张气氛，沉默寡言的何塞·阿尔卡蒂奥第二首先对此表示反对。但这一仪式仍被固定下来，再加上晚饭前念诵玫瑰经的程序，都引起了左邻右舍的注意，很快就有风言风语传出，说布恩迪亚家的人不像一般人家那样坐在桌旁，而是把就餐变成了一场大弥撒。甚至乌尔苏拉的迷信也和费尔南达的迷信之间产生了冲突，前者更多源于个人的灵光一现，与传统关系不大，而后者则继承自父母，清晰明确，分门别类适用于不同场合。在乌尔苏拉耳聪目明的时候，她的意愿在家中还有一定影响，往日的一些习惯尚能勉强保留，但当她视力大减，被岁月的重负逼人角落，从费尔南达到来的那一刻启动的严酷变革便彻底完成，家庭的发展走向完全取决于她一人的决定。桑塔索菲亚·德拉·彼达按照乌尔苏拉的吩咐接手经营甜食和糖果小动物生意，这在费尔南达眼中有失体面，立刻被取消了。往日从清晨到入睡一直敞开的屋门，在午睡时段以阳光晒热了卧室为理由关闭，到后来也就不再打开。从村庄创建时起就挂在房梁上的芦荟枝和面包，被一座耶稣圣心神龛代替。奥雷里亚诺·布恩迪亚上校察觉了这些变化并对后果作出预言。“我们正在变成贵族老爷，”他抗议道，“这样下去，我们又得跟保守党政府开战了，不过这一次是要把国王推上台。”费尔南达极有分寸，避免与他发生冲突。但他的特立独行、他对一切社会成规的排斥，都令她在内心深处十分反感。他清晨五点必喝的咖啡，作坊里的杂乱无序，身上脱线的毛毯以及傍晚坐在门口的习惯都让她恼火。但她不得不忍受家里的这一不和谐音，因为她确信年老的上校是一头猛兽，只是因岁月消磨和理想幻灭而暂时平静下来，而一旦老人脾气失控就足以令家里天翻地覆。当丈夫决定用曾祖父的名字为他们的长子命名时，她没敢提出异议，因为她来到这个家不过一年。到第一个女儿出生时，她便直接表明了自己的决定，要用她母亲的名字取名——雷纳塔。那时乌尔苏拉已经想好要叫她蕾梅黛丝。经过一番紧张的争执，并由奥雷里亚诺第二笑吟吟地居中调停，新生儿以雷纳塔·蕾梅黛丝的名字受洗。但费尔南达仍叫她雷纳塔，而她丈夫一家及市镇上的人都叫她梅梅，即蕾梅黛丝的昵称。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3378, 86, 89, 16, 16, '费尔南达真的相信丈夫在等待天晴回到情妇那里。下雨的最初几个月，她担心丈夫会溜进自己的卧室，那样她只得不顾羞赧地坦诚，自从阿玛兰妲·乌尔苏拉出生以后她就失去了过夫妻生活的能力。正是出于这个原因，她急切地与隐身的医生通信，但总因频频发生的邮政事故而中断。最初几个月，常有消息说火车在暴风雨中出轨，隐身的医生也来信告知没有收到她的信件。晚些时候，她与从未谋面的医生失去联系后，已然在认真考虑戴上丈夫参加血腥狂欢节时用过的老虎面具，化名去找香蕪公司的医生作检查。但那时常有人带来有关暴雨的不幸消息，其中一个告诉她公司已经撤走医疗站，搬到了没下雨的地区。因此她的指望化为泡影。她只能一边期待雨天过去邮路恢复，一边自行设法缓解身上的暗疾，因为她宁死也不愿落在马孔多所剩唯一的医生，那个以驴草为食的古怪的法国人手里。她去找乌尔苏拉，相信她会知道某种可以缓解自己不适的方子。但她出于拐弯抹角的说话习惯，从不直接叫出事物的名称，不惜前后颠倒以减轻羞耻感，将分娩说成排出，将血漏唤作胃热，结果乌尔苏拉合乎情理地得出结论，认为她的病与子宫无关而属于肠胃问题，建议空腹服用甘汞。对于其他不这样过分正经的人来说，这病症其实并非难言之隐。如果不是身染暗疾，不是遗失信件，费尔南达才不会在乎下雨，因为她的一生中本就阴雨不停。她不曾改变作息时间，也不曾稍减繁文缛节。当桌子四脚还立在砖块上，椅子下还垫着木板以免吃饭时弄湿双脚，她依然不忘铺上亚麻桌布，摆设中国瓷器，吃晚饭时点亮烛台，因为她认为灾难不能成为不守规矩的借口。家里没有人再向街上张望。要是依着费尔南达，她一定会永远禁止这种行为，而且远在雨天开始前她就有此想法，因为在她看来门发明出来就是为了关闭，对街上动静的好奇则只属于青楼女子。然而，当听说赫里内勤多·马尔克斯上校的送葬队伍正经过时，她自己首先向外张望，结果透过半掩的窗户所见的景象令她痛苦不已，很长时间都为自己的软弱而悔恨。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3329, 86, 40, 7, 7, '赫里内勒多·马尔克斯上校不仅是奥雷里亚诺·布恩迪亚上校最信任的人，还被乌尔苏拉当作家中的一员。他体质虚弱，性格腼腆，生来文质彬彬，却更适合打仗，不适合从政，他的政治顾问们毫不费力就将他绕进了理论迷宫。不过他还是在马孔多实现了奥雷里亚诺上校梦寐以求的乡土平安，后者希望可以在此安心打造小金鱼以终老。他住在父母家里，但每星期总有两三次到乌尔苏拉这里吃午饭。他开始教奥雷里亚诺·何塞使用火器，对他提前进行军事训练，还在征得乌尔苏拉的同意后带他去军营生活了几个月，使他成长为男子汉。多年以前，赫里内勒多·马尔克斯几乎还是个孩子，就表白过对阿玛兰妲的爱意。她那时正沉浸在对皮埃特罗·克雷斯皮的单相思中，因而还嘲笑过他。赫里内勒多·马尔克斯在等待。有一回他从狱中给阿玛兰妲捎来一张小纸条，请她在一打细棉布手帕上绣上自己父亲的名字缩写，还捎去了工钱。一个星期后，阿玛兰妲去监狱给他送那一打绣好的手帕，钱也还了他，两人谈了几个小时的往事。“等我出去就和你结婚。”赫里内勒多·马尔克斯在告别时说道。阿玛兰妲笑了，但教孩子们读写的时候仍然想着他，希望为他寻回年轻时对皮埃特罗·克雷斯皮燃起的激情。每个星期六是探监的日子，她都去赫里内勒多·马尔克斯父母家，陪他们一同去监狱。其中一个星期六，乌尔苏拉看见她在厨房里等蛋糕出炉，要挑出最好的裹在专为此绣出的餐巾里。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3383, 86, 94, 17, 17, '奥雷里亚诺第二又把衣箱搬回了佩特拉·科特斯家，他此时只能勉强维持不致让家人饿死。用卖骡子彩票挣的钱，佩特拉·科特斯和他又买了别的牲畜，由此起家经营起彩票生意。奥雷里亚诺第二走街串户兜售彩票，那些彩票都是他自己用彩笔所画，以求更吸引人也更有说服力，但他或许没有觉察到有些人购买是出于感激，大多数人是出于怜悯。不过，即使是最富于同情心的购买者，也不会放弃花二十铜板得一头猪或三十二铜板得一头小牛的机会，每到星期二晚上都满怀希望，挤满佩特拉·科特斯家的院子，等待那个随机选出的孩子从袋子里抽出中奖号码。不久这里就变为每星期一次的集市，一到星期二傍晚院中便支起油炸食品摊子和饮料台，很多中奖者只要有人奏乐和上酒就当场杀掉牲畜，而奥雷里亚诺第二也不曾想到自己又拉起手风琴，加入因陋就简的饕餮比赛。这些宴席仿佛昔日盛况的寒酸翻版，也令奥雷里亚诺第二发现自己当年的活力荡然无存，昔日的昆比安巴舞高手雄风不再。他已然变了一个人。当年遭遇“母象”挑战时高达一百二十公斤的体重如今已减至七十八公斤，当年快活圆鼓的乌龟脸变成了鬣蜥脸 ① ，总是带着无聊和疲惫。然而对佩特拉·科特斯来说，他从来没有现在这样好，她或许是将他在自己心中激起的同情，以及贫困引发的患难与共当作了爱情。光秃秃的大床不再是纵情欢愉的地方，而变成私密的避难所。天花板上的照影镜已被卖掉换来做奖品的牲畜，引人绮念的锦缎和天鹅绒也已被骡子啃光，他们好像一对欲望全无的老夫老妻，直到夜深仍不能成眠，便将以前白白浪费的时间用在算账和摆弄零钱上。有时他们一直忙到听见第一声鸡叫，把一堆堆零钱搬来弄去，这里减一点儿那里加一点儿：这些用来哄费尔南达开心，那些用来给阿玛兰妲·乌尔苏拉买鞋，还有这些给桑塔索菲亚·德拉·彼达，她自从混乱时期起就再没穿过新衣服，这些用来给乌尔苏拉预备寿材，那些用来购买隔三个月每磅就涨上一铜板的咖啡，这些用来买越来越没甜味的白糖，这些用来买暴雨过后还没干透的木柴，那些用来买画彩票用的纸和彩墨，剩下的补上四月份那头小牛造成的亏损, 它在彩票卖光的时候突然患上红斑症，最后只侥幸落下一张牛皮。在这些无私的贫寒弥撒中，他们总把最多的一部分留给费尔南达，倒不是出于愧疚或善心，而是因为比起自己来他们更在乎她能否过得舒适。尽管两人都没察觉，他们其实都把费尔南达当成了求之而不可得的女儿，甚至有一次甘心情愿连喝三天玉米糊，只为了能让她买下一块荷兰桌布。然而，他们拼命劳作，努力省钱，想出无数花样，守护天使却依然在疲倦中沉睡，任他们怎样把硬币挪来移去也仅仅勉强糊口而已。因入不敷出而彻夜难眠时，他们不禁自问这世界是怎么了，为什么牲畜不再像当年那样疯狂繁殖，为什么钱从手中溜走，为什么不久前人们还肯为昆比安巴舞花上大沓钞票，现今却认为能得到六只母鸡的彩票定价十二铜板就是抢劫。奥雷里亚诺第二嘴上没有说，心里却相信不是世界的问题，而是佩特拉·科特斯神秘心灵的某个隐秘角落在暴雨期间出了毛病，使牲畜不再多产，令钱财滑不留手。他带着这个谜团，深入她的心灵反复探究，想要找寻利益却找到了爱情，他本想让她爱自己结果自己却爱上了她。而佩特拉·科特斯见他越发亲热也就越发爱他，于是在暮年将至时又重拾青春时代的迷信，相信贫穷是爱情的奴仆。想起往昔，两人都把荒唐的欢宴、离奇的财富和毫无节制的私情当作妨碍，一同感慨浪掷了多少时光才找到共享孤独的天堂。两人在无儿无女的多年相伴之后疯狂相爱，奇迹般从桌上到床上都如胶似漆无比幸福，直到年老体衰时仍像小兔一样嬉戏，像狗一般打闹。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3348, 86, 59, 10, 10, '由此可见，因美人儿蕾梅黛丝被封为女王，他的姓氏重新出现在公众视野而引发的担忧实际上缺乏事实根据。然而很多人并不这样想。市镇上的人们对迫近的悲剧一无所知，广场上人声鼎沸，一派欢天喜地的热闹景象。狂欢节达到疯狂的最高潮，奥雷里亚诺第二实现了扮成老虎的愿望，快乐地在狂热的人群中奔跑，因长久吼叫而嗓音嘶哑。就在此时，通往大泽区的路上出现了一队庞大的化装人群，他们抬着一座金光耀眼的花台，上面是一位人们所能想象出的最迷人的女子。一时间，马孔多本来心境平和的居民都摘下面具好看清这位神奇的美人，她头戴翡翠王冠，身披白鼬皮斗篷，俨然拥有货真价实的权柄，而不仅是闪光的缀片和皱纹纸打扮起来的女王。不乏目光敏锐的人觉察到这是一种挑衅行为。但奥雷里亚诺第二马上摆脱了困惑，宣布将新来者视作贵宾，并很聪明地让美人儿蕾梅黛丝和外来的女王在同一高台上就座。直到午夜时分，那些化装成贝都因人的外来者仍在热闹狂欢，并用绚丽的烟火和精彩的杂耍助兴，让人想起当年吉卜赛人的本领。突然间，就在节日的最高潮，有人打破了这微妙的平衡。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3366, 86, 77, 14, 14, '梅梅的女友中有三个美国姑娘，她们钻出电网鸡笼和马孔多的少女们建立了友谊。其中一个叫帕特里夏·布朗。出于对奥雷里亚诺第二慷慨招待的感谢，布朗先生也为梅梅敞开了自家的大门，邀请她参加星期六的舞会，那是美国佬和本地人共同参与的唯一活动。费尔南达知道后，暂时撇下阿玛兰妲·乌尔苏拉和隐身的医生，掀起一场轩然大波。“你想想，”她对梅梅说，“上校在坟墓里会怎么看呢？”显然，她是在寻求乌尔苏拉的支持。然而出乎所有人的意料，这位失明的老妇人认为梅梅参加舞会并和同龄美国姑娘交友没什么不妥，只要她立场坚定不改信新教就好。梅梅很好地领会了高祖母的意思，舞会后第二天都会提早起床去望弥撒。费尔南达依然反对，直到有一天梅梅告诉她美国人想听自己弹奏古钢琴。古钢琴再次从家中运出，送到布朗先生家中，在那里年轻的演奏家臝得了最真诚的掌声和最热烈的祝贺。从此以后，他们邀请她参加舞会、星期天去泳池游泳，还每星期请她吃一次午饭。梅梅学会了游泳且游得相当专业，还学会了打网球和吃弗吉尼亚火腿配菠萝片。从舞会、泳池到网球场，她很快发现英语对她不再是难题。奥雷里亚诺第二因女儿的进步兴奋不已，于是从一个游商手中买下配有许多彩图的六卷本英语百科全书送给她，她就在空闲时阅读。读书取代了以前的情爱八卦、和女友一起进行的密室探险，这倒不是因为有人强迫，而是因为她不再有兴趣讨论已经众所周知的所谓秘密。回想起醉酒的经历，她只当作幼稚的冒险，并兴致盎然地讲给父亲听，结果奥雷里亚诺第二比当事人更觉有趣。他笑得喘不过气来，“要是让你母亲知道了……”，每当她透露一个秘密他都会这样评论。他曾经让女儿答应以同样的信任告诉他初恋的进展，而梅梅也向他倾诉过自己对一个随父母来度假的美国红发男孩的好感。“好家伙，”奥雷里亚诺第二笑道，“要是让你母亲知道了……”但梅梅又告诉他那男孩已经回国，再也没有消息。她周全的考虑确保了家中的和睦。奥雷里亚诺第二有了更多时间花在佩特拉·科特斯那里，尽管身心都不允许他再像当年那般大宴宾客，但他仍不放过宴饮作乐的机会，再次拿出自己的手风琴，那琴上已经有些按键松动要用鞋带系住。在家里，阿玛兰妲织着那永远织不完的寿衣，乌尔苏拉则任凭自己被衰老引向幽暗深处，那里唯一可见的就是栗树下何塞·阿尔卡蒂奥·布恩迪亚的鬼魂。费尔南达巩固了自己的权威，在每月寄给儿子何塞·阿尔卡蒂奥的信里没再写一句谎言，只是略去了自己和隐身的医生通信一节。他们诊断出她的大肠里有个良性肿瘤，正准备运用通灵术实施治疗。', 1030, 'length_limit', FALSE, 'archived', 3.1, '该场景以概述性叙事推进时间，虽包含人物关系与文化冲突的细节，但缺乏戏剧性场景、对话或独特技巧的集中呈现，更多是情节过渡与背景交代，对写作者的迁移价值有限。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 3.0, "prose_quality": 3.5, "reference_value": 3.0, "scene_completeness": 3.0, "technique_value": 3.0}, "reference_reason": "该场景以概述性叙事推进时间，虽包含人物关系与文化冲突的细节，但缺乏戏剧性场景、对话或独特技巧的集中呈现，更多是情节过渡与背景交代，对写作者的迁移价值有限。", "reference_score": 3.1, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 3, TRUE, '2026-10-06T10:42:56.586149+00:00', '2026-10-06T10:57:09.857796+00:00', 'not_run', '', '', '{}'::jsonb);
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3306, 86, 17, 3, 3, '奥雷里亚诺向鸨母腿上的钱罐里投了一枚硬币，走进房间却不知道要做什么。混血姑娘露着母狗那样的乳头，赤着身子躺在床上。在奥雷里亚诺之前，这天晚上已有六十三个男人光顾过这里。经过这么多人进进出出，房间里的空气中混合了汗水和喘息的气味，变得污浊不堪。姑娘掀起湿透的床单，请奥雷里亚诺抓着另一侧。床单沉得像粗麻布一样。他们俩抓住两头拧水，直到恢复正常重量。他们又翻过席子，汗水从另一面往下淌。奥雷里亚诺盼着这活儿永不停息。他在理论上了解情爱是怎么回事，但还是双膝发软站立不稳，皮肤滚烫毛发悚然，仍忍不住要立刻排出腹中的重负。那姑娘收拾好床铺，要他脱掉衣服时，他慌忙解释：“是他们让我进来的。要我往钱罐里投二十铜板，还得动作快点儿。”姑娘明白了他的困惑。“如果你出去的时候再放二十铜板，就可以多待一会儿。”她温柔地说。奥雷里亚诺脱了衣服，羞惭至极，总想着自己的裸体没法和哥哥相比。不管那姑娘怎样努力，他都愈加没有反应，愈觉孤独异常。“我会再放二十铜板。”他绝望地说。姑娘默默地向他谢过。她的背上都已磨破。她瘦得皮包骨，呼吸间流露出无尽的疲惫。两年前，在离这里很远的地方，她睡前没有熄灭蜡烛，醒来已经身处火海。她和抚养她长大的祖母一起居住的房子化作灰烬。从此，祖母带着她走遍各个村镇，让她以二十铜板的价钱卖身，以挣回烧毁的房屋。根据姑娘自己估算，按每夜接待七十个男人计还需要干十几年，因为她还需另付二人的旅费、饮食费以及抬摇椅的印第安人的工钱。鸨母第二次敲房门的时候，奥雷里亚诺离开了房间，什么也没做，惶惶然只想哭泣。当天夜里他想着那姑娘无法入睡，有欲望也有怜悯。他感到无可抑制的冲动，要去爱她和保护她。到天亮的时候，他已被失眠和狂热折磨得疲惫不堪，终于作出庄严的决定，要与她成婚并把她从所欠祖母的债务中解救出来，夜夜享受她给予七十个男人的满足。但上午十点他赶到卡塔利诺店里的时候，姑娘已经离开镇子。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3309, 86, 20, 4, 4, '安帕萝·摩斯科特与丽贝卡.布恩迪亚之间突然萌生的友情燃起了奥雷里亚诺心中的希望。他一直想着蕾梅黛丝，深受折磨，却总找不到机会见面。当他跟最亲密的朋友马格尼菲科·比斯巴勒和赫里内勒多·马尔克斯——建村元老们的儿子，名字与父亲相同——在镇上散步时，曾无数次用渴望的目光在缝纫店中寻找，但看见的只是她的姐姐们。安帕萝·摩斯科特在家中的出现对他而言不啻一个预兆。“她一定会一起来，”奥雷里亚诺低声对自己说，“她一定会来。”他重复了无数次，如此坚信不疑，终于一天下午，他在作坊里组装一条黄金小鱼的时候，感到她回应了自己的呼唤。不一会儿，他果然听到一个童稚的声音，于是抬起头来一看，心脏因惊恐而停止了跳动：小女孩穿着粉红薄纱裙和白色小靴子站在门前。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3310, 86, 21, 4, 4, '她做到了。只是时机不对，因为家里已经失去往日的平静。丽贝卡那般喊叫已经无法保守秘密，阿玛兰妲发现了她的痴恋后开始发烧。她也在为没有回应的爱情而饱受折磨。她把自己关在浴室里，写下一封封狂热的信，以摆脱没有希望的激情带来的折磨，然后把信深藏在衣箱内。乌尔苏拉同时照顾两个病人，几乎忙不过来。她费尽心机长时间询问，也没能问出阿玛兰妲委靡的缘由。最终，她又灵机一动，撬开衣箱，便发现了用玫瑰色丝带系好的信，信内塞满新鲜的百合花瓣，信上泪痕未干，封封都写给皮埃特罗·克雷斯皮，但从未寄出。乌尔苏拉眼含愤怒的泪水，诅咒自己动念购买自动钢琴的那个时刻，并取消了刺绣课程，下令进入没有死人的丧期，直到女儿们死心断念为止。何塞·阿尔卡蒂奥·布恩迪亚已经改变对皮埃特罗·克雷斯皮最初的看法，十分欣赏他对音乐器械的灵活掌握，于是试图干预, 却无济于事。庇拉尔·特尔内拉告诉奥雷里亚诺，蕾梅黛丝已经作好结婚的准备，他意识到这个消息会给父母带来新的痛苦。但他还是选择面对现实。何塞·阿尔卡蒂奥·布恩迪亚和乌尔苏拉被郑重其事地请到客厅，漠然听着儿子的宣告。但听到那未婚妻的名字时，何塞·阿尔卡蒂奥·布恩迪亚气红了脸。“爱情是瘟疫！”他咆哮着，“有那么多漂亮又正派的女孩，你偏偏要娶敌人的女儿。”乌尔苏拉却赞成儿子的选择。她坦承自己对摩斯科特家七姐妹的好感，说她们漂亮、能干、端庄又有教养，称赞儿子有眼光。何塞·阿尔卡蒂奥·布恩迪亚面对妻子的热情让了步，但提出一个条件：作为交换，丽贝卡要嫁给皮埃特罗·克雷斯皮。乌尔苏拉等到能腾出时间时，会带阿玛兰妲去省城观光，让她多和外人接触以淡忘自己的失落。丽贝卡听到这个结果，立时恢复了健康，给未婚夫写了一封欢喜万分的信，经父母过目后亲自送到邮局投递。阿玛兰妲假意接受了这一决定，渐渐退了烧，但在心中暗暗发誓，丽贝卡想要结婚除非从她的尸体上跨过去。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3314, 86, 25, 5, 5, '丽贝卡试图抢先作出评论。以现在的施工速度来看，教堂竣工起码要等十年。但尼卡诺尔神甫看法不同：鉴于信徒们捐赠日益慷慨，完全可以作出更乐观的估计。尽管丽贝卡暗暗生气，连饭都没有吃完，乌尔苏拉还是赞同阿玛兰妲的主意，并捐出一笔可观的款项以加速施工。尼卡诺尔神甫认为再有一笔相同数额的捐赠，教堂就能在三年内竣工。从此，丽贝卡不再和阿玛兰妲说话，确信她的用心并不像表面那样单纯无辜。“我已经手下留情了，”在当晚的激烈争吵中阿玛兰妲回答道，“这三年我都用不着杀你了。”丽贝卡接受了挑战。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3316, 86, 27, 5, 5, '居丧多日后十字绣活动已经恢复，一天下午两点，酷热的死寂中突然有人推开大门。房柱震颤不已，长廊里刺绣的阿玛兰妲及其女友，卧室里吸吮手指的丽贝卡，厨房里的乌尔苏拉，作坊里的奥雷里亚诺，甚至栗树下孤零零的何塞·阿尔卡蒂奥·布恩迪亚，都感到房子在大地的震动中摇摇欲坠。来人是一个身材过人的大汉。他粗壮的胸背几乎挤不进门。他野牛似的脖子上挂着救难圣母像，双臂和胸前覆满神秘的刺青，右手腕上紧紧缠着“十字架婴孩” ① 护符铜手链。他的身体经风吹日晒变成棕褐色，短发竖起好像骡子的鬃毛，下颌坚毅，眼神悲伤。他的腰带比马肚带宽两倍，靴子带护腿和马刺，靴跟钉了铁掌，走到哪里都给人以地震般的战栗感。他拎着几个破旧的褡裢穿过客厅和起居室，像一阵风暴般出现在秋海棠长廊，惊得阿玛兰妲和女友们一动不动，绣花针停在空中。“嗨。”他用疲倦的声音说道，随手将褡裢往缝纫桌上一丢，径直走向家中深处。“嗨。”他向丽贝卡打了个招呼，她看着他从自己卧室门前经过，吓得呆了。“嗨。”他对奥雷里亚诺说道，后者正在作坊工作台前全神贯注地干活。他没在任何人身边停留，直接走向厨房，在那里才第一次停住脚步，结束了从世界另一端起程的旅行。“嗨。”他说。乌尔苏拉瞬间愣住，看着他的眼睛，随即发出一声惊呼，扑过去搂住他的脖子，高兴得又哭又叫。他是何塞·阿尔卡蒂奥。他像离开时一样赤贫，乌尔苏拉还得给他两个比索付雇马的钱。他说的西班牙语掺杂着水手的黑话。家人问他都去了哪里，他回答：“那边。”他把吊床支在为他安排的房间里，睡了三天三夜。醒来后吃了十六个生鸡蛋，便直接去了卡塔利诺的店里，他那超常的身材在女人当中引发了好奇和恐慌。他要求奏乐并请所有人喝甘蔗酒。他打赌说能同时和五个男人掰腕子。“这不可能。”那些人确信无法撼动他的手臂后，不禁发出感慨，“他有‘十字架婴孩’。”卡塔利诺不相信这类角力花样，押上十二比索赌他挪不动拒台。何塞·阿尔卡蒂奥将柜台从原地搬起，举过头顶，又放到大街上。结果出动了十一个男人才把它搬回去。在节庆般的狂热气氛中，他在柜台上展示了自己那令人难以置信的阳物，上面红蓝两色纵横交错，覆满多种语言的刺青。那些女人饥渴地围在他身边，他问谁肯出最高价。最有钱的一个愿出二十比索。他又提议所有女人一起抽签，十比索一个签号。这是个夸张的价格，最红的姑娘一夜也不过挣八比索，然而所有女人都表示同意。她们把自己的名字写在十四张纸条上，放在一顶帽子里，然后每人抽出一张。最后抽到只剩两张了，中奖者将在其中产生。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3319, 86, 30, 5, 5, '六个月后，奥雷里亚诺才得知医生当时曾宣布他已无可救药, 说他性格被动、生性孤僻，是个感情用事、没有前途的家伙。他们担心他会泄密，试图困住他。奥雷里亚诺打消了他们的顾虑：他不会说出一个字，但在刺杀摩斯科特一家的晚上，他们将会看见他守在门口。他表现出不容置疑的决心，那计划只得无限期推延。就在这段日子里，乌尔苏拉询问他对皮埃特罗·克雷斯皮和阿玛兰妲成亲的意见，他于是回答说现在不是谈婚论嫁的时候。从一个星期前开始，他就在衬衣下藏着一把老式手枪，并监视着自己的朋友们。每天下午他与何塞·阿尔卡蒂奥和丽贝卡喝咖啡——他们的家开始有些样子了——从七点起跟岳父玩多米诺骨牌。午饭时他会与阿尔卡蒂奥聊天，后者已经长成一个身材魁伟的少年，因战争的迫近越来越兴奋。在学校里，比阿尔卡蒂奥还要年长的学生跟刚学会说话的孩子混在一起，自由派的激情在那里传播开来。他们谈论着枪毙尼卡诺尔神甫，将教堂改成学校，实现自由恋爱。奥雷里亚诺试图抑制他的狂热，劝他要小心谨慎。阿尔卡蒂奥听不进他冷静的说理和对现实的客观估计，当众斥责他性格软弱。奥雷里亚诺等待着。终于，在十二月初，乌尔苏拉惊慌失措地冲进作坊。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3360, 86, 71, 13, 13, '他气色从未那样好过，他本人从未像那样广受爱戴，他的畜群也从未像那样疯狂地繁殖。那么多的猪、牛、鸡在无休无止的宴席中被屠宰，院中泥土在无数鲜血的浇灌下变得淤软乌黑。那里成了永久垃圾场，骨骸内脏遍地，残羹剩饭成堆，人们不得不一直燃放炸药吓走秃鹫，以免它们啄出宾客的眼珠来。奥雷里亚诺第二变得肥硕臃肿，面色红中透紫，走路像乌龟般迟缓。这都要归因于他奇佳的胃口，只有周游世界归来时的何塞·阿尔卡蒂奥才能比得上。耸人听闻的贪食，一掷千金的豪气，无人可比的好客，他的名声越出大泽区的边界，吸引了沿海一带最知名的老饕。神奇的饭桌精英从四面八方赶到，参加在佩特拉·科特斯家举行的疯狂的饕餮大赛。奥雷里亚诺第二保持常胜不败，直到那个不祥的星期六，卡米拉·萨迦丝杜梅出现了。这个图腾般的女人以“母象”的美名享誉全国。比赛一直持续到星期二清晨。在最初的二十四小时里，奥雷里亚诺第二就着木薯、山药和烤香蕉吃掉一头牛，喝下一箱半香槟，对胜利充满信心。比起波澜不惊的对手，他看起来兴奋活跃得多。对手明显更有专业风范，但也正因如此在挤满屋子的各路观众眼中显得缺乏激情。奥雷里亚诺第二在求胜欲望驱使下张口大嚼的同时，“母象”施展外科医生般的技艺将肉细细分解，慢慢享用，甚至带有几分愉悦。她体形巨大敦实，但壮硕的身架掩不住女性的温情。她脸庞秀美，纤细的双手保养得当，浑身散发出不可抗拒的个人魅力，奥雷里亚诺第二在她进门时低声说，自己宁愿和她在床上而不是在桌上比赛。后来看到她吃下整整一扇牛肉仍保持着淑女的最佳仪态，他严肃地评价道，这头娇柔迷人而又胃口奇佳的长鼻动物从某种角度来看正是理想的女人类型。他说得不错。得名“母象”之前，她一度被称为“兀鹫”，这实在没有道理可言。她不像流言所说是杀牛碎骨的屠夫，也不是希腊马戏团里长胡子的悍妇，而是一所声乐学校的校长。她开始学习进食技巧时已是一位可敬的母亲，她这么做是为了找到合适的方式让自己的儿女吃得更好，即不靠人为刺激，而是凭借精神的绝对平静。她那已被实践证明的理论基于以下原则：一个人只要能完全拥有良心上的安宁，就可以不断进食直到疲惫无力为止。因此，她是出于道义上的考虑而非竞技方面的兴趣才离开学校和家庭，来与这个以无所顾忌的大胃王之名享誉全国的男人比试。她第一眼看到奥雷里亚诺第二，就意识到他不会输在胄上，却会输在性格上。第一个夜晚过去，“母象”依然不动声色，奥雷里亚诺第二却因为说笑太多而渐渐困乏。他们睡了四个小时。醒来的时候，每人喝下五十个橙子榨出的果汁、八升咖啡，吃了三十个生鸡蛋。到第二个早上，两人都许久未眠，又吃下两头猪、一把香蕪和四箱香槟。“母象”怀疑奥雷里亚诺第二也在无意中发现了同样的进食诀窍，但区别在于他是从彻底放纵的荒唐之道中领悟的。这样他就比她预想的更为危险。然而在佩特拉·科特斯端上两只烤火鸡时，奥雷里亚诺第二的肚子已快撑到极限。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3321, 86, 32, 6, 6, '阿玛兰妲和皮埃特罗·克雷斯皮得到了乌尔苏拉的信任，友情日深，这一回她认为没有必要再监视他们的见面。这是一段暮色恋情。意大利人每天傍晚登门，扣眼里别着一枝栀子花，把彼特拉克的十四行诗译给阿玛兰妲听。他们待在弥漫着牛至 ① 和玫瑰香气的长廊里，他朗读，而她编织袖口花边，对战争中的种种动乱和噩耗都毫不关心，直到不堪蚊子的烦扰才躲进客厅。阿玛兰妲的善解人意，以及不失分寸又包容一切的温柔，织起一幅无形的网罗把男友围在其中，他不得不用自己未戴戒指的苍白手指生生拨开，才能在八点时告辞离去。他们用皮埃特罗·克雷斯皮收到的意大利明信片做成一本精美的图册，里面的图画都是幽静园林中的恋人，配以中箭的红心和鸽子衔起的金色缎带。“我知道佛罗伦萨的这个公园，”皮埃特罗·克雷斯皮边浏览明信片边说，“你一伸手，鸽子就落下来吃食。”有时看着一幅威尼斯的水彩画，思乡之情使运河中污泥和腐败水产的气味升华成了花朵的幽香。阿玛兰妲一时叹息，一时欢笑，幻想着第二故乡，在那里容貌俊美的男男女女说着孩童的语言，古老的城市昔日荣光不再，只剩下出没于瓦砾间的猫儿。皮埃特罗·克雷斯皮曾经穿过大洋上下寻索，曾经在丽贝卡冲动的纠缠中错生激情，最终找到了真爱。爰情的幸福带来了生意的兴隆。他的商店那时几乎占据了整个街区，堪称幻想的温床，里面有能以钟琴报时的佛罗伦萨钟楼仿制品，有索伦托的八音盒，有一开盖便奏起五音曲的中国香粉盒，以及一切所能想象的乐器和一切所能构想的上弦装置。他的弟弟布鲁诺·克雷斯皮负责商店的业务，因为他自己单单照管音乐学校就忙不过来。多亏了他那五光十色的玩物博览，土耳其人大街变成了一方和谐的绿洲，令人淡忘了阿尔卡蒂奥的种种专横和遥远的战争梦魇。乌尔苏拉恢复星期天弥撒的时候，皮埃特罗·克雷斯皮捐赠给教堂一架德国簧风琴，组织了一个儿童唱诗班，教他们唱格列高利圣诗，为尼卡诺尔神甫沉郁的仪式平添了几许亮丽色彩。没有人怀疑阿玛兰妲会是一位幸福的妻子。他们不刻意推进恋情, 任凭心中的感情自然发展，最后只差定下婚期。他们没遇到什么阻碍。乌尔苏拉为当初反复推迟丽贝卡的婚期这一失误暗中自责不已，不愿重蹈覆辙增添懊悔。战争的戕害，奥雷里亚诺的远走，阿尔卡蒂奥的暴行，以及何塞·阿尔卡蒂奥和丽贝卡的被逐，都令为蕾梅黛丝的服丧退居其次，不再那么严格。婚期在望，皮埃特罗·克雷斯皮暗示将收养奥雷里亚诺·何塞为长子，他一直待他以父亲般的亲切。一切都预示着阿玛兰妲将一帆风顺地走向幸福。然而与丽贝卡相反，她丝毫不显急切。一如染桌布、织绦带、绣孔雀那样，她耐心等待着皮埃特罗·克雷斯皮向内心的煎熬屈服。她盼望的时刻与十月不祥的阴雨一同到来。皮埃特罗·克雷斯皮拿过她膝上的绣筐，双手紧握她的手。“我不能再等了，”他对她说，“我们下个月就结婚。”阿玛兰妲触碰到他冰冷的双手时没有颤抖。她像只抓不住的小动物似的缩回手去，继续自己的活计。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3344, 86, 55, 10, 10, '很快便听说，安东尼奥·伊莎贝尔神甫在为他准备第一次领圣体仪式。他一边为斗鸡修剪颈羽，一边跟神甫学习教理问答。在他安置母鸡抱窝的时候，神甫用简明的例子为他解释上帝如何在创世第二日想到让鸡在蛋中孕育。从那时起神甫表现出老年谵语的最初症状，数年后甚至妄言或许魔鬼已在对上帝的反叛中获胜，如今是它坐在天国的宝座上，隐藏自己的身份来引人受骗上当。经过导师的大胆锤炼，何塞·阿尔卡蒂奥第二在短短几个月内就掌握了足以迷惑魔鬼的神学诀窍，不亚于他在斗鸡方面的百般花招。阿玛兰妲给他做了身亚麻正装，配上硬领和领带，又给他买了一双雪白的鞋子, 还用金字把他的姓名印在大蜡烛的丝带上。领圣体前两天，安东尼奥·伊莎贝尔神甫把两人关在圣器室里听他告解，手捧一本罪孽大全作为参照。那份罪孽清单那么长，神甫上了年纪，平时又习惯六点就寝，终于没等结束就在扶手椅上睡了过去。这场问讯令何塞·阿尔卡蒂奥第二眼界大开。神甫问他有没有和女人做坏事，他并不吃惊，当下如实回答没有，但被问到有没有和动物做过的时候，他不禁一阵惶然。五月第一个星期五，他在好奇心的煎熬中领了圣体。后来他去向佩特洛尼奥请教，这个疾病缠身的圣器保管人住在钟楼上，据说以蝙蝠为食，他这样回答：“是有些堕落的基督徒和母驴干那种事。”何塞·阿尔卡蒂奥第二仍很好奇，缠着问个不停，佩特洛尼奥终于失去了耐心。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3352, 86, 63, 11, 11, '于是奥雷里亚诺·布恩迪亚上校拉开门闩，看见门口聚集着十七个形貌迥异的男子，他们体型肤色各不相同，但都带着落落寡合的气质，在任何地方都能被分辨出来。他们是他的儿子。他们事先未经协商，甚至彼此互不相识，都是风闻纪念特典的消息从沿海地区的各个角落赶来。他们都自豪地取了奥雷里亚诺这个名字，用的母亲的姓氏。他们在家中逗留了三日，弄得像战场一样混乱，乌尔苏拉心满意足，费尔南达又惊又怒。阿玛兰妲从故纸堆里找出乌尔苏拉当年记录姓名、出生日期和受洗日期的小本子，在对应每个名字的空白中添上现在的住址。这份表格可以看作是二十年战争的缩影，凭着它足以重绘上校夜间的行军路线，从那天凌晨他带着二十一个人离开马孔多加入一场荒唐的起义，直到最后一次他裹在沾了血迹而硬结的毯子里归来。奥雷里亚诺第二没有放过款待堂兄弟们的机会，他打开香槟，拉起手风琴，大肆庆祝，算是补回了因纪念特典而未能尽兴的狂欢节。他们打碎了家里一半的餐具，为了追赶一头公牛并将它兜在毯子里抛耍而将花园里的玫瑰践踏殆尽，他们开枪射杀母鸡，强迫阿玛兰妲跳起皮埃特罗·克雷斯皮所教的悲伤华尔玆，怂恿美人儿蕾梅黛丝穿上男人的裤子参加爬竿游戏：他们在饭厅里放出一头涂满油脂的猪，结果将费尔南达撞翻在地，但没有人抱怨这些意外，欢快的气氛席卷全家。奥雷里亚诺·布恩迪亚上校开始时还有所顾虑，甚至对其中几人的血脉心存怀疑，但他渐渐被他们的疯狂感染，临行前还送了每人一条小金鱼。连冷漠的何塞·阿尔卡蒂奥第二也为他们准备了一场斗鸡，但险些以悲剧结束，因为好几个奥雷里亚诺都是此中老手，一眼就看穿了安东尼奥·伊莎贝尔神甫传授的花招。奥雷里亚诺第二从这些为数众多的亲戚身上看到了大肆欢宴的无限可能，决定让所有人都留下来跟他一起干活。唯一接受邀请的人是奥雷里亚诺·特里斯特，一个身形高大的黑白混血儿，有着祖父的冲劲儿和开拓精神，他已经周游半个世界寻找机会，留在哪里都一样。其他人尽管尚未成家，但都已认准自己的前途，个个都是灵巧的工匠，家中的支柱，性情平和的男人。到了圣灰星期三 ① ，在众人四散回到沿海各地之前，阿玛兰妲让他们穿上主日正装，陪他们去了教堂。他们更多是感到有趣而非出于虔诚，被领到祭坛围栏前，由安东尼奥·伊莎贝尔神甫用圣灰在前额上画上十字。回到家后，最小的奥雷里亚诺想要清洗前额，却发现那痕迹无法消除，他的兄弟们也是如此。他们试过清水与肥皂，试过泥土和瓜瓤，最后用上了浮石和碱液，仍然无法除去那痕迹。但阿玛兰姐和其他去望弥撒的人都轻而易举地洗掉了。“这样更好，”乌尔苏拉在与他们告别时说，“从今往后谁都不会把你们认错。”他们在乐队演奏声和爆竹声中胡乱散去，给市镇上的人留下的印象是布恩迪亚家的血脉将绵延不绝。额上印着十字的奥雷里亚诺·特里斯特在市郊建起一座制冰厂，那正是昔日何塞·阿尔卡蒂奥·布恩迪亚痴迷于发明变得癫狂时所梦想的事。
