INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3320, 86, 31, 6, 6, '第6章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3391, 86, 102, 18, 18, '桑塔索菲亚·德拉·彼达买来语法书三年多后，奥雷里亚诺译出了第一张羊皮卷。这工作并非没有意义，但也不过是无法预计的漫漫长路上的第一步，因为译出来的卡斯蒂利亚语看不出什么含义，仍是有待破解的神秘诗行。奥雷里亚诺手头缺乏可供深入研究的资料，但好在梅尔基亚德斯说过加泰罗尼亚智者的店里有能助他破译羊皮卷内容的书籍，于是他决定去找费尔南达，请她允许自己出去找书。在那个被日益增加的垃圾所吞噬的房间里，他考虑着如何以最合宜的方式提出请求，预想各种情形，等候恰当时机，但事到临头看见正从余火上取下食物的费尔南达，他却错过了与她搭讪的唯一机会，事先周密酝酿的请求噎在喉中，一时发不出声音。那是他唯一一次窥看她。她在卧室中的脚步声牵动着他的注意力。他凝神聆听她走到门口收取儿女的来信，同时把写好的信交给邮差，到深夜还在倾听她用笔尖划过纸张时那急迫有力的沙沙声，然后是关灯的声音，黑暗中的喃哺祈祷。这时候他才睡下，相信第二天期待的机会便会到来。他满心以为不会遭到拒绝，因此一天早上剪短垂到肩膀的长发，刮净杂乱的胡须，穿上不知是谁传下的紧身裤和假领衬衣，在厨房等待费尔南达来吃早饭。出现在眼前的不是每日里那个头颈高昂、步伐刻板的女人，而是一位美貌超凡的老妪，她身披已经泛黄的白鼬皮斗篷，头戴金色纸板制成的王冠，举手投足带着几分倦怠，好像刚在暗中哭过。事实上，自从在奥雷里亚诺第二的衣箱里发现了这套蛀痕斑斑的女王行头，费尔南达已经穿戴多次。若是有人看到她站在镜子前，满心陶醉地摆出女王模样，必定会认为她已陷入癫狂。然而并非如此。她不过是把女王盛装当成追忆时光的机器。她第一次穿上时不禁心结暗生，双眼含泪，她又闻到了当年来家里接她去做女王的军官的鞋油气味，追忆起破灭的梦想时心头一阵激荡。她觉得自己如此老迈、衰弱，离生命中的美好时光已如此遥远，竟开始怀念那些最不如意的时刻，而直到此时她才发现自己多么需要长廊里飘来的牛至香气、黄昏时的玫瑰芬芳，甚至渴望外乡人带来的野蛮生机。她本已心如死灰，在日常忧患的痛切打击下若无其事，却在怀旧伊始被击溃了防线。随着岁月的摧残，她对自怜自伤的需求渐渐沦为一种恶习。她在孤独中变得更有人情味。然而那天早上走进厨房，见一个瘦骨嶙峋、面色苍白的年轻人递上一杯咖啡，眼中闪耀着狂热的光芒，她立时因尴尬而痛苦万分。她不仅拒绝了请求，从那以后还把家里的钥匙藏在存放待用子宫托的衣袋里。这一防范并无必要，因为奥雷里亚诺若是愿意，早就能够偷偷自由出入。然而漫长的囚禁、对外界的陌生，以及顺从的习惯，早已使他心中反抗的种子干枯。于是他又回到自己的囚室，把羊皮卷读了又读，聆听费尔南达在卧室里抽泣直到深夜。一天早上，他像往常一样去生火，发现前一天留给她的饭菜仍在已熄灭的炉火上。于是他朝她的卧室里张望，只见她躺在床上，白鼬皮斗篷遮身，皮肤显出象牙般的质地，比以往任何时候都要美丽。四个月后，何塞·阿尔卡蒂奥赶回家时，眼前的她仍保持着这个样子。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3396, 86, 107, 19, 19, '尽管阿玛兰妲·乌尔苏拉自己毫无察觉，她的归来却给奥雷里亚诺的生活带来了根本的改变。自从何塞·阿尔卡蒂奥死后，他成了加泰罗尼亚智者书店的忠实主顾。他那时自由自在，时间充裕，不禁对市镇产生了些许好奇心，但却没有发现任何惊喜。他走在覆满灰尘的孤寂街巷，怀着科学考察般的兴趣不带感情地审视几成废墟的房舍内部，观看因锈蚀和飞鸟的垂死撞击而变得破烂不堪的铁窗纱，打量在往事中消沉下去的居民。他试图以想象重建昔日香蕉公司已荡然无存的辉煌，可视线所及却是当初的泳池里堆满男人的鞋子女人的拖鞋直至池沿；遭到毒麦毁坏的房屋里残留着一具德国犬的骨架，依然被一根钢链拴在铁环上；一部电话响了又响，奥雷里亚诺只得拿起话筒，他听见一个焦虑的女声遥遥传来，说的是英语，便回答说是的，罢工已经结束，三千个死人已经被扔进海里，香蕉公司已经撤走，马孔多最终获得了久违多年的平静。他又走到业已败落的花街柳巷，曾几何时这里大捆大捆的钞票被烧掉只为给昆比安巴舞助兴，如今却已成为分外凄凉冷落、起伏不平的窄巷，几盏红灯尚未熄灭，无人光顾的舞厅只剩些残破的花环点缀，苍白臃肿的无主孀妇、年老色衰的法国女郎和巴比伦女族长还守在唱机旁等待主顾上门。除了安的列斯群岛黑人中最年迈的那个，奥雷里亚诺不曾遇到一个还记得他家族的人，连奥雷里亚诺·布恩迪亚上校也无人知晓。那黑人一头棉花似的白发给人以照片底片的印象，他一如以往在家门口唱着傍晚时凄恻的圣诗。奥雷里亚诺只用了几个星期就学会了复杂的帕皮亚门托语用来和他交谈，有时还一起享用他曾孙女烹制的鸡头汤。那是个高大的黑人姑娘，长着结实的骨架、母马般的臀部和活甜瓜似的乳房，浑圆美丽的头颅上密密覆了一层铁丝般的头发，仿佛戴着中世纪武士的帽盔。她名叫尼格罗曼妲。那时奥雷里亚诺还在靠变卖家里的餐具、烛台和其他小物件过活。他时常落到囊空如洗的地步，便去市场的小吃摊上讨些人家准备丢进垃圾桶的鸡头，请尼格罗曼妲添上马齿苋做汤，又加进薄荷调味。她曾祖父死后，奥雷里亚诺不再去她家，但常在广场上巴旦杏树幽暗的树荫下遇见她用粗野的呼哨声吸引稀少的夜游者。很多次他都去陪她，用帕皮亚门托语和她谈起鸡头汤及其他贫寒生活中的美味。若不是她表示他待在一边吓走了潜在的主顾，他还会和她这样聊下去。尽管他有几次感受到了诱惑，尽管尼格罗曼妲也会将那看作共享怀旧之情的自然结果，他却没有和她睡觉。因此阿玛兰妲·乌尔苏拉在回到马孔多那天送出一个令他窒息的友爱拥抱时，奥雷里亚诺仍然是未经人事的处男。每次看到她，特别是在她传授最新舞步的时候，他总会感到骨头里充满无助的泡沬，跟当年高祖父与借口玩纸牌带他钻进谷仓的庇拉尔·特尔内拉独处时的感觉一般无二。他试图强压下痛苦，更加投人地研究羊皮卷，尽量避开那位姨妈天真烂漫的讨好，避开她身上散发出的令他夜夜饱受荼毒的气息，然而他越是逃避，越是渴望听见她咯咯的笑声、牝猫般快活的尖叫和欢畅的歌声，她随时随刻在家中最出人意料的地方享受情爱的欢娱声。一天夜里，距离他床铺十米远处，在金银器工作台上，那夫妻俩肆意欢爱间将玻璃瓶打碎，最后在盐酸横流中成其好事。奧雷里亚诺一分钟都没能合眼，而且次日整天都在发热，在愤怒中抽泣。他在巴旦杏树荫下等待尼格罗曼妲的第一个夜晚无比漫长，惴惴不安的感觉仿佛冰针穿心，手中紧紧握着那一比索五十铜板。他向阿玛兰妲·乌尔苏拉要来这钱固然因为需要，但更多地是为了让她也以某种形式卷入自己的冒险，从而折辱她，占有她。尼格罗曼妲把他引向诱人的烛火映照下的卧室，引向那张因反复接客而脏污不堪的折叠床，引向她冷酷无情、精壮如母狗般的身体，她本打算像安慰受惊的孩子似的将他打发，不料遇上的却是一个勇猛异常的男人，搅得她五脏六腑都在巨震中错位。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3393, 86, 104, 18, 18, '其中四个最大的孩子，快进入青春期却仍穿着短裤，他们负责何塞·阿尔卡蒂奥的仪容修饰。他们比旁人来得更早，整个上午为他剃须，用热毛巾按摩，修剪手脚指甲，洒花露水。他们不时也跳进水池，为他从头到脚打上肥皂，他自己则仰面漂在水上，想着阿玛兰妲。随后他们为他擦干身体，搽粉，穿衣。其中有个孩子长着金黄色鬈发，一双玻璃球似的红眼睛活像兔子，他时常在家里过夜。这孩子与何塞·阿尔卡蒂奥的关系极为密切，甚至在他患哮喘失眠时也陪伴一旁，默默跟随他在漆黑一片的家中游荡。一天晚上，他们在乌尔苏拉的卧室中看到一片金光自水泥地下映出，仿佛地下有一轮太阳把卧室地板变成了彩色玻璃窗。屋里亮得不用开灯，他们只是掀开断裂的石板，就在昔日放置乌尔苏拉卧床的角落、光芒最盛的地方，发现了奥雷里亚诺第二曾经疯狂挖掘却未能寻获的秘密地窖。里面藏着那三个用铜丝绳束口的帆布袋，袋中是七千二百一十四枚面值为四多卜拉的多卜隆金币， ① 在黑暗中仿佛炭火般艳艳放光。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3394, 86, 105, 19, 19, '第19章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3357, 86, 68, 12, 12, '这一事件结束了奧雷里亚诺·布恩迪亚上校的赎罪心境。蓦然间他内心又充满了年轻时的愤怒，当年他面对那个因被疯狗咬伤就惨遭乱棍打死的女人的尸体时也曾这般怒火中烧。他望着家门口好奇围观的人群， 因着 对自己的深深蔑视又恢复了当年的洪亮嗓音，向他们发泄胸中再也无法忍受的愤恨。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3340, 86, 51, 9, 9, '阿玛兰妲第一个怀疑家里人已经永远失去了他。停战前一星期, 他没带卫队而只让两个赤脚的勤务兵走在前面，进家后把骡子上的鞍鞴 ① 和收藏诗稿的箱子卸在长廊里，那是他当年帝王般行装仅存的部分。她看见他从缝纫间门口经过，便叫了一声。奥雷里亚诺·布恩迪亚上校似乎一时想不起她是谁。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3395, 86, 106, 19, 19, '他们在结婚三年前相识，当时他驾驶着双翼运动机在阿玛兰妲·乌尔苏拉读书的学校上空翻滚腾跃，正要大胆操作避开旗杆，由帆布和铝箔构成的粗陋机身尾部却挂在了电线上。从那时起，他不顾腿上还绑着夹板，每到周末都去阿玛兰妲·乌尔苏拉一直居住的修女膳宿公寓接她——显然那里的规定没有费尔南达期待的那般严厉——随后带她去自己的竞赛倶乐部。他们星期天在野地上五百米的高空相爱，看着地上的人影愈变愈小，愈觉彼此心意相通。她时常和他说起马孔多，仿佛那是世界上最幸福最恬静的市镇，说起一座满溢牛至芬芳的大宅，她愿与一位忠贞的丈夫在那里相伴终老，生下两个野性十足的儿子分别叫作罗德里戈和贡萨洛，绝不叫奥雷里亚诺和何塞·阿尔卡蒂奥，还要养育一个女儿名叫维吉尼娅，绝不叫蕾梅黛丝。她思乡情切，念念不忘被回忆美化的市镇，加斯通便明白若想娶她必须带她去马孔多生活。他表示同意，后来也同样接受了颈上的丝带，因为他相信那不过是一时的任性，终将随着时间的流逝而淡忘。但在马孔多待了两年，阿玛兰妲·乌尔苏拉仍像第一天那样快活，他不禁警惕起来。这时他已经把本地所有能制成标本的昆虫都制成了标本，卡斯蒂利亚语也说得像本地人一样流利，还做完了杂志中所有的填字游戏。他无法拿气候当作归返的借口，因为他天生一副殖民者的体格，能毫无困难地忍受闷热天气里的午睡和含蛆虫的水质。他酷爱美洲食物，有一次连吃下八十二个鬣蜥蛋。阿玛兰妲·乌尔苏拉反而只吃火车用冰柜运来的鱼虾海鲜、罐头肉和蜜饯，穿衣打扮依然按照欧洲时尚并继续订阅时装图样，尽管她在这里无处可去也无人可拜访，并且这时她丈夫也没有心思欣赏她的清凉短装、斜戴的毡帽和环绕七转的项链。她的秘密似乎在于永远保持忙碌，处理自己一手造成的家务问题，时常出错以备次日纠正，费尔南达若是有知，一定会把这种有害的勤勉归咎于且做且毁的祖传恶习。她天性未改依然喜好玩乐，每当收到新寄来的唱片，都会叫上加斯通去客厅演练同学为她画在纸上的舞步，一练练到很晚, 通常会以维也纳摇椅中或光地板上的做爱告终。对她来说唯一美中不足的就是尚未有儿女诞生，但她依然尊重当初和丈夫的约定，婚后五年内不生孩子。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3392, 86, 103, 18, 18, '“看来，”他的声音里有种剃刀般的锐利，“你就是那个野种了。”
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3318, 86, 29, 5, 5, '第二天，应朋友之请，他去拜访阿利黎奥·诺格拉医生，求治并不存在的肝痛。他甚至不知道自己为什么要这样做。阿利黎奥·诺格拉医生几年前来到马孔多，带着一药箱无味的药丸和一块无法令人信服的行医招牌：“一钉入，一钉出。” ① 其实那只是伪装。那副平庸医生的无辜外表下隐藏着一个恐怖分子，借着及膝的高筒靴遮住相伴五年的脚镣在踝部留下的疤痕。他是在参加联邦派的第一次起事时被捕的，后乔装改扮逃往库拉索，被迫披上他在这个世界上最憎恶的衣服——教士袍。漫长的逃亡岁月过去，从加勒比海各地来到库拉索的流亡者带来令人振奋的消息，他大受鼓舞登上走私贩的帆船，随身带着一瓶瓶纯由白糖制成的药丸和一张他自己伪造的莱比锡大学文凭，出现在里奥阿查。但他随即失望得痛哭起来。联邦派的激情在流亡者口中被描述成一触即发的火药桶，其实早已沦为对选举的渺茫幻想。怀着受挫的苦涩，以及寻找一处安稳地方养老的渴望，这位冒牌的顺势疗法医生逃到了马孔多。他在广场一侧租下间小屋，在这摆满空药瓶的斗室里过了几年，生计全仰仗那些已经试遍所有医药，最后只靠糖丸聊作安慰的病人。在堂阿波利纳尔·摩斯科特有名无实的统治期间，他那煽动者的天性一直无用武之地。追忆往昔，与哮喘作斗争，他的日子一天天过去。大选的临近使他重新找到了起事的机会。他与镇上缺乏政治素养的年轻人建立联系，暗暗展开教唆工作。票箱中出现大量红色选票，堂阿波利纳尔·摩斯科特归因于年轻人的追新猎奇，但其实是他计划的一部分：强迫自己的门徒投票，好让他们认清选举不过是一场骗人的闹剧。“唯一有效的他说，“就是暴力。”奥雷里亚诺的大多数朋友都为铲除保守秩序的念头所鼓舞，但没人敢拉他下水，这不仅因为他与里正的关系，也和他孤僻遁世的性格有关。另外众所周知，他在岳父的授意下投了蓝色选票。因此他表露自己的政治态度纯属偶然，为不存在的病痛去求诊更是完全出于一时的好奇心。猪圈般的陋室里蛛网横斜，樟脑味扑鼻，他见到的是一个浑身灰尘颇似蜥蜴的人，喘息间肺里呼啸作响。医生一言不发，先把他领到窗前，检查下眼睑。“不是这里。”奥雷里亚诺按照人家事先所教的说道。他用指尖按住肝部，加了一句：“是这里疼得让我睡不着觉。”于是阿利黎奥·诺格拉医生推说阳光太强，关上了窗，随即向他简洁地解说为什么剌杀保守派是一种爱国行为。连续几天奥雷里亚诺都在衬衣兜里揣着小药瓶，每两个小时取出一次，倒出三粒药丸在手上，然后放进嘴里慢慢含服。堂阿波利纳尔·摩斯科特嘲笑他竟信任顺势疗法，但那些知情人都把他当成又一个加入的同伴。几乎所有建村元老的儿子都参与其中，但没人知晓他们所酝酿的行动的具体内容。然而有一天医生向奥雷里亚诺吐露了秘密，他终于弄清了密谋的详情。虽然当时他确信铲除保守党政权刻不容缓，但这一计划仍令他不寒而栗。阿利黎奥·诺格拉医生是个信奉个人暗杀的狂热分子，他的方案可归纳如下：将一系列个人行动汇成一次全国范围内的总攻，铲除当局官员及其亲属，特别是孩子，以达到将保守主义斩草除根的目的。堂阿波利纳尔·摩斯科特，他的妻子和六个女儿，自然全在目标之列。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3382, 86, 93, 17, 17, '第17章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3398, 86, 109, 19, 19, '于是奥雷里亚诺的激情爆发了，他像个被抛弃的孩子似的在她受伤的手上吻了又吻，敞开内心所有最隐秘的甬道，倾吐百转愁肠, 释放煎熬中孕育出的寄生怪兽。向她诉说自己如何在深夜起来，扑在她晾在浴室的内衣上因无助和愤怒而哭泣。向她诉说自己如何热切要求尼格罗曼妲像牝猫般尖叫并在他耳边呜咽“加斯通，加斯通，加斯通”，如何费尽心机搜罗她的香水瓶好在那些卖身糊口的女孩颈项上闻到她的香味。这激情四溢的倾诉把阿玛兰妲·乌尔苏拉吓得不轻，她渐渐蜷起手指像软体动物般缩了回去，那受伤的手不再感到疼痛也不再有分毫的怜悯，化作一团翡翠、黄玉以及僵硬麻木的骨头拧成的死结。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3400, 86, 111, 20, 20, '阿尔瓦罗第一个听从忠告离开了马孔多。他变卖一切，包括家中院里吓唬路人的老虎，买下一张永久车票，登上一列永无终点的火车。他从路经的车站寄来明信片，兴高采烈地描述车窗外瞬间闪过的世间万象，仿佛将一首飞逝的长诗撕成碎片向着遗忘之乡一路抛洒：路易斯安那棉田里奇怪的黑人，肯塔基蓝色草丛中疾驰的骏马，亚利桑那地狱般暮色里的希腊情侣，密歇根湖畔画水彩画的红衫少女——她举起画笔向他致意，不是为了告别而是盼望再见，因为她并不知道眼前所见的火车没有归路。随后，阿尔丰索和赫尔曼在一个星期六离开，计划下星期一回来，却从此再无音讯。加泰罗尼亚智者走后一年，只有加布列尔还留在马孔多，仍然一事无成，靠尼格罗曼妲不稳定的周济过活。他参加了一家法国杂志的有奖问答，头奖是一次巴黎之旅。订阅杂志的人其实是奥雷里亚诺，他帮加布列尔填写答案，有时在家里，更多的时候在马孔多仅存的一家药房中，在瓷瓶和缬草 ① 气息的环绕间，加布列尔沉静的女友梅尔塞德斯所住的地方。这是往昔的最后遗存，这往昔日渐衰落却不会彻底消亡，因为它是在自身之中无休无止地败落下去，每过一刻便向彻底灭亡更近一步，却永远无法抵达最后的终结。整个市镇如此死气沉沉、与世隔绝，当加布列尔赢了大奖，带着两套换洗衣服、一双鞋和一套拉伯雷全集要去巴黎的时候，不得不向司机挥手致意才让火车停下将他接上。昔日的土耳其人大街已沦为被遗忘的角落，最后一批阿拉伯人沿袭千年传统端坐在门口等待死亡的到来，尽管最后一码斜纹布早已售出，幽暗的橱窗里只剩下一个个无头的模特。至于香蕉公司的城镇，或许帕特里夏·布朗在阿拉巴马州普拉特维尔难耐的长夜里会就着醋拌黄瓜对儿孙们说起，但此时它已沦为一片野草丛生的平原。安赫尔神甫的继任者是一位老神甫，没人愿意费心打听他的名姓。他为关节炎及疑虑引发的失眠所苦，懒懒地躺在吊床上等待上帝的慈悲，任凭蜥蜴和老鼠在隔壁的教堂里争夺领地。在那个连飞鸟也厌弃，长久的扬尘与酷热令人呼吸艰难的马孔多，奥雷里亚诺和阿玛兰妲·乌尔苏拉被爱情、被孤独、被爱情的孤独幽禁在因红蚂蚁疯狂啃噬的轰响而难以入睡的家里，他们是唯一幸福的生灵，世上再没有比他们更幸福的人。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3368, 86, 79, 14, 14, '正午之前，阿玛兰妲·布恩迪亚将在傍晚起程梢带冥信的消息就在马孔多传开，到下午三点客厅里已经放了整整一箱信件。不愿写信的人托阿玛兰妲带个口信，她就在小本子上一一记下收信人的姓名和去世日期。“放心，”她安慰委托人，“我一到那边就去打听他的下落，把口信带给他。”一切仿佛一场闹剧。阿玛兰妲没显出丝毫慌乱，也没露出任何痛苦的迹象，甚至因为履行了义务而显得更加年轻。她身形挺拔修长一如平常。如果不是颧骨凸出和牙齿略有缺残，她看上去会比实际年龄年轻得多。她亲自吩咐将信件放进涂了柏油的箱子，并指定安放在坟墓中的位置，以尽量做到防潮。上午她请来一位木匠，站在客厅里让他量尺寸做棺材，就像是要做一件礼服。她在最后几小时迸发出无穷活力，费尔南达认为她是在拿所有人寻开心。乌尔苏拉知道布恩迪亚家的人都是无疾而终，并不怀疑阿玛兰妲的死亡预感，但仍害怕昏了头的寄信人希望信件早些送达而将她活着下葬。于是她拼命在家中清场，喊叫着与侵入者争吵，到下午四点时终于达到目的。这时，阿玛兰妲刚刚将自己的物品分发给穷人，只留下死后要穿的一套换洗内衣和一双普通的灯芯绒便鞋放在简陋的粗木棺材板上。她没有忽略这个细节，因为她还记得奥雷里亚诺·布恩迪亚上校死的时候只剩下在作坊里穿的拖鞋，自己不得不给他买一双新鞋。快五点的时候，奥雷里亚诺第二来接梅梅去参加音乐会，惊讶地发现家里正在筹备丧事。那时看上去生机勃勃的活人就只有阿玛兰妲，她甚至还好整以睱地修了鸡眼。奥雷里亚诺第二和梅梅开玩笑似的与她告别，还约好下个星期六举办复活宴席。听说阿玛兰妲·布恩迪亚将给死人带信，安东尼奥·伊莎贝尔神甫在五点钟赶来准备施行临终仪式，但等了一刻多钟才看到濒死的女士从浴室出来。一见她穿着马达普兰白细布睡衣、披散着头发出现，老迈的神甫便认定这是一个玩笑，随即遣走了祭童。但他认为可以利用这个机会，让阿玛兰妲作出一次延宕了二十年的忏悔。阿玛兰妲直截了当地回答说，她不需要任何宗教仪式的帮助，因为她的良心是清白的。费尔南达大惊失色，她不顾别人会听见，高声责问阿玛兰妲究竟犯下了怎样可怕的罪行，以至于宁可亵渎神明而死也不愿丟脸地忏悔。于是阿玛兰妲躺下，逼迫乌尔苏拉当众检查自己的贞洁。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3402, 86, 113, 20, 20, '奥雷里亚诺这时才明白自己多么爱他的朋友，多么需要他们，多么想在此时此刻有他们的陪伴。他把孩子放进他母亲预备好的篮子，用毯子盖住死者的脸庞，然后跑到市镇上漫无方向地游荡，寻找回到往昔的途径。他来到最近一阵未曾拜访的药房前叫门，发现那里变成了一家木匠作坊。提灯为他开门的老妇人对他的胡言乱语表示同情，但同时一口咬定，这里从没有过什么药房，她也从不认识一个脖颈纤细、眼神迷离，名叫梅尔塞德斯的姑娘。他来到加泰罗尼亚智者的书店旧址，一头抵在门上放声痛哭，心中明白这迟来的眼泪是为那桩死丧而流，当时没有哭泣是不愿破坏相爱的美好。他捶打着“金童”乐园的灰泥墙直到双手俱裂，呼唤着庇拉尔·特尔内拉。空中有发光的橙色圆盘飞过，他在过去无数个欢闹的夜晚曾经从养着石鸻的院中像孩子般着迷地仰头观看，此时却无动于衷。花街柳巷最后一家营业的舞厅里，手风琴乐队弹唱起主教的侄子，好汉弗朗西斯科的绝艺传人拉斐尔·埃斯卡洛纳的歌曲。店主曾对自己的母亲不敬，出手向她动粗，结果落得一只手臂萎缩，他邀请奥雷里亚诺喝了瓶烧酒，奥雷里亚诺也请他喝了一瓶。店主对他讲起自己手臂的不幸遭遇，奥雷里亚诺对他讲起自己心灵的不幸遭遇：因为对自己的姐妹倾心而落得枯焦。最后，两人齐声痛哭起来，奥雷里亚诺一时间感到痛苦已经结束。然而，当他在马孔多的最后一个清晨再次变成独身一人，他站在广场中央大张双臂，仿佛要唤醒整个世界一样声嘶力竭地吼道：
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3364, 86, 75, 13, 13, '然后他不急不慌，慢慢吃下盛在同一个盘子里的洋葱炖肉、白米饭和炸香蕉片。他的胃口不受环境好坏的影响。午饭后，他感到一阵闲下来的空虚。出于一种科学的迷信，他在饭后消化的两小时内不干活、不阅读、不洗澡也不做爱。这种信念如此根深蒂固，早在战时他就曾为了避免士兵们消化不良而多次推迟行动。他躺在吊床上，用折叠小刀掏着耳朵，不到几分钟便睡着了。他梦见自己走进一幢空空的房子，墙壁雪白，还因为自己是第一个走进这房子的人而深感不安。在梦中，他记起前一夜以及近年来无数个夜晚自己都做过同样的梦，知道醒来时就会遗忘，因为这个不断重复的梦只能在梦中想起。果然，片刻后当理发师敲响作坊的门，奥雷里亚诺·布恩迪亚上校醒来，只觉得自己无意中睡了短短几秒钟，还来不及做梦。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3371, 86, 82, 14, 14, '她疯狂地爱上了他。她辗转难眠，茶饭不思，深深沉浸在孤独里，连自己的父亲都成了障碍。她利用约会的借口编织出错综复杂的迷网令费尔南达无从捉摸，她不再去看女友，打破常规在任意时间和地点与马乌里肖·巴比伦见面。开始的时候她不喜欢他的粗鲁。他们在汽修厂后面荒凉的草地上第一次单独相处时，他毫不怜惜地带着她进入野兽般的状态，令她精疲力竭。后来她意识到这种方式也是柔情的表现，便失去了平静，再也离不开他，一心渴望沉醉在他那混杂着去污剂和机油气味的迷人气息中。阿玛兰妲死前不久，梅梅在疯狂中突然显出一线清醒，开始为未卜的前途恐慌。这时她听说有个女人会用纸牌算命，便暗中登门拜访。那是庇拉尔·特尔内拉。一见梅梅进门，她就猜出了她的心思。“坐吧，”她说，“不用纸牌我也能猜出布恩迪亚家人的未来。”梅梅那时并不知道，而且永远不会知道，这个年过百岁的算命老妪是自己的曾祖母。即使她知道也不会相信，尤其老人还毫不掩饰地告诉她热恋中的焦灼只能在床上平息。马乌里肖·巴比伦也持同样的观点，但梅梅不肯相信，她在内心深处怀疑那只不过是匠人的错误想法。她当时认为爱情的一种方式能够击败另一种方式，这与胃口得到满足就不觉饥饿是同样的道理。庇拉尔·特尔内拉不仅纠正了她的错误，还将那张铺着麻布的旧床慷慨出借，她在那上面孕育了梅梅的祖父阿尔卡蒂奥，后来又怀上了奥雷里亚诺·何塞。她还教她如何用芥末泥蒸气来避孕，并传授她药水配方，好在意外发生时消除麻烦，甚至摆脱“良心的挣扎”。这次会面令梅梅获得了与那天下午醉酒后同样的勇气。然而，阿玛兰妲的死迫使她推迟了行动。在守灵的九天里，她片刻不曾离开混在家中吊唁人群里的马乌里肖·巴比伦。后来是漫长的服丧和必不可免的闭门幽居，他们分开了一段时间。那段日子她内心受尽煎熬，焦急不安，难忍冲动，因此在能够脱身出门的第一个下午便径直来到庇拉尔·特尔内拉家里。她献身给马乌里肖·巴比伦，不抗拒、不扭捏也不羞赧，显出优异的天赋和过人的敏锐，若换一个比她的情人更多疑的男人或许要怀疑她熟稔此道。三个多月中他们每星期幽会两次，蒙在鼓里的奥雷里亚诺第二还一直提供庇护，天真地为女儿的借口作保，只为帮她摆脱她母亲的严厉管束。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3377, 86, 88, 16, 16, '第16章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3390, 86, 101, 18, 18, '得知她的离去，费尔南达不停不休地骂了一整天，还翻箱倒柜挨个检查，确认桑塔索菲亚·德拉·彼达没有卷走什么东西。她平生第一次试着生火却烫到了手指，不得不请奥雷里亚诺教她煮咖啡。时间一长，便由他承担起厨房的活计。每天费尔南达起床时早饭已做好，她只需走出卧室，取走余火上奥雷里亚诺盖好留给她的食物，放到铺着亚麻桌布的桌上，坐到上首，在烛台环绕中面对着十五把空椅子独自用餐。即使到了这步田地，奥雷里亚诺和费尔南达也从未分享孤独，仍然各行其是，各自打扫房间，任凭蛛网落雪般笼在玫瑰枝头，又在梁上垂丝，绕四壁飘絮。那个时期，费尔南达感觉家中到处都是鬼怪精灵。各样物品，特别是日常用具，仿佛都有了自由移动的能力。费尔南达找了很长时间明明放在床上的剪刀，在家中四处翻遍后，结果在厨房里的隔板上找到，而她却认定自己已经有四天不曾迈进厨房一步。叉子从装餐具的抽屉里不翼而飞，她却在祭坛上找到六把，洗衣盆里也有三把。她坐下来写信，这种现象更令她绝望。一向放在右手边的墨水瓶跑到左手边；吸墨垫突然消失，两天后又在枕下现身，写给何塞·阿尔卡蒂奥的信与给阿玛兰妲·乌尔苏拉的弄混，她总是为装错信封而烦恼，这种事也确实发生了不止一次。有一回她丢了钢笔，十五天后邮差送了回来，他是在自己的邮袋里发现的，挨家挨户问了一圈才找到失主。开始的时候，她以为这和子宫托的消失一样是隐身的医生们所为，准备写信央求他们放过自己，但写信中途为别的事走开了一会儿，结果回来的时候不仅找不到已经开了头的信，甚至想不起写信的初衷。有一段时间她怀疑奥雷里亚诺，就开始监视他，故意把东西放在他经过的地方，想等他挪动时一举抓获，但很快她便证实奥雷里亚诺除了去厨房和厕所之外从不离开梅尔基亚德斯的房间，而且他也不是爱开玩笑的人。最终她相信是精灵们在淘气，于是决定把每样东西都固定在要用的地方。她拿一根龙舌兰线绳把剪刀拴在床头。她把钢笔和吸墨垫绑在桌腿上，又用胶水将墨水瓶粘在桌面右手边的位置。事情并未立竿见影地解决，她才做了几个小时的针线活儿，拴剪刀的线绳便已不够长，仿佛精灵们正暗中将它裁短。钢笔上的线绳也是一样，她没写多久手就已经够不着墨水瓶。但无论是远在布鲁塞尔的阿玛兰妲·乌尔苏拉还是罗马的何塞·阿尔卡蒂奥，对这些琐碎的不幸都毫不知情。费尔南达总告诉他们自己很幸福，事实上也是如此，因为她感觉卸去了一切重担，仿佛生活又把她带回到她父母的天地里，那里没有日常生活的困扰，一切都已在幻想中解决。无休无止的通信使她丧失了时间概念，特别是在桑塔索菲亚·德拉·彼达走后。她本来已习惯根据儿女们预定的归期来数算日日月月、岁岁年年，但他们一再推迟归期，使她混淆了日子，颠倒了年月，何况每一天都如此相似，简直感觉不到时光的流逝。但她并未失去耐心，反而对拖延深感欣慰。何塞·阿尔卡蒂奥多年前就宣称即将誓发永愿，但仍在推说结束高等神学的课业后还需转攻外交。费尔南达未觉不安，她理解通往圣彼得宝座之路任重道远，绝非一帆风顺。与此相反，一些在旁人看来无关紧要的消息却能令她兴奋不已，譬如儿子亲眼见到教皇。当阿玛兰妲·乌尔苏拉告诉她，自己由于成绩优异，赢得了当初父亲未曾预料的奖励而得以继续学业，她也同样为之欣喜。', 1316, 'length_limit', FALSE, 'selected', 4.8, '该场景以日常物品的错位、丢失与固定为核心，将人物内心的孤独、时间感的崩塌和自欺的幸福具象化，形成高度可迁移的写作范式。细节密集而克制，不依赖情节推进，却通过物件与动作的异常传递出深层的心理状态，对写作者具有明确的示范价值。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 4.2, "distinctiveness": 4.8, "prose_quality": 4.8, "reference_value": 4.8, "scene_completeness": 4.5, "technique_value": 5.0}, "reference_reason": "该场景以日常物品的错位、丢失与固定为核心，将人物内心的孤独、时间感的崩塌和自欺的幸福具象化，形成高度可迁移的写作范式。细节密集而克制，不依赖情节推进，却通过物件与动作的异常传递出深层的心理状态，对写作者具有明确的示范价值。", "reference_score": 4.8, "reference_status": "selected"}'::jsonb, '桑塔索菲亚离去后，费尔南达首次生火做饭，奥雷里亚诺接手厨房。她陷入物品自行移动的怪象，剪刀、钢笔、墨水瓶等不断失踪或移位，她尝试捆绑固定却徒劳。她与远方子女通信，谎称幸福，实则失去时间感，沉溺于幻想中的平静。', '以日常琐碎细节铺陈魔幻现实，通过物品丢失的荒诞升级展现人物孤独与自欺。语言克制而富有诗意，用具体动作和物件替代直白心理描写，形成独特的叙事节奏。', '适合参考如何用日常物件和微小异常营造神秘氛围，表现人物内心。避免过度解释超自然现象，应让细节自行呈现荒诞感。', ARRAY['daily_life', 'mystery', 'emotional']::text[], ARRAY['daily_life', 'mystery', 'emotional']::text[], ARRAY['escalation', 'sensory_detail', 'show_dont_tell', 'contrast']::text[], ARRAY['escalation', 'sensory_detail', 'show_dont_tell', 'contrast']::text[], ARRAY['lyrical', 'restrained', 'dark']::text[], ARRAY['lyrical', 'restrained', 'dark']::text[], ARRAY['grief', 'tension', 'relief']::text[], ARRAY['grief', 'tension', 'relief']::text[], ARRAY['fire', 'snow', 'light']::text[], ARRAY['fire', 'snow', 'light']::text[], 'advance', '{"emotion_tags": ["grief", "tension", "relief"], "key_images": ["fire", "snow", "light"], "narrative_func": "advance", "scene_type": ["daily_life", "mystery", "emotional"], "style_summary": "以日常琐碎细节铺陈魔幻现实，通过物品丢失的荒诞升级展现人物孤独与自欺。语言克制而富有诗意，用具体动作和物件替代直白心理描写，形成独特的叙事节奏。", "style_tags": ["lyrical", "restrained", "dark"], "summary": "桑塔索菲亚离去后，费尔南达首次生火做饭，奥雷里亚诺接手厨房。她陷入物品自行移动的怪象，剪刀、钢笔、墨水瓶等不断失踪或移位，她尝试捆绑固定却徒劳。她与远方子女通信，谎称幸福，实则失去时间感，沉溺于幻想中的平静。", "technique": ["escalation", "sensory_detail", "show_dont_tell", "contrast"], "usage_hint": "适合参考如何用日常物件和微小异常营造神秘氛围，表现人物内心。避免过度解释超自然现象，应让细节自行呈现荒诞感。"}'::jsonb, 'annotated', 'indexed', NULL, 3, TRUE, '2026-10-06T10:42:56.586149+00:00', '2026-10-06T10:57:09.857796+00:00', 'not_run', '', '', '{}'::jsonb);
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3937, 43, 19, 19, 19, '第18章 高中的冰淇淋
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3381, 86, 92, 16, 16, '马孔多满目疮痍。街巷间的泥潭中残留着破烂家具，被红色百合覆盖的动物骨架，都是外来人潮留下的最后遗物，他们一拥而至又一哄而散。香蕉热潮期间匆忙盖起的房子都已废弃。香蕉公司撤走了一切设施。当初电网包围的城市只剩下一地瓦砾。那些木屋，那些午后常有轻松牌戏的清凉露台，都被飓风刮走，仿佛是多年后马孔多必将从世间被抹去的预演。这场狂野风暴过后留下的人迹，只有帕特里夏·布朗的一只手套，落在巳被九重葛 ① 淹没的汽车里。何塞·阿尔卡蒂奥·布恩迪亚当年创业时探索过的着魔之地，后来变成繁盛的香蕉种植区，此时却沦为腐烂根系的沼泽，多年以后从这里仍能遥遥望见远方大海无声的泡沬。雨后的第一个星期天，奥雷里亚诺第二穿上干衣服出门，故园面目全非的景象令他心痛不已。那些灾难幸存者，那些早在香蕉公司的风暴席卷之前就生活在马孔多的老住户，都坐在街头享受雨后初晴的阳光。他们皮肤上仍残存着绿色的水藻，身上雨水留下的墙角霉味犹未散去，但在内心深处正为收复了自己出生于此的市镇而欣慰不已。土耳其人大街又恢复了昔日景象，就像当年阿拉伯人到来时一样。那些穿尖头靴戴耳环的阿拉伯人走遍世界用小玩意儿交换金刚鹦鹉，最终在马孔多找到安身之处，结束了千年流浪生涯。市集上的商品破败不堪，店门口的货物苔藓满布，柜台被白蚁蛀坏，墙壁受潮气侵蚀，然而第三代阿拉伯人仍坐在同样的地方，带着和祖辈父辈同样的神态。他们沉默寡言，镇静自若，不受时光与灾难的影响，就像失眠症肆虐之后以及奥雷里亚诺·布恩迪亚上校的三十二场战争之后那样生死莫测。面对破烂不堪的赌桌、油炸食品摊子、打靶屋、已成一片废墟的算命解梦的小巷，他们表现出的镇定着实令人惊诧。奥雷里亚诺第二不禁以一贯的随便态度，问他们凭借了怎样的神奇方法从暴风雨中幸存，怎么会见鬼似的没被淹死，而家家户户都报以狡狯的微笑和梦幻般的眼神，人人都不谋而合地给出同样的答案：
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3369, 86, 80, 14, 14, '为阿玛兰妲守灵九天后，乌尔苏拉再没有起床。桑塔索菲亚·德拉·彼达负责照顾她。她每天往卧室里送饭和用来洗漱的胭脂果水, 将马孔多发生的一切讲给她听。奥雷里亚诺第二时常来探望，给她送来衣服。她把衣服和日常必需品一起放在床边，很快就建起一个触手可及的小天地。她还赢得了小阿玛兰妲·乌尔苏拉的亲近，教导这个与她酷似的孩子学习认字。她神志清醒，生活能够自理，给人的印象只是历经百年沧桑而自然衰老。虽然她明显视物困难，却没有人怀疑她巳彻底失明。她有足够充裕的时间和平和的心境来关注家人的一举一动，也是她首先发觉了梅梅的隐优。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3370, 86, 81, 14, 14, '他叫马乌里肖·巴比伦。他在马孔多出生成长，是香蕉公司汽修厂里的学徒。梅梅是偶然与他结识的。一天下午，她和帕特里夏·布朗想找一辆汽车到种植园里兜风，当时司机病了，他便被派来开车。梅梅终于如愿以偿坐到了副驾驶位置，可以近距离观察驾驶操作。和那位正式司机不同，马乌里肖·巴比伦为她作了操作示范。那还是梅梅刚开始来布朗先生家串门的时候，女士开车在马孔多仍被视为有失体统，因此她得到些理论知识便心满意足，此后几个月都没再见到马乌里肖·巴比伦。后来她想起兜风时，除了那双粗糙的手，他的男性美也曾引起自己的注意，但事后她又曾向帕特里夏抱怨过他那不无高傲的自信令人厌烦。她第一次和父亲星期六去看电影的时候，又见到了马乌里肖·巴比伦，他穿着亚麻正装，坐在离他们不远的地方。她发觉他不看电影却总是回头看她，其实那也不是为了看她而是为了引起她的注意。梅梅很厌恶这种粗俗的把戏。最后，马乌里肖·巴比伦过来和奥雷里亚诺第二打招呼，这时梅梅才知道他曾在奥雷里亚诺·特里斯特简陋的发电厂工作过，因而在她父亲面前也像对待上级一样恭敬。这一幕减轻了她对他高傲的反感。他们没有单独见过面，除了打招呼没有谈过一句话，但那天夜里她却梦见他在一场海难中救了自己，而她没有任何感激之情还大为光火。这看起来像是自己给了他一个他所渴求的机会，而那却是她不希望发生的，不仅对马乌里肖·巴比伦，对所有属意于她的男人都是如此。故此她在梦醒后很生自己的气，因为不但没有对他产生厌恶，反而感到一种无法压抑的冲动想要见他。一个星期以来，这冲动日益强烈，到星期六更达到顶点，她得极力控制才能在打招呼时不让他看出自己的一颗心快要跳出来。她在愉悦与愤怒交杂的感觉中昏了头，第一次伸出手去，而直到此刻马乌里肖·巴比伦才握上她的手。梅梅在刹那间又为自己的冲动而悔恨，可发现他的手也同样冰凉汗湿，心中的悔恨旋即化作残酷的满足感。当天晚上，她明白如果不让马乌里肖·巴比伦意识到他只是痴心妄想，自己就不会有片刻安宁，于是整个星期都在为此奔忙。她耍尽一切花招想让帕特里夏·布朗陪自己去要车，却没能成功。最后，她利用了那个正在马孔多度假的美国红发男孩，借口想见识新型号汽车让他带自己来到厂里。在看见马乌里肖·巴比伦的那一刻，梅梅便无法再欺骗自己，明白事实上是自己无法抵抗与他单独见面的欲望。她也确信对方一见自己来到便明白了这一点，不由又是一阵气恼。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3372, 86, 83, 15, 15, '第15章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3290, 86, 1, 1, 1, '第1章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3292, 86, 3, 1, 1, '当吉卜赛人再来的时候，乌尔苏拉已经发动全村的人加以抵制。但好奇心胜过了恐惧，因为这一次吉卜赛人走遍全村，利用各式乐器制造出震耳欲聋的响声，叫卖人还声称将要展出纳西安索人最神奇的发明。因此全村人都去了帐篷，付上一个铜板 ① 就看到了青春焕发的梅尔基亚德斯：身体痊愈，皱纹平复，全新的牙齿闪闪发亮。凡是还记得他的牙龈如何毁于坏血病、脸颊如何松弛、嘴唇如何干瘪的人，面对这一无可置疑的明证，都不禁为吉卜赛人的魔力而惊栗。梅尔基亚德斯将镶在牙床上的牙齿完好无损地摘下并向观众展示——那一瞬间他变回了往昔的老朽模样——随后又戴上牙齿展露出重获青春的微笑，这时惊慌变成了恐惧。即便是何塞·阿尔卡蒂奥·布恩迪亚都觉得梅尔基亚德斯的知识已经达到令人无法企及的程度，不过当后者私下里给他讲解了假牙的原理后，他随即感到一阵畅然。他觉得这一切如此简单而神奇，一夜之间又对炼金研究完全失去了兴趣，陷入新的情绪危机，无心饮食，整天在家中踱步。“世上正发生着不可思议的事情，”他对乌尔苏拉说，“就在那边，在河的另一边，各种魔法机器应有尽有，而我们却还像驴子一样生活。”从马孔多创建之初就认识他的人，都惊讶于他在梅尔基亚德斯影响下发生的变化。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3399, 86, 110, 20, 20, '第20章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3291, 86, 2, 1, 1, '那一时期，梅尔基亚德斯在以惊人的速度衰老。他头几回来访时看上去和何塞·阿尔卡蒂奥·布恩迪亚岁数相仿，但当后者仍然力气过人，楸住马耳朵就能将马掀翻的时候，吉卜赛人却好像已被某种顽疾击垮。实际上，那是他无数次周游世界时染上多种罕见疾病的结果。他在帮助何塞·阿尔卡蒂奥·布恩迪亚搭建实验室时亲口说过，死神一直追随他的脚步，嗅闻他的行踪，但尚未下定决心给他最后一击。他经历了危害人类的各种疾病和灾难幸存下来。他在波斯得过蜀黍红斑病，在马来群岛患上坏血病，在亚历山大生过麻风病，在日本染上脚气病，在马达加斯加患过腺鼠疫，在西西里碰上地震，在麦哲伦海峡遭遇重大海难，却都大难不死。这个天赋异禀，自称掌握了诺查丹玛斯 ① 之钥的人是个阴沉的男子，裹在一团愁云惨雾里，目光斜曳像是能够看透一切。他总戴着一顶黑色大礼帽，活像乌鸦展开的翅膀，身穿一件天鹅绒坎肩，染着沧桑岁月的苔印。他智慧无边又神秘莫测，但还是有着凡人的一面，未能摆脱日常生活中琐碎问题的烦扰。他抱怨着衰老和病痛，为经济上微不足道的困窘而难过 ； 他很久以前就不再展露笑容，因为坏血病夺去了他所有的牙齿。在一个闷热的正午，他吐露了心声，何塞·阿尔卡蒂奥·布恩迪亚确信那是一段伟大友情的开始。孩子们听着他的神奇故事，目瞪口呆。奥雷里亚诺那时只有五岁，他一生都将记得，那个下午吉卜赛人如何坐在窗前金属的反光中，用管风琴般深沉的声音揭示最幽暗的想象地域，热得从太阳穴流下油腻的汗水。他的哥哥何塞·阿尔卡蒂奥，将会把这奇妙的形象作为记忆遗产，传给所有后世子孙。乌尔苏拉却对这次来访印象恶劣，因为她走进房间的时候，正赶上梅尔基亚德斯一分神，打破了一个装有二氯化汞的小瓶。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3295, 86, 6, 2, 2, '第2章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3307, 86, 18, 3, 3, '“所以，如果您想留在这里，和其他普通居民一样，我们非常欢迎。”何塞·阿尔卡蒂奥·布恩迪亚总结道，“但如果您是来制造混乱，强迫大家把房子漆成蓝色，那么您可以收拾起家什，从哪儿来回到哪儿去。因为我的家一定要像鸽子一样雪白。”
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3297, 86, 8, 2, 2, '那段时期有个女人常来家里帮忙做家务，她神情欢快，言语无忌，举止诱人，还会用纸牌算命。乌尔苏拉对她说起自己的儿子, 认为他惊人的尺寸和表兄的猪尾巴一样不正常。那女人爆出一阵直率的笑声，仿佛一条玻璃溪流在整个家中荡漾。“正相反，”她说，“他会幸福。”为了证实这一预言，没过几天她就把纸牌带了来，与何塞·阿尔卡蒂奥一起反锁在厨房旁边的谷仓里。她镇静自若地把纸牌摊开在一张旧木工桌上，随意闲扯着，而那年轻人等在她身旁，厌烦多过好奇。突然，她伸手摸了他一下。“好家伙。”她实实被吓到，说不出别的话来。何塞·阿尔卡蒂奥感到骨头里充满了泡沬，并伴随着一种无力的恐惧，以及哭泣的强烈欲望。女人没有给他任何暗示，但何塞·阿尔卡蒂奥整夜都在烟味中寻找她，那气味本是从她腋下逸出，也渗入到他的皮肤里面。他想一直和她在一起，想让她做自己的母亲，想永远待在谷仓里，想听她说“好家伙”，想让她再一次摸自己并对自己说“好家伙”。一天，他终于忍不住去她家找她。那是一次莫名其妙的礼节性拜访，他坐在客厅里自始至终没说一句话。那个时候他失去了欲望。他觉得她变了，与她的气味在自己心中幻化出的那个形象完全不同，仿佛成了另一个人。喝过咖啡，他沮丧地离开。当天晚上，在失眠的惊恐中，他恢复了强烈的欲望，只是此刻渴望的不是谷仓里的她，而是下午见到的她。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3296, 86, 7, 2, 2, '就这样，他们开始了翻越山脉之旅。何塞·阿尔卡蒂奥·布恩迪亚有许多像他一样年轻的朋友，他们因要探险而欢欣鼓舞，都拆掉自家房子，带上女人孩子上路，朝着没有人向他们应许过的土地进发。出发之前，何塞·阿尔卡蒂奥·布恩迪亚将长矛埋在院子里，又把自己那些出色的斗鸡一只只砍下脑袋，深信这样能够给予普鲁邓希奥·阿基拉尔些许安慰。乌尔苏拉只带了一箱嫁衣、少许家用物品以及那个小匣子，匣里装着从父亲那里继承的金币。他们没有预定的路线，只想朝着与里奥阿查相反的方向进发，为的是不留下任何踪迹，不碰见任何熟人。那是一场荒唐的旅行。走了十四个月后，吃猴肉喝蟒蛇汤坏了胃口的乌尔苏拉生下一个健全的男婴。她的腿肿得变了形，静脉曲张得像水泡鼓起，因此一半的路程都躺在吊床上，由两个男人用一根棍子抬着走。孩子们虽然肚皮干瘪、眼神倦怠，看起来很可怜，实际上倒比父母更能适应旅行，大部分时间都过得很愉快。经过将近两年的跋涉，一天早上，他们成为第一批见到山脉西坡的人。从云雾弥漫的山顶望去，大沼泽无边无际的水面一直延伸到世界的另一边。然而，他们从未找到大海。在沼泽间盲目行进了几个月之后，一天晚上，他们远离了路上遇见的最后一拨土著，在一条乱石累累的河流岸边扎了营，那河水仿佛冰冷的玻璃在流动。若干年后，在第二次内战期间，奥雷里亚诺·布恩迪亚上校曾试图走同一条路奇袭里奥阿査，行进了六天后他意识到这完全是疯狂之举。在沿河驻营的那天晚上，他父亲的追随者们看起来像是身处绝境的遇难者，但人丁倒比旅行前更为兴旺，并且所有人都期望能老死善终，而后来也都如愿以偿。那天晚上，何塞·阿尔卡蒂奥·布恩迪亚梦见那个地方耸立起一座喧嚣的城市，家家户户以镜子为墙。他询问这是什么城市，得到的回答是一个他从未听说、也没有任何含义的名字，但那名字却在梦中神秘地回响：马孔多。第二天，他说服众人相信永远也找不到大海了。他又下令在河边最凉爽的地方砍伐树木辟出空地，就在那里建起了村庄。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3304, 86, 15, 3, 3, '还是奥雷里亚诺想出了办法，在接下来的几个月中帮助人们抵御失忆。这发现本出于偶然。他属于第一批病人，已是老练的失眠者，并借此掌握了高超的金银器工艺。一天他在寻找用来捶打金属箔片的小铁砧时，却想不起它的名称。父亲告诉他：“砧子。”奥雷里亚诺把名称写在纸上，用树胶贴在小铁砧底部：砧子。这样，他相信今后就不会再忘记。当时他还没想到这便是失忆开始的症状，因为那东西的名称本不好记。没过几天，他发现自己对实验室里几乎所有器物都叫不出名来。于是他依次注明，这样只需看一下标签就可以辨认。当父亲不安地告诉他自己童年最深刻的记忆都已消失时，奥雷里亚诺向他传授了这一方法。何塞·阿尔卡蒂奥·布恩迪亚先在家中实行，而后推广到全镇。他用小刷子蘸上墨水给每样东西注明名称： 桌子，椅子，钟，门，墙，床，平锅 。他又到畜栏为动物和植物标上名称： 奶牛，山羊，猪，母鸡，木薯，海芋，香蕉 。随着对失忆各种可能症状的研究不断深入，他意识到终会有那么一天，人们即使能通过标签认出每样事物，仍会记不起它的功用。于是他又逐一详加解释。奶牛颈后所挂的名牌便是一个极好的例子，体现出马孔多居民与失忆作斗争的决心： 这是奶牛，每天早晨都应挤奶，可得牛奶。牛奶应煮沸后和咖啡混合，可得牛奶咖啡。 就这样，人们继续在捉摸不定的现实中生活，只是一旦标签文字的意义也被遗忘，这般靠词语暂时维系的现实终将一去不返。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3301, 86, 12, 3, 3, '第3章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3315, 86, 26, 5, 5, '不料一个更大的障碍突然出现，并且无法挽救，迫使婚礼再次无限期延迟。婚期前一个星期，小蕾梅黛丝半夜醒来，内脏打嗝般撕裂，火热的汁液爆涌浸透全身。三天后她被自己的血毒死，一对双胞胎也横死腹中。阿玛兰妲受到良心的谴责。她曾切切祈求上帝，希望发生某种可怕的事情免得自己向丽贝卡下毒，因此对蕾梅黛丝的死怀有负罪感。那并不是她日夜祈祷所期盼的障碍。蕾梅黛丝为这个家带来了欢快气息。她和丈夫在作坊旁收拾出一间小屋，用刚刚告别的童年时代的娃娃和玩具装饰一新。她欢快的活力溢出房间四壁，像生机盎然的和风吹过秋海棠长廊。她从清晨便开始唱歌。她是唯一敢在丽贝卡与阿玛兰妲争吵时从中斡旋的人。她担负起照顾何塞·阿尔卡蒂奥·布恩迪亚的繁重任务。她为他送去食物，每日伺候他大小便，用肥皂和丝瓜瓤给他擦洗，为他除去头发胡须里的跳蚤和虱子，还让棕榈叶顶棚保持完好并在暴风雨天气用防水帆布加固。最后几个月，她已经能够用简单的拉丁语与他沟通。当奥雷里亚诺和庇拉尔·特尔内拉的儿子出生后被送到家里，并在家中举行仪式命名为奥雷里亚诺·何塞，蕾梅黛丝决定把他认作自己的长子。她这种母性本能令乌尔苏拉惊讶不已。就奥雷里亚诺而言，他在她这里找到了生存的意义。他整日在作坊干活，蕾梅黛丝会在上午送去一杯不加糖的咖啡。夫妇俩每天晚上都去摩斯科特家。奥雷里亚诺和岳父一局接一局地玩多米诺骨牌，蕾梅黛丝则与姐姐们聊天，或和母亲商量大人的事情。与布恩迪亚家的联姻稳固了堂阿波利纳尔·摩斯科特在镇上的权威。他频繁前往省城，结果成功让政府在镇上建立一所学校，便交由继承了祖父教学热忱的阿尔卡蒂奥掌管。他说服了大多数人家将房子漆成蓝色以纪念国家独立日。应尼卡诺尔神甫之请，他将卡塔利诺的店铺迁往一条偏僻的街道，还关闭了镇中心多处生意兴隆却有伤风化的场所。他带回六名荷枪警察来维持秩序，这时却没人想起当初镇上不准有武装人员的协议。奥雷里亚诺对岳父的工作效率颇为欣赏。“你也会变得像他一样胖。”他的朋友们对他说。但长久端坐着干活，令他颧骨线条更明显，使他眼神更锐利，却没有增加他的体重，也不曾影响他的冷静性格，相反还加深了他唇间的笔直线条，那代表着孤独的沉思和无情的决断。他和妻子在双方家里都成功唤醒了深厚的亲情，因而当蕾梅黛丝宣告怀孕的时候，甚至连丽贝卡和阿玛兰妲都暂时休战，忙着编织蓝毛衣——如果生的是男孩，还有红毛衣——如果生的是女孩。几年以后面对行刑队，阿尔卡蒂奥最后想到的人也是她。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3299, 86, 10, 2, 2, '一月里一个星期四的凌晨两点，阿玛兰妲出生了。在其他人进入房间之前，乌尔苏拉先把她浑身上下细细检查了一遍。她又轻又湿像条蝌蜴，不过身体所有部位都属于人类无疑。奥雷里亚诺发现家里挤满了人，才知道这一新闻。他趁着混乱溜出去找哥哥，因为哥哥从十一点就不在床上了。这一决定如此仓促，他甚至没时间考虑要如何把哥哥从庇拉尔·特尔内拉的卧室里拉出来。他围着房子转了几个小时，吹口哨打暗号，快天亮时才不得不回去。在母亲的房间里，他看到何塞·阿尔卡蒂奥正在逗弄初生的小妹妹，脸上挂着天真无辜的笑容。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3302, 86, 13, 3, 3, '家人没有办法，只得把她收留下来。奥雷里亚诺耐心地在她面前从头到尾念了一遍圣徒节期表，但她对所有名字都没有反应，家人只好根据信中她母亲的名字叫她丽贝卡。那时马孔多还没死过人，自然没有墓地，他们只得暂时将骨殖袋收藏起来，等将来有合宜的地方再下葬。很长一段时间这些遗骨在家中到处碍事，总在意想不到的地方出现，像母鸡抱窝似的咯咯作响。丽贝卡过了很久才融人家庭生活。她总是缩到家中最偏僻的角落，坐在摇椅上吮吸手指。什么都无法引起她的注意，除了那些钟表奏出的音乐，她每过半小时就会瞪着受惊的眼睛四下寻找，仿佛想在空中某个位置找到那乐声。数天过去，她什么也不肯吃。谁都无法理解她居然没有饿死，后来印第安人——他们一刻不停、悄无声息地在家里走来走去，一切都逃不过他们的眼睛——发现她只喜欢吃院子里的湿土和用指甲刮下的石灰墙皮。显然她父母或是其他抚养人曾斥责过这一恶习，因为她总是心有愧疚暗中行事，藏起口粮来等没人时再享用。从那以后，家里开始对她严加监视。他们在院子里洒牛胆汁，往墙壁上涂辣椒油，相信用这些方法可以遏制她的恶习。然而她找寻泥土时显得异常狡黯机智，乌尔苏拉不得不采取更严厉的手段。乌尔苏拉在小锅里放入橘汁，兑上大黄晾了一整夜，次日让她空腹喝下。没人说过这就是治疗食土怪癖的特效药，但乌尔苏拉却相信任何苦味的食物进入空腹都会令肝脏产生反应。丽贝卡拼命反抗，力气之大与瘦小身量根本不符，他们不得不像扳倒一头小牛犊似的逼她服药，却难以制止她的乱踢乱踹，无法忍受她在撕咬和吐口水之余古怪难解的呼号。印第安人听得目瞪口呆，说那是他们语言中最污秽的辱骂。乌尔苏拉知道后，在药物治疗之外又加上了皮带抽打。永远无从确知，究竟是大黄或毒打，还是二者一起最终发挥了效用，总之几个星期后丽贝卡显出康复的迹象。她加入到阿尔卡蒂奥和阿玛兰妲的游戏中，他们把她当姐姐看待。她胃口颇佳，刀叉也用得不错。不久家人又发现她的卡斯蒂利亚语说得和印第安土语一样流利，手头活计也干得出色，还会哼唱音乐钟奏出的华尔兹舞曲，配上滑稽的自编歌词。大家很快就接纳她为家庭新成员。她和乌尔苏拉最亲，连乌尔苏拉的亲生儿女都比不上。她管阿玛兰妲和阿尔卡蒂奥叫小妹妹小弟弟，称奥雷里亚诺为叔叔，呼何塞·阿尔卡蒂奥·布恩迪亚为爷爷。于是，她和其他家人一样名正言顺地用上了丽贝卡·布恩迪亚的姓名，那也是她一生用的唯一姓名，直到去世从未玷污。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3308, 86, 19, 4, 4, '第4章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3303, 86, 14, 3, 3, '几个星期后，比西塔西翁的恐惧似乎平息了下去。有天晚上何塞·阿尔卡蒂奥·布恩迪亚在床上辗转反侧，难以入睡。乌尔苏拉也醒着，问他怎么了，他回答：“我又想起了普鲁邓希奥·阿基拉尔。”他们一刻也没睡着，但到了第二天感觉疲劳尽去，便把不眠之夜抛在了脑后。午饭时候，奥雷里亚诺惊异地讲起他如何一整夜都在实验室忙着给一枚别针镀金，准备在乌尔苏拉的生日送给她，但此刻却仍然感觉良好。到了第三天，大家在该入睡的时刻还是毫无睡意，这才意识到已连续五十多个小时没有合眼，终于警觉起来。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3305, 86, 16, 3, 3, '马孔多欢庆重获记忆的同时，何塞·阿尔卡蒂奥·布恩迪亚和梅尔基亚德斯正在重温往昔的友情。老吉卜赛人准备就此留在镇上。他的确一度死去，但难以忍受孤独又重返人世。他因执著于生命受到惩罚，被剥夺了一切超自然能力，又被逐出了部落，便决定到这个死神尚未光顾的偏远角落栖身，专心创立一家银版照相术工作室。何塞·阿尔卡蒂奥·布恩迪亚还从未听说过这一发明，他看到自己和全家人的形象在一块闪光的金属版上凝固成永恒，顿时惊诧得说不出话来。在当时拍下的一张老照片上，何塞·阿尔卡蒂奥·布恩迪亚灰色的头发乱蓬蓬，硬挺的衬衫领子用一粒铜扣扣上，神情庄严中藏着惊诧，乌尔苏拉乐不可支地说他像“一位受惊的将军”。何塞·阿尔卡蒂奥·布恩迪亚在那个晴朗的十二月上午的确受惊不小, 他以为人的形象一旦被摄到金属版上，生命就会随之日渐销蚀。有趣的是，乌尔苏拉一反常态，消除了丈夫的疑虑，并且拋下往曰的怨气，决定让梅尔基亚德斯留下一起生活，只是她一直拒绝拍照，因为——按她自己的原话——不愿意将来让儿孙笑话。那天上午她给孩子们穿上最好的衣裳，在他们脸上都搽了粉，还让每人喝下一勺骨髓糖浆，好让他们面对梅尔基亚德斯壮观的机器保持近两分钟的安分。在这张唯一的全家福照片上，奥雷里亚诺身穿黑色天鹅绒正装，夹在阿玛兰妲和丽贝卡中间，那倦怠的模样和深邃的眼神与多年以后面对行刑队时一般无二。但那时他尚未感觉到命运的预示。他已是熟练的金银匠，凭着精湛的手艺在整个大泽区享有盛名。他的作坊与梅尔基亚德斯杂乱的实验室合在一起，屋里几乎听不到他的呼吸声。他父亲和老吉卜赛人为诺查丹玛斯的预言大声争论，瓶子和托盘撞击作响，酸液不时在磕磕碰碰中打翻，溴化银到处流淌，而他仿佛置身于另一个时空。他全神投入工作，加上经营有道，不久赚取的收人就超过了乌尔苏拉的美味糖果小动物生意。但所有人都觉得奇怪，他明明已是个十足的男子汉，竟然还没有结识女人。事实上他的确没有。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3317, 86, 28, 5, 5, '奥雷里亚诺是唯一关心他们的人。他给他们买了一些家具，并送钱过去，直到何塞·阿尔卡蒂奥恢复常态，开始耕种与家中院子相邻的无主土地。阿玛兰妲却永远无法摆脱对丽贝卡的怨恨，尽管生活为她带来了超出梦想的满足：乌尔苏拉不知如何洗刷耻辱，她主动提出让皮埃特罗·克雷斯皮每个星期二仍来家中共进午餐，后者平和而不失尊严地战胜了挫折。出于对这一家人的尊敬，他在帽子上仍然系着黑纱，并很乐意亲近乌尔苏拉，为她带来异国礼物：葡萄牙沙丁鱼，土耳其玫瑰果酱，还有一次是一条精美的马尼拉大披巾。阿玛兰妲总是亲切殷勤地款待他。她揣测他的喜好，为他扯掉衬衫袖口的脱线，在他过生日时送上一打绣着他姓名缩写的手帕。每个星期二吃过午饭，她在长廊里绣花，他陪伴一旁，其乐融融。对皮埃特罗·克雷斯皮而言，这个他一向当小女孩对待的姑娘不啻全新的发现。她虽然外表缺乏魅力，却拥有罕见的感受力，能体会世间万物的美好，还蕴含一种不为人知的柔情。一个星期二，发生了众人意料中早晚会发生的事：皮埃特罗·克雷斯皮向她求婚。她没有停下手里的活计，等耳边火热的红潮退去才开口，镇静的声音显出老成持重。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3338, 86, 49, 9, 9, '他没下命令，的确没有。但十五天后特奥菲洛·巴尔加斯将军遇伏，在乱刀下被剁成肉酱，大权落到奥雷里亚诺·布恩迪亚上校手中。就在他的权威被所有起义军将领承认的当天夜里，他猝然惊醒，叫喊着要毯子。一种内在的寒冷直入骨髓，即使烈日当空也让他不堪其苦，好几个月都难以安眠，到最后成了习惯。权力带来的陶醉消失于阵阵烦恼之中。他试图找到抵御寒意的方法，就下令枪毙了提议暗杀特奥菲洛·巴尔加斯将军的年轻上尉。他的命令总是在发布之前，甚至早在他动念之前，就已被执行，而且总会执行得超出他事先所敢想望的范围。他大权独揽却在孤独中陷入迷途，开始失去方向。被占领市镇中人们的欢呼令他厌烦，因为他们也曾向他的敌人发出同样的欢呼。每到一处，他总能见到那些少年用和他一模一样的眼睛望着他，用和他一模一样的声音同他说话，向他致意时的警惕神色和他回应时的神色一般无二，并且都自称是他的儿子。他感觉自己被分裂，被重复，从未这般孤独。他确信手下的军官对自己撒谎。他对马尔伯勒公爵也产生了敌视。“最好的朋友，”那时他常这样说，“是刚死去的朋友。”他厌倦了战事无常，身陷这场永无休止的战争的恶性循环中总在原地打转，只不过一次比一次越发老迈，越发衰朽，越发不知道为何而战、如何而战、要战到何时。总有人待在粉笔圈外，手头拮据的人，儿子得了百日咳的人，因为受不了嘴里粪便一样的战争味道而想一睡不醒、但仍鼓足最后的气力报告的人：“一切正常，我的上校。”正常恰恰是这场无尽的战争最可怕的地方：什么都不曾发生。他深陷孤独，不再感知到预兆，他为了逃避必将陪伴他终生的寒意回到了马孔多，在最久远的回忆中寻求最后的慰藉。他如此懒怠，当听说党组织派来一个代表团商议如何打破战争的僵局时，也只是在吊床上翻了个身，甚至没有完全醒转。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3323, 86, 34, 6, 6, '他无须等上很久，因为自由派失利的消息不断传来，而且越发确切。三月末，提前到来的雨季的一个清晨，几星期以来紧张的平静被尖厉的军号声猝然打破。随后一声炮响，教堂的尖塔轰然倒塌。阿尔卡蒂奥的抵抗决心与疯狂无异。他手下不过五十来人，装备低劣，每人至多能分到二十发子弹。但这些人，他旧日的学生，受他那慷慨激昂的宣言所鼓动变得热血沸腾，时刻准备着为一项无望的事业献出生命。纷乱的军靴声，互相矛盾的号令声，令大地震颤的炮火声，慌乱的射击声，无谓的军号声——在这片混乱中，自称格雷戈里奥·史蒂文森上校的男人设法与阿尔卡蒂奥对上了话。“请不要让我蒙受羞耻，戴着镣铐穿着女人的破烂死掉，”他说，“如果我非死不可，请让我战斗而死。”他说服了他。阿尔卡蒂奥下令给他一支枪和二十发子弹，让他带着五个人保卫军营，他自己则领着参谋部冲向抵抗前线。他没能到达通往大泽区的路。街垒都已被清除，守军在无遮无挡的街道上作战，他们先用步枪直到子弹耗尽，然后用手枪对步枪，最后展开肉搏战。在镇子失守前，一些用棍棒和菜刀武装起来的妇女冲到街上。阿尔卡蒂奥在混乱中发现阿玛兰妲正像个疯子一样四处找他，身上还穿着睡衣，手持何塞·阿尔卡蒂奥·布恩迪亚的两把老式手枪。他把步枪交给一位在战斗中弄丢了武器的军官，拉上阿玛兰妲逃向邻近的街巷带她回家。乌尔苏拉等在门口，纷飞的流弹已在邻居家墙上打出一个窟窿，她却全不在乎。雨停了，街面变得像泡化的肥皂又软又滑，而且黑暗中辨不出远近距离。阿尔卡蒂奥把阿玛兰妲交给乌尔苏拉，想去对付两个从街角胡乱开枪的士兵，但老手枪在衣柜里收藏多年之后失去了效用。乌尔苏拉用身体护住阿尔卡蒂奥，想把他拉进家门。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3335, 86, 46, 8, 8, '当晚，他试图逃离马孔多时被捕，临行前他还给奥雷里亚诺·布恩迪亚上校写了一封长信，追緬当年想让战争更人道的共同理想，并祝愿他在对抗两党军人腐败和政客野心的战斗中获得最终胜利。次日，奥雷里亚诺·布恩迪亚上校和他在乌尔苏拉那儿共进午餐，他就被囚禁在那里等待革命军事法庭决定他的命运。这是一次家庭聚会。然而就在敌对双方忘却战事一起緬怀往昔的同时，乌尔苏拉心头却蒙上一层阴影，感觉自己的儿子才是外来的侵入者。她从看到他进门起就有这种感觉，那时一群喧嚣的军人护卫着他进来，搜遍各个房间确信没有危险才罢休。奥雷里亚诺·布恩迪亚上校不仅允许他们这样做，还颁下严令不准任何人走进他周围三米以内，甚至连乌尔苏拉也不例外，与此同时他的卫队在房子附近忙着设置岗哨。他身穿寻常粗布军装，没佩任何军衔标志，带马刺的长靴上沾满泥土和干血迹。他腰间佩戴手枪，枪套未扣，手永远按在枪柄上，与眼神一样显出高度的警觉与果断。他的前额如今分外开阔，像是被文火烤过。他的脸庞因加勒比海的盐分而皴裂，带着几分金属般的坚厉。他凭着某种活力胜过了迫近的衰老，只是这活力与内心的冷漠不无关联。他比离家时更高，更苍白嶙峋，开始表露不念旧情的迹象。“上帝啊，”乌尔苏拉心想，“他现在看起来什么事儿都干得出来。”他的确成了这样的人。他带给阿玛兰妲的阿兹台克头巾，他在午饭时的怀旧，他口中的趣闻逸事，都不过是昔日性情的残余。将死尸掩埋到公墓里的命令刚被执行，他就指派罗格·卡尔尼塞罗上校去敦促建立军事法庭展开审判，他自己则担负起推行激进改革的艰巨任务，决心将江河日下的保守党政权摧毁殆尽。“我们要赶在党内政客前面。”他对自己的顾问说，“等他们睁眼面对现实的时候，看到的就是既成事实。”就在此时，他决定审查百年来的地契，便发现了他哥哥何塞·阿尔卡蒂奥强占土地又将其合法化的行径。他将那些文书一笔勾销。最后出于礼貌，他搁下手头的事务，抽出一个小时去见丽贝卡通知他的决定。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3341, 86, 52, 9, 9, '此后的日子，他忙于毁去在世上留下的一切痕迹。他清理金银器作坊，只留下不带任何个人标记的用具；把自己的衣服送给勤务兵；怀着父亲当年埋葬刺死普鲁邓希奥·阿基拉尔的长矛时的忏悔心情，把武器埋在院子里。他只留下一把手枪，一发子弹。乌尔苏拉没有干涉他。她只是在他想要毁掉蕾梅黛丝的银版照片时，才上前劝阻。那照片保存在客厅里，由一盏长明灯照亮。“这张照片早就不属于你了，”她说，“这是留给全家的遗物。”到停战前夜，家里一件与他有关联的物事都没剩下。他带上装诗稿的箱子来到面包房，遇上桑塔索菲亚·德拉·彼达正准备点炉子。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3327, 86, 38, 7, 7, '并非所有的消息都是好的。奥雷里亚诺·布恩迪亚上校逃走一年后，何塞·阿尔卡蒂奥和丽贝卡搬进了阿尔卡蒂奥建起的房子。没人知道他阻止行刑的事。新家坐落在广场最好的一角，掩映在一棵巴旦杏树的浓荫里，树上足有三个知更鸟的鸟巢。一扇大门迎送访客, 四扇明窗承接阳光，他们就在这房子里安下热情好客的新家。丽贝卡旧日的女伴，包括摩斯科特家四个尚未出嫁的女儿，重新聚在一起刺绣，就像数年前在秋海棠长廊里一样。何塞·阿尔卡蒂奥继续享受掠夺来的土地收益，他的所有权巳得到保守党政府的承认。每天下午都可以看见他骑马归来，扛着双铳猎枪，带着猎狗，一串兔子挂在马鞍上。九月的一天下午，眼看暴风雨迫近，他比平时提前回了家。他到饭厅和丽贝卡打过招呼，把狗拴在院中，又将兔子挂在厨房准备晚些时候腌起来，随后去卧室换衣服。丽贝卡事后声称丈夫进卧室时自己正在浴室，丝毫没有察觉。这一说法难以令人信服，但又没有更可信的其他说法，另外谁也想不出丽贝卡会有什么动机谋杀令她幸福的男人。这也许是马孔多唯一从未解开的谜团。何塞·阿尔卡蒂奥刚关上卧室的门，一声枪响震彻全屋。一道血线从门下涌出，穿过客厅，流到街上，沿着起伏不平的便道径直向前，经台阶下行，爬上路栏，绕过土耳其人大街，右拐又左拐，九十度转向直奔布恩迪亚家，从紧闭的大门下面潜入，紧贴墙边穿过客厅以免弄脏地毯，经过另一个房间，划出一道大弧线绕开餐桌，沿秋海棠长廊继续前行，无声无息地从正给奥雷里亚诺·何塞上算术课的阿玛兰妲的椅子下经过而没被察觉，钻进谷仓，最后出现在厨房，乌尔苏拉在那里正准备打上三十六个鸡蛋做面包。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3343, 86, 54, 10, 10, '第10章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3345, 86, 56, 10, 10, '就像他漫长一生中所有的好事一样，这笔巨大的财富也是出于偶然。直到战争末期，佩特拉·科特斯还在靠卖彩票糊口，奥雷里亚诺第二则不时洗劫乌尔苏拉的储钱罐来过活。他们成了轻浮的一对，只知道夜夜睡在一起，即使在禁止寻欢的日子也不例外，在床上嬉闹直到天明。“这女人非毁了你不可，”乌尔苏拉看着曾孙梦游般走进家门，朝他大喊起来，“她把你变傻了，过不了两天你肚子里就会生只癞蛤蟆，疼得直不起腰。”何塞·阿尔卡蒂奥第二过了很久才发现他冒名顶替自己，很难理解兄弟的痴狂。在他的印象中，佩特拉·科特斯是个很平常的女人，在床上甚至有些慵懒，完全不具备勾人情愫的魅力。对乌尔苏拉的呼号和兄弟的嘲弄，奥雷里亚诺第二一概充耳不闻，他那时只想着找个营生养活佩特拉·科特斯，在某个狂欢之夜与她死在一起，死在她身上，死在她身下。当奥雷里亚诺·布恩迪亚上校终于抵不住安享晚年的诱惑，重开作坊，奥雷里亚诺第二觉得制作小金鱼是桩不错的生意。他在那间酷热的小屋里待了很久，看着上校在大彻大悟后生发出难以想象的耐心，让坚硬的金属片在手中渐渐变成金色的鱼鳞。他觉得这活计太过费力，而他又无时无刻不思念着佩特拉·科特斯，因此三个星期后便彻底从作坊消失了。正是在那段时间，佩特拉·科特斯忽然想到卖彩票抽兔子的主意。她的兔子不断繁殖生长，速度之快甚至没等彩票卖完就已发育成熟。开始的时候，这种惊人的繁衍并没有引起奥雷里亚诺第二的注意，直到后来市镇上的人都厌烦了兔子彩票，一天晚上他听到隔着院墙传来阵阵喧闹声。“别担心，”佩特拉·科特斯说，“是兔子。”两人再没睡着，被兔子的忙碌声吵了一夜。天亮时，奥雷里亚诺第二打开房门，看见院里满是兔子，在晨光中一片青蓝。佩特拉·科特斯笑弯了腰，忍不住跟他开个玩笑。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3333, 86, 44, 8, 8, '乌尔苏拉那时还不知道将少女送进军人卧室的习俗，那就像把母鸡赶到良种公鸡那里去。但在这一年她有了充分的了解：又有九个奥雷里亚诺·布恩迪亚上校的孩子被送到家里起名。其中最大的已过十岁，长相奇特，肤色黝黑，眼睛碧绿，与父家没有丝毫相似。送来的孩子有各种年龄各种肤色的，但都是男孩，都带着落落寡合的神情，显示出毋庸置疑的血缘归属。其中有两个格外突出。一个身材魁伟与年龄不符，打碎了许多花瓶和餐具，双手仿佛拥有损坏一切所碰东西的特性。另一个一头金发，长着母亲那样的蓝眼睛，留着女人一样的长鬈发。他走进家里，一副熟门熟路的样子，仿佛就在这里长大。他径直来到乌尔苏拉卧室里的一个箱子前，说：“我要上弦的跳舞女郎。”乌尔苏拉吓了一跳。她打开箱子，在梅尔基亚德斯时期落满尘灰的旧物中翻寻，找到了包裹在一双长袜中的上弦跳舞女郎，这东西是当初皮埃特罗·克雷斯皮带到家里的，此后被人遗忘了。不到两年内，他们为上校在战场上一路播撒的儿子命了名，都叫奥雷里亚诺，姓氏则随母亲：共计十七个。起初，乌尔苏拉还往孩子的口袋里塞满钱，阿玛兰妲则努力争取把他们留下来抚养，但后来她们只是送一份礼物，并担当教母。“我们起了名就行了。”乌尔苏拉一边说，一边在小本子上记下母亲的姓名地址及孩子出生的时间地点, “奥雷里亚诺一定算得清楚，等他回来自己拿主意吧。”吃午饭时，她对蒙卡达将军谈起这意外的人丁兴旺，希望奥雷里亚诺·布恩迪亚上校能回来一次，和所有儿子在家中团聚。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3337, 86, 48, 9, 9, '那天下午赫里内勒多·马尔克斯上校收到了奥雷里亚诺·布恩迪亚上校的电报。那是一次例行公事的谈话，没有为胶着的战局带来任何突破。谈话即将结束时，赫里内勒多·马尔克斯上校望着荒凉的街道、巴旦杏树上凝结的水珠，感觉自己在孤独中迷失了。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3328, 86, 39, 7, 7, '奥雷里亚诺·布恩迪亚上校凯旋归来，但他并没有为事情的这种表象而兴奋。政府军未作抵抗便放弃许多村镇，这在自由派民众当中激发的胜利憧憬不宜打破，然而革命者了解真相，奥雷里亚诺·布恩迪亚上校更是如此。此时他手下士兵超过五千，控制着沿海两个州，但他清醒地意识到自己已背海受困，并陷入了混乱的政治环境之中，无怪乎当他下令重建毁于政府军炮火的教堂尖塔时，尼卡诺尔神甫在病榻上不禁感慨：“这实在荒唐，基督信仰的卫士摧毁教堂，共济会的人却下令重建。”为了寻找一条出路，他在电报室一待就是几个小时，与其他城镇的首领商谈，他日益确信战争已陷入僵局。每当自由派的捷报传来，就会有通报大肆庆贺，但他会在地图上标出实际进展，进而发现他们的队伍正在深入雨林，与疟疾和蚊虫作战，与现实背道而驰。“我们在浪费时间，”他向他的军官们抱怨，“只要党内那些混账东西还在乞讨国会的位子，我们就得接着浪费。”失眠的夜里，就在当死囚犯时待过的同一个房间，他仰面躺在吊床上，眼前浮现出那些身着黑衣的律师的形象，他们在黎明的寒意中离开总统府邸，竖起大衣领子遮住耳朵，搓手御寒，窃窃私语，庇身于凌晨时分昏暗的小咖啡馆，细细揣摩总统说“是”的时候真正想说什么，说“不”的时候又想说什么，甚至还推测总统心口不一的时候究竟想的是什么——而他此时在三十五度的高温中驱赶着蚊子，感到可怕的黎明正在迫近，到时他就只能下令让自己的人跳进海里。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3354, 86, 65, 12, 12, '第12章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3332, 86, 43, 8, 8, '听她说这话的人，也是她对其出示信件的第一个人，是保守党将军何塞·拉克尔·蒙卡达，战后马孔多的市长。“这个奥雷里亚诺，”蒙卡达将军说，“真可惜他不是保守党。”他的敬佩出自真心。像许多保守党人一样，何塞·拉克尔·蒙卡达为了捍卫自己的党派才参战，并在战场上获得了将军的头衔，但他无意成为职业军人。恰恰相反，他和党内许多同道一样，是反军事主义者。在他看来，军人都是些没有原则的懒虫、野心勃勃的阴谋家，惯于欺压平民乱中牟利。他聪明和善，性格开朗，胃口好，爱斗鸡，一度成为奥雷里亚诺·布恩迪亚上校最可怕的对手。他在沿海广阔区域内的职业军人中建立了自己的权威。曾有一次，他出于战略考虑被迫放弃一座据点让奥雷里亚诺·布恩迪亚上校的军队占领，同时留下了两封信。其中一封很长，他在信中邀请对手共同努力促使战争更人道。另一封写给他身陷自由派占领区的妻子，他请求将信送给她。从那以后，即使在战事最激烈的时期，两位指挥官仍会达成暂时休战的协定来互换战俘。那些战事间歇期洋溢着节庆气息，蒙卡达将军有了机会教奥雷里亚诺·布恩迪亚上校下象棋。他们成了好友。他们甚至考虑过这种可能性：团结两党的民众力量，肃清军人和职业政客的流毒，建立一个汲取了两党理论思想精华的人道主义政府。战争结束后，奥雷里亚诺·布恩迪亚上校铤而走险，不断起事，而蒙卡达将军被任命为马孔多的里正。他脱下军装，以不带武器的警察取代士兵，实行大赦法令，并救助一些阵亡自由党人的家属。他成功让马孔多提升为市，也因此当了第一任市长。他营造出安定的氛围，令战争成为昔日荒诞的噩梦。尼卡诺尔神甫被肝病高热折磨得奄奄一息，已由科罗奈尔神甫取代，后者被人称作“新手”，是第一次联邦战争中的老兵。布鲁诺·克雷斯皮与安帕萝·摩斯科特结了婚，他的玩具乐器店生意蒸蒸日上。他盖了一座剧院，成为许多西班牙剧团的巡演站点。那是一座宏伟的露天大厅，配有木制靠背椅，饰以古希腊面具的天鹅绒大幕。三个售票窗造成狮头形状，从大张的狮口出售戏票。学校也在那一时期重建，由堂梅尔乔·埃斯卡洛纳负责，他是一位从大泽区派来的老教师，让不用功的学生在院中石灰地面上跪着行走，让言语放肆的学生吃辣椒，家长们对此十分满意。奥雷里亚诺第二和何塞·阿尔卡蒂奥第二，桑塔索菲亚·德拉·彼达这对任性的双胞胎儿子，是第一批带着小黑板、粉笔和标有名字的小铝壶坐到教室里的学生。蕾梅黛丝遗传了母亲的美貌，开始被称为美人儿蕾梅黛丝。尽管时光流逝，丧事接二连三，苦痛不断增添，乌尔苏拉却并不显衰老。在桑塔索菲亚·德拉·彼达的帮助下，她将自己的甜食生意推上新的高峰，不仅在短短几年内挣回了儿子消耗于战争中的资财，还用纯金塞满了一个个葫芦埋在卧室里。“只要上帝还让我活着，”她时常这样说，“这个净出疯子的家里就缺不了钱。”就在这时候，奥雷里亚诺·何塞从尼加拉瓜联邦派军队里开了小差，跑到一艘德国船上当水手，最后出现在家中的厨房里。他壮实如马，肤色黝黑，头发浓密，像个印第安人。他怀着秘密的目的回来，一心要和阿玛兰妲结婚。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3353, 86, 64, 11, 11, '奥雷里亚诺·布恩迪亚上校的儿子们第二次造访马孔多时，其中的另一个，奥雷里亚诺·森特诺，也留下来和奥雷里亚诺·特里斯特一起干活。他属于最早一批来到家里受洗的人，乌尔苏拉和阿玛兰妲都清楚地记得他，因为短短几个小时内所有经过他手的易碎物品全被打个粉碎。时间的流逝遏制住当初的成长势头，他长成一个中等身材的汉子，天花疤痕十分醒目，但手上惊人的毁灭力量却丝毫未减。他甚至碰都没碰就已打碎无数盘子，费尔南达只得赶在自己仅存的昂贵餐具损失殆尽之前为他买来一套白镴 ① 餐具，但这些耐用的金属盘碟也很快釉彩剥落、扭曲变形。这种不可救药的能力令他本人也很恼火，不过他同时还拥有热忱可亲的气质，一见面就能贏得他人的信任，干活也十分出色。在很短的时间内，他大幅提高了冰块的产量，超出了本地市场的需求，奥雷里亚诺·特里斯特不得不考虑将生意扩展到大泽区的其他市镇。就在这时他突发奇想，这一设想不仅对工厂的现代化，甚至对市镇与外界的沟通都具有决定意义。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3350, 86, 61, 11, 11, '“我们家权势无比，财富无边，”她说道，“你也会成为女王的。”她信以为真，尽管家里将亚麻布铺上长桌又摆上银餐具，只是为了喝一杯掺水的巧克力、吃一块甜面包而已。直到婚礼那天，她还梦想着成为一个传奇国度的女王，尽管她父亲堂费尔南多为置办嫁妆不得不将房产抵押。这并非幼稚无知或是野心谵妄。她就是这样被培养成人的。从记事时起，她记得自己都是在刻有家族纹章的黄金溺盆里大小便。十二岁时第一次出家门，她去的不过是两个街区外的修道院，仍需乘坐马车前往。她的同学惊奇地发现她被单独隔开，坐在一把高背椅上，即使在休息时间也不和旁人混在一处。“她可不一般，”修女们解释道，“将来是要做女王的。”她的同学深信不疑，因为那时的她就已出落成她们从未见过的美貌、高贵又端庄的姑娘。八年之后，她学会了用拉丁语作诗，学会了弹奏古钢琴，学会了与绅士谈鹰猎术、和主教论护教学，学会了向外邦君主阐述人间政务、为教皇诠释天国事宜，却还是回到父母家中又编起花圈来。她发现屋里已变得空空荡荡，只剩下必需的家具，烛台和银餐具，其他家居物品都已一件件卖掉以负担她的学费。母亲因五点钟热病去世了。父亲堂费尔南多一身黑衣，戴着硬领，怀表的金链绕过胸前，他每星期一给她一枚银币作为家用，同时取走前一个星期编好的花圈。他一天大部分时间都关在书房里，少有的几回出门上街也都会在六点前回家，陪她一起念玫瑰经 ① 。她从未和任何人结下亲密的友情。她从未听说过令整个国家流血败落的频繁战事。她从未间断过每天下午三点倾听钢琴练习曲。她那做女王的梦想开始破灭时，大门上传来了两下急迫的门环敲击声。她打开门，面前是一位衣着得体的军人，举止庄重有礼，脸颊上有一道伤疤，胸前佩戴着一枚金质勋章。他和她父亲走进书房密谈。两个小时后，父亲来缝纫间找她。“请准备好行李，”他对她说，“你要长途旅行了。”她就这样被带到了马孔多。仅仅一天之内，生活粗暴地打碎了幻梦，将父母多年来极力向她隐藏的现实赤裸裸地全盘呈现。回家后，她把自己关在房里痛哭，毫不理睬堂费尔南多的哀求和解释，试图借此消抹这场耸人听闻的嘲弄造成的创伤。就在她下定决心终生不再走出卧室一步的时候，奥雷里亚诺第二赶来找她了。这一转机完全出乎意料，因为她当初又惊又怒、又羞又恼，便撒谎隐瞒了自己的真实身份。奥雷里亚诺第二出门来找她的时候，所掌握的真实线索只有两条：内地人的独特口音和编棕榈花圈的职业。他豁出一切寻找她。他凭着何塞·阿尔卡蒂奥·布恩迪亚翻越山脉创立马孔多那样的蛮勇，凭着奥雷里亚诺·布恩迪亚上校一次次徒劳发动战争那样的盲目骄傲，凭着乌尔苏拉一心延续家族血脉那样的疯狂执拗，寻找费尔南达时不曾有片刻气馁。当他问起何处出售棕榈花圈时，人们带他一家一家挑选。当他问起哪里有世上最美的女人时，所有的母亲都把自己的女儿带到他面前。在雾气弥漫的隘道间，在注定被遗忘的时光中，在幻灭的迷宫里，他一度迷失方向。他穿过一片黄色荒原，在那里回声重复着人的所思所想，焦虑引出预示未来的蜃景。徒劳寻找数星期后，他来到一座陌生的城市，城里所有的钟楼同时敲响丧钟。尽管从未见过，也从没听人描述过，他还是立即认出了被尸骨析出的石灰质侵蚀的外墙，被菌类蛀空木头的衰败凉台，以及钉在大门上，被雨水冲刷得模糊难辨，堪称世上最悲凉的纸板：出售棕榈花圈。从那一刻起到费尔南达将家里托付给女修道院院长照看后出发的那个寒冷早晨，修女们几乎来不及缝好嫁衣，并将烛台、银餐具、金溺盆，以及两百年间家业衰败后余下的无数无用的家什装进六个箱子。堂费尔南多婉拒了同去的邀请。他答应晚些时候等处理完手头的事务再去。他为女儿送上祝福后，又关在书房里, 用印有惨淡花饰和家族纹章的信笺给她写信，那是父女俩有生以来第一次充满人情味的交流。对费尔南达而言，这才是生活的真正开始。对奥雷里亚诺第二而言，这几乎同时是幸福的开端和结束。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3362, 86, 73, 13, 13, '家里不得不向邻居借床及吊床，让她们分成九组就餐，排定沐浴时刻，并借来四十张凳子好让这些穿着蓝色校服和男式靴子的姑娘安稳片刻。这是一次失败的邀请，因为这些唧唧喳喳的女学生刚刚吃完早饭，不一会儿又得开始排队吃午饭，然后是晚饭，整整一个星期只来得及去种植园散了一次步。到了晚上，修女们个个精疲力竭，无法动弹也无力再下达命令，而不知疲惫的女学生们仍在院中高唱乏味的校歌。一天，她们险些踩到乌尔苏拉身上，因为她总是坚持要帮忙，结果越帮越忙。另一天，修女们一阵大乱，因为奥雷里亚诺·布恩迪亚上校在栗树下小便，毫不顾及院中有女学生在场。阿玛兰妲也险些制造出恐慌，当时一位修女走进厨房看见她正往汤里放盐，一时觉得没话可说，便问她那白色粉末是什么。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3349, 86, 60, 11, 11, '第11章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3355, 86, 66, 12, 12, '奥雷里亚诺第二却对外乡人的潮涌而至兴奋不已。家里突然间挤满了陌生的来宾、世界各地的酒肉豪客，不得不在院中加盖卧室, 扩建饭厅，换上一张可供十六人就餐的新餐桌，并配上成套的新餐具，即使如此仍需排出班次轮流进餐。费尔南达压下疑虑，像款待国王一样招待最卑劣的客人，但他们却穿靴踩脏长廊地板，在花园里随地小便，到处铺席子午睡，言语间全然不顾女士的感受，毫无绅士风度可言。阿玛兰妲对入侵家中的人潮愤慨不已，恢复了旧时习惯回到厨房吃饭。奥雷里亚诺·布恩迪亚上校认定大多数人来作坊探访他并非出自善意或敬意，而是抱着瞻仰历史遗迹、观赏博物馆化石的猎奇心态，因此决定紧闭房门，此后便很少再见他坐在大门口。乌尔苏拉却不同，即使在步履蹒跚扶墙行走的日子里，每当火车驶来仍像孩童般兴奋。“鱼和肉都得做。”她下令给四个厨娘，她们在桑塔索菲亚·德拉·彼达的沉着指挥下忙碌着将一切准备到位。“什么都得做一些，”她说，“你永远不知道外乡人爱吃什么。”火车在一天中最炎热的时刻到达。午饭时，整个家在集市般的喧闹中震颤。那些汗流浃背的客人甚至不知道主人是谁，你推我搡地抢占餐桌上的有利位置，与此同时厨娘们忙不迭端上大锅大锅的汤、一罐罐炖肉、一瓢瓢蔬菜、一盘盘米饭，并用长柄勺不停地将整桶整桶的柠檬水舀迸杯里。家里乱成一片，费尔南达一想到不少人吃了两回便气恼不已，而且不止一次恨不得用市井小贩才说的粗话来发泄怒火，因为竟有昏了头的客人要找她结账。赫伯特先生来到马孔多已经一年多，人们只知道美国佬想在何塞·阿尔卡蒂奥·布恩迪亚当年带人寻找伟大发明时穿越的着魔之地上种植香蕉。奧雷里亚诺·布恩迪亚上校的另外两个儿子，额头上仍带着灰烬十字的印记，也被这热潮吸引而来。他们说明来意的一句话或许能代表所有人的心声。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3359, 86, 70, 13, 13, '然而，当乌尔苏拉意识到她已经没有足够的时间让何塞·阿尔卡蒂奧来坚定志向，立时因沮丧而陷入迷惘。她试图用眼睛去看那些本可以靠直觉看得更清楚的东西，于是开始频频出错。一天早上，她把一瓶墨水误当作花露水倒在孩子头上。她执意四处插手却造成无数麻烦，弄得自己也情绪恶劣，烦躁不安，一心想要挣脱如蛛网般缠着自己的黑暗。这时她并未将自己的笨拙视作衰老与黑暗的最初胜利，而是归咎于时光的错误。 她想起以前，上帝还没让岁月缩水如同土耳其商人丈量花布时偷减尺寸 ① ，那时候不像现在这样。如今不仅孩子们长得更快，连人的情感也变了样。美人儿蕾梅黛丝连身体带灵魂才升天，凉薄的费尔南达就在角落里踱来踱去，为那些被卷走的床单愤愤不平。奥雷里亚诺们在坟墓里尸骨未寒，奥雷里亚诺第二就又点亮家中的灯火，聚上一群醉汉拉起手风琴，浑身浇透香槟酒，仿佛被害的不是基督徒而只是几条狗，仿佛用无数的操劳和无数的糖果小动物换来的这个疯人之家注定要沦为堕落的垃圾场。她想到这些的时候，家人正为何塞·阿尔卡蒂奥准备行李。乌尔苏拉又不禁自问是否应当索性躺进坟墓让人埋土，并毫无顾忌地质询上帝是否真的认为人心如铁足以经受这许多痛苦的折磨。她问了又问，愈加惶惑，并感到无可抑制的强烈欲望涌上心头，想要像外乡人一样破口大骂，想要让自己最终能放任片刻，那是她渴求已久却反复拖延的时刻，在这一时刻她不再逆来顺受，而要痛骂一场，把整整一个世纪忍气吞声压在心底的无数污言秽语一吐为快。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3365, 86, 76, 14, 14, '第14章
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3374, 86, 85, 15, 15, '水渠被鲜血染红。依然健在的布朗先生，连同家人及其他同胞被送出电网鸡笼，抵达军队保护下的安全区。眼看一场血腥恶战一触即发，当局发出通告，呼吁工人们到马孔多集合。通告中宣布，省军政主席将于下星期五前来调解争端。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3384, 86, 95, 17, 17, '奥雷里亚诺第二忙于经营彩票生意，几乎没有时间去看望孩子。费尔南达把阿玛兰妲·乌尔苏拉送到一所只收六名学生的私立学校，但连公立学校也不许奥雷里亚诺上。在她看来，任由他走出房间已经是莫大的让步。另外，当时的学校只接收天主教婚姻中诞生的合法子女，而奥雷里亚诺被送来时，外罩衣上用别针系着的出生证书注明他是弃婴。因此他被关起来，全靠桑塔索菲亚·德拉·彼达的好心看护和乌尔苏拉间或清醒时的照管，通过老祖母们的解说逐渐认识了家中的狭小世界。他面容清秀，身材修长，好奇之强常常将大人们惹恼，但他那闪烁的眼神却与上校在他这个年龄时刨根问底、有时洞察一切的目光不同，显得有些漫不经心。阿玛兰妲·乌尔苏拉上幼儿园的时候，他就在花园里寻捉蚯蚓折磨虫子。有一次，他把蝎子装进盒子准备放到乌尔苏拉的床席上，被费尔南达当场抓到，关进以前梅梅的卧室，他便在那里翻看百科全书里的插图打发孤寂的时光。一天下午，乌尔苏拉拿着荨麻枝在家中四处洒过夜的凉水。她明明已经见过多次，这时仍问他是谁。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3380, 86, 91, 16, 16, '“这可不是真的，”奥雷里亚诺第二打断了她的话，“他被送来的时候都臭了。”
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3385, 86, 96, 17, 17, '“连话也说不出，”奥雷里亚诺说，“像只小蟋蟀似的死了。”于是乌尔苏拉在事实面前屈服了。“上帝啊，”她低声叫道，“原来死就是这个样子。”她开始一场漫长、急迫、深切的祈祷，足足持续了两天多，到星期二的时候那祷词已经沦为诚心祈求与实用忠告的混合：不要让红蚂蚁毁掉房子，不要让蕾梅黛丝照片前的长明灯熄灭，不要让布恩迪亚家的人近亲结婚，生下长猪尾巴的孩子。奥雷里亚诺第二试图利用她呓语的当儿求她说出藏金币的地方，但恳求再一次落空。“等主人出现的时候，”乌尔苏拉说，“上帝必然会带领他找到。”桑塔索菲亚·德拉·彼达猜到她随时会离开人世，因为这些天来已经观察到自然事物的异常：玫瑰发出土荆芥的气味;·一个加拉巴木果壳杯失手掉落，鹰嘴豆和谷粒洒落在地排列出完美的几何图形，组成海星形状；一天晚上她还看见夜空中有一排发光的橙色圆盘飞过。
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at", "quality_screen_status", "quality_screen_reason", "quality_screen_prompt_version", "quality_screen_meta_json") OVERRIDING SYSTEM VALUE VALUES (3387, 86, 98, 17, 17, '埋下母鸡六个月后，奥雷里亚诺第二半夜在咳嗽中醒来，感觉像有一对蟹螯正扼住自己的咽喉。这时他明白无论销毁多少魔法子宫托，浸湿多少驱邪的母鸡，都没法改变一个简单而悲哀的事实：他快要死了。他没有告诉任何人。他满心担忧死前不能送阿玛兰妲·乌尔苏拉去布鲁塞尔，于是比以往任何时候更卖力地干活，把彩票销售从每星期一次增加到三次。每天一早就能看见他在市镇上奔走，连最偏僻最穷苦的街区也不放过，那种迫不及待的势头只能在垂死之人身上看到。“天赐彩票到了，”他吆喝着，“大好机会别错过，一百年就这一次。”他竭力装出快活、亲切又健谈的样子，但只要看看他的冷汗和苍白脸色就知道他是在勉强支撑。有时他躲到无人看见的荒地上，坐下来忍着体内魔爪带来的撕心裂肺的剧痛喘息片刻。直到半夜他还在花街柳巷游走，向那些伴着唱机抽泣的孤独女郎努力兜售好运。“这个号已经四个月没出啦，”他边说边展示手中的彩票，“别错过机会，人生比你想象的要短。”后来人们对他失去了敬意，开始取笑他，最后几个月都不再像一直以来那样称他堂奥雷里亚诺，而是当面叫他堂“天赐”先生。他喉间杂音日增，说话渐渐走调，最后喑哑嘶叫如狗，但仍努力使人们对佩特拉·科特斯院中的开彩保持兴趣。然而彻底失声时，他意识到自己即将被剧痛压垮，同时也明白靠猪羊彩票无法将女儿送去布鲁塞尔，因此突发奇想，要拿被暴雨毁坏的土地来举行一场豪华抽彩，那些土地只要有资金投人就能重新派上用场。这一想法手笔之大，甚至惊动了市长亲自颁发公告。人们合伙购买面额一百比索的彩票，一个星期之内就抢购一空。开彩当晚，中彩者举办了一场盛大的欢庆会，堪与香蕉公司黄金时代的聚会相媲美。奥雷里亚诺第二最后一次拉起手风琴，演奏好汉弗朗西斯科已被人遗忘的歌曲，只是他再也无法伴唱。
